PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE IF NOT EXISTS "django_migrations" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "app" varchar(255) NOT NULL, "name" varchar(255) NOT NULL, "applied" datetime NOT NULL);
CREATE TABLE IF NOT EXISTS "django_content_type" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "app_label" varchar(100) NOT NULL, "model" varchar(100) NOT NULL);
CREATE TABLE IF NOT EXISTS "auth_group_permissions" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "group_id" integer NOT NULL REFERENCES "auth_group" ("id") DEFERRABLE INITIALLY DEFERRED, "permission_id" integer NOT NULL REFERENCES "auth_permission" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "auth_permission" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "content_type_id" integer NOT NULL REFERENCES "django_content_type" ("id") DEFERRABLE INITIALLY DEFERRED, "codename" varchar(100) NOT NULL, "name" varchar(255) NOT NULL);
CREATE TABLE IF NOT EXISTS "auth_group" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(150) NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS "backend_auth_user_groups" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "user_id" integer NOT NULL REFERENCES "backend_auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "group_id" integer NOT NULL REFERENCES "auth_group" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "backend_auth_user_user_permissions" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "user_id" integer NOT NULL REFERENCES "backend_auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "permission_id" integer NOT NULL REFERENCES "auth_permission" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "cms_globalpagepermission" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "can_change" bool NOT NULL, "can_add" bool NOT NULL, "can_delete" bool NOT NULL, "can_change_advanced_settings" bool NOT NULL, "can_publish" bool NOT NULL, "can_change_permissions" bool NOT NULL, "can_move_page" bool NOT NULL, "can_view" bool NOT NULL, "can_recover_page" bool NOT NULL, "group_id" integer NULL REFERENCES "auth_group" ("id") DEFERRABLE INITIALLY DEFERRED, "user_id" integer NULL REFERENCES "backend_auth_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "cms_pagepermission" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "can_change" bool NOT NULL, "can_add" bool NOT NULL, "can_delete" bool NOT NULL, "can_change_advanced_settings" bool NOT NULL, "can_publish" bool NOT NULL, "can_change_permissions" bool NOT NULL, "can_move_page" bool NOT NULL, "can_view" bool NOT NULL, "grant_on" integer NOT NULL, "group_id" integer NULL REFERENCES "auth_group" ("id") DEFERRABLE INITIALLY DEFERRED, "page_id" integer NULL REFERENCES "cms_page" ("id") DEFERRABLE INITIALLY DEFERRED, "user_id" integer NULL REFERENCES "backend_auth_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "cms_pageuser" ("user_ptr_id" integer NOT NULL PRIMARY KEY REFERENCES "backend_auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "created_by_id" integer NOT NULL REFERENCES "backend_auth_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "cms_pageusergroup" ("group_ptr_id" integer NOT NULL PRIMARY KEY REFERENCES "auth_group" ("id") DEFERRABLE INITIALLY DEFERRED, "created_by_id" integer NOT NULL REFERENCES "backend_auth_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "cms_page_placeholders" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "page_id" integer NOT NULL REFERENCES "cms_page" ("id") DEFERRABLE INITIALLY DEFERRED, "placeholder_id" integer NOT NULL REFERENCES "cms_placeholder" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "cms_staticplaceholder" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(255) NOT NULL, "code" varchar(255) NOT NULL, "dirty" bool NOT NULL, "creation_method" varchar(20) NOT NULL, "draft_id" integer NULL REFERENCES "cms_placeholder" ("id") DEFERRABLE INITIALLY DEFERRED, "public_id" integer NULL REFERENCES "cms_placeholder" ("id") DEFERRABLE INITIALLY DEFERRED, "site_id" integer NULL REFERENCES "django_site" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "cms_placeholder" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "default_width" smallint unsigned NULL CHECK ("default_width" >= 0), "slot" varchar(255) NOT NULL);
CREATE TABLE IF NOT EXISTS "cms_globalpagepermission_sites" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "globalpagepermission_id" integer NOT NULL REFERENCES "cms_globalpagepermission" ("id") DEFERRABLE INITIALLY DEFERRED, "site_id" integer NOT NULL REFERENCES "django_site" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "cms_usersettings" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "language" varchar(10) NOT NULL, "clipboard_id" integer NULL REFERENCES "cms_placeholder" ("id") DEFERRABLE INITIALLY DEFERRED, "user_id" integer NOT NULL UNIQUE REFERENCES "backend_auth_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "cms_urlconfrevision" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "revision" varchar(255) NOT NULL);
CREATE TABLE IF NOT EXISTS "cms_cmsplugin" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "language" varchar(15) NOT NULL, "plugin_type" varchar(50) NOT NULL, "creation_date" datetime NOT NULL, "changed_date" datetime NOT NULL, "placeholder_id" integer NULL REFERENCES "cms_placeholder" ("id") DEFERRABLE INITIALLY DEFERRED, "depth" integer unsigned NOT NULL CHECK ("depth" >= 0), "numchild" integer unsigned NOT NULL CHECK ("numchild" >= 0), "path" varchar(255) NOT NULL UNIQUE, "position" smallint unsigned NOT NULL CHECK ("position" >= 0), "parent_id" integer NULL REFERENCES "cms_cmsplugin" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "cms_aliaspluginmodel" ("plugin_id" integer NULL REFERENCES "cms_cmsplugin" ("id") DEFERRABLE INITIALLY DEFERRED, "alias_placeholder_id" integer NULL REFERENCES "cms_placeholder" ("id") DEFERRABLE INITIALLY DEFERRED, "cmsplugin_ptr_id" integer NOT NULL PRIMARY KEY REFERENCES "cms_cmsplugin" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "cms_placeholderreference" ("name" varchar(255) NOT NULL, "placeholder_ref_id" integer NULL REFERENCES "cms_placeholder" ("id") DEFERRABLE INITIALLY DEFERRED, "cmsplugin_ptr_id" integer NOT NULL PRIMARY KEY REFERENCES "cms_cmsplugin" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "cms_treenode" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "path" varchar(255) NOT NULL UNIQUE, "depth" integer unsigned NOT NULL CHECK ("depth" >= 0), "numchild" integer unsigned NOT NULL CHECK ("numchild" >= 0), "parent_id" integer NULL REFERENCES "cms_treenode" ("id") DEFERRABLE INITIALLY DEFERRED, "site_id" integer NOT NULL REFERENCES "django_site" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "cms_page" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "created_by" varchar(255) NOT NULL, "changed_by" varchar(255) NOT NULL, "creation_date" datetime NOT NULL, "changed_date" datetime NOT NULL, "publication_date" datetime NULL, "publication_end_date" datetime NULL, "in_navigation" bool NOT NULL, "soft_root" bool NOT NULL, "reverse_id" varchar(40) NULL, "navigation_extenders" varchar(80) NULL, "template" varchar(100) NOT NULL, "login_required" bool NOT NULL, "limit_visibility_in_menu" smallint NULL, "is_home" bool NOT NULL, "application_urls" varchar(200) NULL, "application_namespace" varchar(200) NULL, "publisher_is_draft" bool NOT NULL, "languages" varchar(255) NULL, "xframe_options" integer NOT NULL, "is_page_type" bool NOT NULL, "node_id" integer NOT NULL REFERENCES "cms_treenode" ("id") DEFERRABLE INITIALLY DEFERRED, "publisher_public_id" integer NULL UNIQUE REFERENCES "cms_page" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "cms_title" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "language" varchar(15) NOT NULL, "title" varchar(255) NOT NULL, "page_title" varchar(255) NULL, "menu_title" varchar(255) NULL, "slug" varchar(255) NOT NULL, "path" varchar(255) NOT NULL, "has_url_overwrite" bool NOT NULL, "redirect" varchar(2048) NULL, "creation_date" datetime NOT NULL, "published" bool NOT NULL, "publisher_is_draft" bool NOT NULL, "publisher_state" smallint NOT NULL, "page_id" integer NOT NULL REFERENCES "cms_page" ("id") DEFERRABLE INITIALLY DEFERRED, "meta_description" text NULL, "publisher_public_id" integer NULL UNIQUE REFERENCES "cms_title" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "djangocms_frontend_frontenduiitem" ("cmsplugin_ptr_id" integer NOT NULL PRIMARY KEY REFERENCES "cms_cmsplugin" ("id") DEFERRABLE INITIALLY DEFERRED, "ui_item" varchar(30) NOT NULL, "tag_type" varchar(255) NOT NULL, "config" text NOT NULL CHECK ((JSON_VALID("config") OR "config" IS NULL)));
CREATE TABLE IF NOT EXISTS "account_emailconfirmation" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "created" datetime NOT NULL, "sent" datetime NULL, "key" varchar(64) NOT NULL UNIQUE, "email_address_id" integer NOT NULL REFERENCES "account_emailaddress" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "account_emailaddress" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "verified" bool NOT NULL, "primary" bool NOT NULL, "user_id" integer NOT NULL REFERENCES "backend_auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "email" varchar(254) NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS "django_admin_log" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "object_id" text NULL, "object_repr" varchar(200) NOT NULL, "action_flag" smallint unsigned NOT NULL CHECK ("action_flag" >= 0), "change_message" text NOT NULL, "content_type_id" integer NULL REFERENCES "django_content_type" ("id") DEFERRABLE INITIALLY DEFERRED, "user_id" integer NOT NULL REFERENCES "backend_auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "action_time" datetime NOT NULL);
CREATE TABLE IF NOT EXISTS "filer_folderpermission" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "type" smallint NOT NULL, "everybody" bool NOT NULL, "can_edit" smallint NULL, "can_read" smallint NULL, "can_add_children" smallint NULL, "folder_id" integer NULL REFERENCES "filer_folder" ("id") DEFERRABLE INITIALLY DEFERRED, "group_id" integer NULL REFERENCES "auth_group" ("id") DEFERRABLE INITIALLY DEFERRED, "user_id" integer NULL REFERENCES "backend_auth_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "filer_clipboarditem" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "clipboard_id" integer NOT NULL REFERENCES "filer_clipboard" ("id") DEFERRABLE INITIALLY DEFERRED, "file_id" integer NOT NULL REFERENCES "filer_file" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "filer_clipboard" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "user_id" integer NOT NULL REFERENCES "backend_auth_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "aldryn_forms_formplugin_recipients" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "formplugin_id" integer NOT NULL REFERENCES "aldryn_forms_formplugin" ("cmsplugin_ptr_id") DEFERRABLE INITIALLY DEFERRED, "user_id" integer NOT NULL REFERENCES "backend_auth_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "aldryn_forms_fieldsetplugin" ("cmsplugin_ptr_id" integer NOT NULL PRIMARY KEY REFERENCES "cms_cmsplugin" ("id") DEFERRABLE INITIALLY DEFERRED, "custom_classes" varchar(255) NOT NULL, "legend" varchar(255) NOT NULL);
CREATE TABLE IF NOT EXISTS "aldryn_forms_formbuttonplugin" ("cmsplugin_ptr_id" integer NOT NULL PRIMARY KEY REFERENCES "cms_cmsplugin" ("id") DEFERRABLE INITIALLY DEFERRED, "custom_classes" varchar(255) NOT NULL, "label" varchar(255) NOT NULL);
CREATE TABLE IF NOT EXISTS "aldryn_forms_emailfieldplugin" ("cmsplugin_ptr_id" integer NOT NULL PRIMARY KEY REFERENCES "cms_cmsplugin" ("id") DEFERRABLE INITIALLY DEFERRED, "label" varchar(255) NOT NULL, "required" bool NOT NULL, "required_message" text NULL, "placeholder_text" varchar(255) NOT NULL, "help_text" text NULL, "min_value" integer unsigned NULL CHECK ("min_value" >= 0), "max_value" integer unsigned NULL CHECK ("max_value" >= 0), "custom_classes" varchar(255) NOT NULL, "email_send_notification" bool NOT NULL, "email_subject" varchar(255) NOT NULL, "email_body" text NOT NULL, "attributes" text NOT NULL, "initial_value" varchar(255) NOT NULL, "name" varchar(255) NOT NULL);
CREATE TABLE IF NOT EXISTS "aldryn_forms_fieldplugin" ("cmsplugin_ptr_id" integer NOT NULL PRIMARY KEY REFERENCES "cms_cmsplugin" ("id") DEFERRABLE INITIALLY DEFERRED, "label" varchar(255) NOT NULL, "required" bool NOT NULL, "required_message" text NULL, "placeholder_text" varchar(255) NOT NULL, "help_text" text NULL, "min_value" integer unsigned NULL CHECK ("min_value" >= 0), "max_value" integer unsigned NULL CHECK ("max_value" >= 0), "custom_classes" varchar(255) NOT NULL, "attributes" text NOT NULL, "initial_value" varchar(255) NOT NULL, "name" varchar(255) NOT NULL);
CREATE TABLE IF NOT EXISTS "aldryn_forms_fileuploadfieldplugin" ("cmsplugin_ptr_id" integer NOT NULL PRIMARY KEY REFERENCES "cms_cmsplugin" ("id") DEFERRABLE INITIALLY DEFERRED, "label" varchar(255) NOT NULL, "required" bool NOT NULL, "required_message" text NULL, "placeholder_text" varchar(255) NOT NULL, "help_text" text NULL, "min_value" integer unsigned NULL CHECK ("min_value" >= 0), "max_value" integer unsigned NULL CHECK ("max_value" >= 0), "custom_classes" varchar(255) NOT NULL, "max_size" bigint NULL, "upload_to_id" integer NOT NULL REFERENCES "filer_folder" ("id") DEFERRABLE INITIALLY DEFERRED, "attributes" text NOT NULL, "initial_value" varchar(255) NOT NULL, "name" varchar(255) NOT NULL);
CREATE TABLE IF NOT EXISTS "aldryn_forms_imageuploadfieldplugin" ("cmsplugin_ptr_id" integer NOT NULL PRIMARY KEY REFERENCES "cms_cmsplugin" ("id") DEFERRABLE INITIALLY DEFERRED, "label" varchar(255) NOT NULL, "required" bool NOT NULL, "required_message" text NULL, "placeholder_text" varchar(255) NOT NULL, "help_text" text NULL, "min_value" integer unsigned NULL CHECK ("min_value" >= 0), "max_value" integer unsigned NULL CHECK ("max_value" >= 0), "custom_classes" varchar(255) NOT NULL, "max_size" bigint NULL, "max_width" integer unsigned NULL CHECK ("max_width" >= 0), "max_height" integer unsigned NULL CHECK ("max_height" >= 0), "upload_to_id" integer NOT NULL REFERENCES "filer_folder" ("id") DEFERRABLE INITIALLY DEFERRED, "attributes" text NOT NULL, "initial_value" varchar(255) NOT NULL, "name" varchar(255) NOT NULL);
CREATE TABLE IF NOT EXISTS "aldryn_forms_textareafieldplugin" ("cmsplugin_ptr_id" integer NOT NULL PRIMARY KEY REFERENCES "cms_cmsplugin" ("id") DEFERRABLE INITIALLY DEFERRED, "label" varchar(255) NOT NULL, "required" bool NOT NULL, "required_message" text NULL, "placeholder_text" varchar(255) NOT NULL, "help_text" text NULL, "min_value" integer unsigned NULL CHECK ("min_value" >= 0), "max_value" integer unsigned NULL CHECK ("max_value" >= 0), "custom_classes" varchar(255) NOT NULL, "text_area_columns" integer unsigned NULL CHECK ("text_area_columns" >= 0), "text_area_rows" integer unsigned NULL CHECK ("text_area_rows" >= 0), "attributes" text NOT NULL, "initial_value" varchar(255) NOT NULL, "name" varchar(255) NOT NULL);
CREATE TABLE IF NOT EXISTS "aldryn_forms_formplugin" ("cmsplugin_ptr_id" integer NOT NULL PRIMARY KEY REFERENCES "cms_cmsplugin" ("id") DEFERRABLE INITIALLY DEFERRED, "name" varchar(255) NOT NULL, "error_message" text NULL, "success_message" text NULL, "redirect_type" varchar(20) NOT NULL, "url" varchar(200) NULL, "custom_classes" varchar(255) NOT NULL, "form_template" varchar(255) NOT NULL, "redirect_page_id" integer NULL REFERENCES "cms_page" ("id") DEFERRABLE INITIALLY DEFERRED, "form_attributes" text NOT NULL, "action_backend" varchar(15) NOT NULL, "is_enable_autofill_from_url_params" bool NOT NULL);
CREATE TABLE IF NOT EXISTS "aldryn_forms_formsubmission" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(255) NOT NULL, "data" text NOT NULL, "recipients" text NOT NULL, "language" varchar(10) NOT NULL, "form_url" varchar(255) NOT NULL, "sent_at" datetime NOT NULL);
CREATE TABLE IF NOT EXISTS "aldryn_forms_option" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "value" varchar(255) NOT NULL, "default_value" bool NOT NULL, "field_id" integer NOT NULL REFERENCES "aldryn_forms_fieldplugin" ("cmsplugin_ptr_id") DEFERRABLE INITIALLY DEFERRED, "position" integer unsigned NOT NULL CHECK ("position" >= 0));
CREATE TABLE IF NOT EXISTS "aldryn_sso_aldrynclouduser" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "cloud_id" integer unsigned NOT NULL UNIQUE CHECK ("cloud_id" >= 0), "user_id" integer NOT NULL UNIQUE REFERENCES "backend_auth_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "backend_auth_user" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "password" varchar(128) NOT NULL, "last_login" datetime NULL, "is_superuser" bool NOT NULL, "email" varchar(254) NOT NULL UNIQUE, "username" varchar(128) NOT NULL, "first_name" varchar(150) NOT NULL, "last_name" varchar(150) NOT NULL, "is_staff" bool NOT NULL, "is_active" bool NOT NULL, "date_joined" datetime NOT NULL);
CREATE TABLE IF NOT EXISTS "products" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "photo" varchar(100) NOT NULL, "name" varchar(100) NOT NULL, "price" integer unsigned NOT NULL CHECK ("price" >= 0), "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL, "is_published" bool NOT NULL, "description" text NOT NULL);
CREATE TABLE IF NOT EXISTS "bs4_float_floatmodel" ("cmsplugin_ptr_id" integer NOT NULL PRIMARY KEY REFERENCES "cms_cmsplugin" ("id") DEFERRABLE INITIALLY DEFERRED, "float_direction" varchar(256) NOT NULL, "float_breakpoint" varchar(256) NOT NULL, "margin_top" integer unsigned NOT NULL CHECK ("margin_top" >= 0), "margin_right" integer unsigned NOT NULL CHECK ("margin_right" >= 0), "margin_bottom" integer unsigned NOT NULL CHECK ("margin_bottom" >= 0), "margin_left" integer unsigned NOT NULL CHECK ("margin_left" >= 0));
CREATE TABLE IF NOT EXISTS "bs4_hiding_bootstrap4hidepluginmodel" ("cmsplugin_ptr_id" integer NOT NULL PRIMARY KEY REFERENCES "cms_cmsplugin" ("id") DEFERRABLE INITIALLY DEFERRED, "hide_on_very_small_devices" bool NOT NULL, "hide_on_small_devices" bool NOT NULL, "hide_on_medium_devices" bool NOT NULL, "hide_on_large_devices" bool NOT NULL, "hide_on_very_large_devices" bool NOT NULL);
CREATE TABLE IF NOT EXISTS "bs4_inline_alignment_inlinealignmentmodel" ("cmsplugin_ptr_id" integer NOT NULL PRIMARY KEY REFERENCES "cms_cmsplugin" ("id") DEFERRABLE INITIALLY DEFERRED, "alignment" varchar(256) NULL, "alignment_sm" varchar(256) NULL, "alignment_md" varchar(256) NULL, "alignment_lg" varchar(256) NULL, "alignment_xl" varchar(256) NULL);
CREATE TABLE IF NOT EXISTS "bs4_spacer_verticalspacerplugin" ("cmsplugin_ptr_id" integer NOT NULL PRIMARY KEY REFERENCES "cms_cmsplugin" ("id") DEFERRABLE INITIALLY DEFERRED, "smart_space" integer unsigned NOT NULL CHECK ("smart_space" >= 0), "space_xs" integer unsigned NULL CHECK ("space_xs" >= 0), "space_sm" integer unsigned NULL CHECK ("space_sm" >= 0), "space_md" integer unsigned NULL CHECK ("space_md" >= 0), "space_lg" integer unsigned NULL CHECK ("space_lg" >= 0), "space_xl" integer unsigned NULL CHECK ("space_xl" >= 0));
CREATE TABLE IF NOT EXISTS "filer_thumbnailoption" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(100) NOT NULL, "width" integer NOT NULL, "height" integer NOT NULL, "crop" bool NOT NULL, "upscale" bool NOT NULL);
CREATE TABLE IF NOT EXISTS "taggit_taggeditem" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "object_id" integer NOT NULL, "content_type_id" integer NOT NULL REFERENCES "django_content_type" ("id") DEFERRABLE INITIALLY DEFERRED, "tag_id" integer NOT NULL REFERENCES "taggit_tag" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "djangocms_blog_authorentriesplugin_authors" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "authorentriesplugin_id" integer NOT NULL REFERENCES "djangocms_blog_authorentriesplugin" ("cmsplugin_ptr_id") DEFERRABLE INITIALLY DEFERRED, "user_id" bigint NOT NULL REFERENCES "backend_auth_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "djangocms_blog_latestpostsplugin_categories" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "latestpostsplugin_id" integer NOT NULL REFERENCES "djangocms_blog_latestpostsplugin" ("cmsplugin_ptr_id") DEFERRABLE INITIALLY DEFERRED, "blogcategory_id" integer NOT NULL REFERENCES "djangocms_blog_blogcategory" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "djangocms_blog_post_categories" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "post_id" integer NOT NULL REFERENCES "djangocms_blog_post" ("id") DEFERRABLE INITIALLY DEFERRED, "blogcategory_id" integer NOT NULL REFERENCES "djangocms_blog_blogcategory" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "djangocms_blog_post_sites" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "post_id" integer NOT NULL REFERENCES "djangocms_blog_post" ("id") DEFERRABLE INITIALLY DEFERRED, "site_id" integer NOT NULL REFERENCES "django_site" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "djangocms_blog_authorentriesplugin" ("cmsplugin_ptr_id" integer NOT NULL PRIMARY KEY REFERENCES "cms_cmsplugin" ("id") DEFERRABLE INITIALLY DEFERRED, "latest_posts" integer NOT NULL, "app_config_id" integer NULL REFERENCES "djangocms_blog_blogconfig" ("id") DEFERRABLE INITIALLY DEFERRED, "current_site" bool NOT NULL, "template_folder" varchar(200) NOT NULL);
CREATE TABLE IF NOT EXISTS "djangocms_blog_genericblogplugin" ("cmsplugin_ptr_id" integer NOT NULL PRIMARY KEY REFERENCES "cms_cmsplugin" ("id") DEFERRABLE INITIALLY DEFERRED, "app_config_id" integer NULL REFERENCES "djangocms_blog_blogconfig" ("id") DEFERRABLE INITIALLY DEFERRED, "current_site" bool NOT NULL, "template_folder" varchar(200) NOT NULL);
CREATE TABLE IF NOT EXISTS "djangocms_blog_latestpostsplugin" ("cmsplugin_ptr_id" integer NOT NULL PRIMARY KEY REFERENCES "cms_cmsplugin" ("id") DEFERRABLE INITIALLY DEFERRED, "latest_posts" integer NOT NULL, "app_config_id" integer NULL REFERENCES "djangocms_blog_blogconfig" ("id") DEFERRABLE INITIALLY DEFERRED, "current_site" bool NOT NULL, "template_folder" varchar(200) NOT NULL);
CREATE TABLE IF NOT EXISTS "djangocms_blog_post_related" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "from_post_id" integer NOT NULL REFERENCES "djangocms_blog_post" ("id") DEFERRABLE INITIALLY DEFERRED, "to_post_id" integer NOT NULL REFERENCES "djangocms_blog_post" ("id") DEFERRABLE INITIALLY DEFERRED, "sort_value" integer NOT NULL);
CREATE TABLE IF NOT EXISTS "djangocms_blog_blogcategory" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "date_created" datetime NOT NULL, "date_modified" datetime NOT NULL, "app_config_id" integer NULL REFERENCES "djangocms_blog_blogconfig" ("id") DEFERRABLE INITIALLY DEFERRED, "parent_id" bigint NULL REFERENCES "djangocms_blog_blogcategory" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "djangocms_blog_blogcategory_translation" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "language_code" varchar(15) NOT NULL, "name" varchar(752) NOT NULL, "slug" varchar(752) NOT NULL, "master_id" bigint NULL REFERENCES "djangocms_blog_blogcategory" ("id") DEFERRABLE INITIALLY DEFERRED, "meta_description" text NOT NULL);
CREATE TABLE IF NOT EXISTS "djangocms_blog_blogconfig" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "type" varchar(100) NOT NULL, "namespace" varchar(100) NOT NULL UNIQUE, "app_data" text NOT NULL);
CREATE TABLE IF NOT EXISTS "djangocms_blog_blogconfig_translation" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "language_code" varchar(15) NOT NULL, "app_title" varchar(234) NOT NULL, "master_id" bigint NULL REFERENCES "djangocms_blog_blogconfig" ("id") DEFERRABLE INITIALLY DEFERRED, "object_name" varchar(234) NOT NULL);
CREATE TABLE IF NOT EXISTS "djangocms_blog_post" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "date_created" datetime NOT NULL, "date_modified" datetime NOT NULL, "date_published" datetime NULL, "date_published_end" datetime NULL, "publish" bool NOT NULL, "enable_comments" bool NOT NULL, "author_id" bigint NULL REFERENCES "backend_auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "content_id" integer NULL REFERENCES "cms_placeholder" ("id") DEFERRABLE INITIALLY DEFERRED, "main_image_id" integer NULL REFERENCES "filer_image" ("file_ptr_id") DEFERRABLE INITIALLY DEFERRED, "app_config_id" bigint NULL REFERENCES "djangocms_blog_blogconfig" ("id") DEFERRABLE INITIALLY DEFERRED, "main_image_full_id" integer NULL REFERENCES "filer_thumbnailoption" ("id") DEFERRABLE INITIALLY DEFERRED, "main_image_thumbnail_id" integer NULL REFERENCES "filer_thumbnailoption" ("id") DEFERRABLE INITIALLY DEFERRED, "liveblog_id" integer NULL REFERENCES "cms_placeholder" ("id") DEFERRABLE INITIALLY DEFERRED, "enable_liveblog" bool NOT NULL, "date_featured" datetime NULL, "media_id" integer NULL REFERENCES "cms_placeholder" ("id") DEFERRABLE INITIALLY DEFERRED, "include_in_rss" bool NOT NULL);
CREATE TABLE IF NOT EXISTS "djangocms_blog_post_translation" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "language_code" varchar(15) NOT NULL, "title" varchar(752) NOT NULL, "slug" varchar(752) NOT NULL, "abstract" text NOT NULL, "meta_description" text NOT NULL, "meta_keywords" text NOT NULL, "meta_title" varchar(2000) NOT NULL, "post_text" text NOT NULL, "master_id" bigint NULL REFERENCES "djangocms_blog_post" ("id") DEFERRABLE INITIALLY DEFERRED, "subtitle" varchar(767) NOT NULL);
CREATE TABLE IF NOT EXISTS "djangocms_blog_featuredpostsplugin" ("cmsplugin_ptr_id" integer NOT NULL PRIMARY KEY REFERENCES "cms_cmsplugin" ("id") DEFERRABLE INITIALLY DEFERRED, "current_site" bool NOT NULL, "template_folder" varchar(200) NOT NULL, "app_config_id" bigint NULL REFERENCES "djangocms_blog_blogconfig" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "djangocms_blog_featuredpostsplugin_posts" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "sort_value" integer NOT NULL, "featuredpostsplugin_id" integer NOT NULL REFERENCES "djangocms_blog_featuredpostsplugin" ("cmsplugin_ptr_id") DEFERRABLE INITIALLY DEFERRED, "post_id" bigint NOT NULL REFERENCES "djangocms_blog_post" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "djangocms_file_folder" ("template" varchar(255) NOT NULL, "link_target" varchar(255) NOT NULL, "show_file_size" bool NOT NULL, "attributes" text NOT NULL, "cmsplugin_ptr_id" integer NOT NULL PRIMARY KEY REFERENCES "cms_cmsplugin" ("id") DEFERRABLE INITIALLY DEFERRED, "folder_src_id" integer NULL REFERENCES "filer_folder" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "djangocms_file_file" ("cmsplugin_ptr_id" integer NOT NULL PRIMARY KEY REFERENCES "cms_cmsplugin" ("id") DEFERRABLE INITIALLY DEFERRED, "file_src_id" integer NULL REFERENCES "filer_file" ("id") DEFERRABLE INITIALLY DEFERRED, "attributes" text NOT NULL, "template" varchar(255) NOT NULL, "link_target" varchar(255) NOT NULL, "link_title" varchar(255) NOT NULL, "show_file_size" bool NOT NULL, "file_name" varchar(255) NOT NULL);
CREATE TABLE IF NOT EXISTS "djangocms_googlemap_googlemaproute" ("cmsplugin_ptr_id" integer NOT NULL PRIMARY KEY REFERENCES "cms_cmsplugin" ("id") DEFERRABLE INITIALLY DEFERRED, "title" varchar(255) NOT NULL, "origin" varchar(255) NOT NULL, "destination" varchar(255) NOT NULL, "travel_mode" varchar(255) NOT NULL);
CREATE TABLE IF NOT EXISTS "djangocms_googlemap_googlemapmarker" ("cmsplugin_ptr_id" integer NOT NULL PRIMARY KEY REFERENCES "cms_cmsplugin" ("id") DEFERRABLE INITIALLY DEFERRED, "title" varchar(255) NOT NULL, "address" varchar(255) NOT NULL, "lat" real NULL, "show_content" bool NOT NULL, "info_content" text NOT NULL, "icon_id" integer NULL REFERENCES "filer_image" ("file_ptr_id") DEFERRABLE INITIALLY DEFERRED, "lng" real NULL);
CREATE TABLE IF NOT EXISTS "djangocms_googlemap_googlemap" ("cmsplugin_ptr_id" integer NOT NULL PRIMARY KEY REFERENCES "cms_cmsplugin" ("id") DEFERRABLE INITIALLY DEFERRED, "title" varchar(255) NOT NULL, "zoom" smallint unsigned NOT NULL CHECK ("zoom" >= 0), "lat" real NULL, "lng" real NULL, "width" varchar(6) NOT NULL, "height" varchar(6) NOT NULL, "scrollwheel" bool NOT NULL, "double_click_zoom" bool NOT NULL, "draggable" bool NOT NULL, "keyboard_shortcuts" bool NOT NULL, "pan_control" bool NOT NULL, "zoom_control" bool NOT NULL, "street_view_control" bool NOT NULL, "style" text NOT NULL, "fullscreen_control" bool NOT NULL, "map_type_control" varchar(255) NOT NULL, "rotate_control" bool NOT NULL, "scale_control" bool NOT NULL, "template" varchar(255) NOT NULL, "map_id" varchar(32) NOT NULL);
CREATE TABLE IF NOT EXISTS "djangocms_history_placeholderaction" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "action" varchar(30) NOT NULL, "pre_action_data" text NOT NULL, "post_action_data" text NOT NULL, "language" varchar(15) NOT NULL, "order" integer unsigned NOT NULL CHECK ("order" >= 0), "operation_id" integer NOT NULL REFERENCES "djangocms_history_placeholderoperation" ("id") DEFERRABLE INITIALLY DEFERRED, "placeholder_id" integer NOT NULL REFERENCES "cms_placeholder" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "djangocms_history_placeholderoperation" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "operation_type" varchar(30) NOT NULL, "token" varchar(120) NOT NULL, "origin" varchar(255) NOT NULL, "language" varchar(15) NOT NULL, "user_session_key" varchar(120) NOT NULL, "date_created" datetime NOT NULL, "is_applied" bool NOT NULL, "is_archived" bool NOT NULL, "site_id" integer NOT NULL REFERENCES "django_site" ("id") DEFERRABLE INITIALLY DEFERRED, "user_id" bigint NOT NULL REFERENCES "backend_auth_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "djangocms_link_link" ("cmsplugin_ptr_id" integer NOT NULL PRIMARY KEY REFERENCES "cms_cmsplugin" ("id") DEFERRABLE INITIALLY DEFERRED, "name" varchar(255) NOT NULL, "anchor" varchar(255) NOT NULL, "mailto" varchar(255) NOT NULL, "phone" varchar(255) NOT NULL, "target" varchar(255) NOT NULL, "attributes" text NOT NULL, "template" varchar(255) NOT NULL, "internal_link_id" integer NULL REFERENCES "cms_page" ("id") DEFERRABLE INITIALLY DEFERRED, "file_link_id" integer NULL REFERENCES "filer_file" ("id") DEFERRABLE INITIALLY DEFERRED, "external_link" varchar(2040) NOT NULL);
CREATE TABLE IF NOT EXISTS "djangocms_modules_category" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(120) NOT NULL UNIQUE, "modules_id" integer NULL REFERENCES "cms_placeholder" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "djangocms_modules_moduleplugin" ("cmsplugin_ptr_id" integer NOT NULL PRIMARY KEY REFERENCES "cms_cmsplugin" ("id") DEFERRABLE INITIALLY DEFERRED, "module_name" varchar(120) NOT NULL, "module_category_id" integer NOT NULL REFERENCES "djangocms_modules_category" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "djangocms_page_meta_genericmetaattribute" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "attribute" varchar(200) NOT NULL, "name" varchar(200) NOT NULL, "value" varchar(2000) NOT NULL, "page_id" integer NULL REFERENCES "djangocms_page_meta_pagemeta" ("id") DEFERRABLE INITIALLY DEFERRED, "title_id" integer NULL REFERENCES "djangocms_page_meta_titlemeta" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "djangocms_page_meta_pagemeta" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "og_type" varchar(255) NOT NULL, "og_author_url" varchar(255) NOT NULL, "og_author_fbid" varchar(16) NOT NULL, "og_publisher" varchar(255) NOT NULL, "og_app_id" varchar(255) NOT NULL, "twitter_author" varchar(255) NOT NULL, "twitter_site" varchar(255) NOT NULL, "twitter_type" varchar(255) NOT NULL, "extended_object_id" integer NOT NULL UNIQUE REFERENCES "cms_page" ("id") DEFERRABLE INITIALLY DEFERRED, "image_id" integer NULL REFERENCES "filer_file" ("id") DEFERRABLE INITIALLY DEFERRED, "og_author_id" bigint NULL REFERENCES "backend_auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "fb_pages" varchar(255) NOT NULL, "schemaorg_type" varchar(255) NOT NULL, "robots" varchar(512) NOT NULL, "public_extension_id" bigint NULL UNIQUE REFERENCES "djangocms_page_meta_pagemeta" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "djangocms_page_meta_titlemeta" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "keywords" varchar(2000) NOT NULL, "description" varchar(2000) NOT NULL, "og_description" varchar(2000) NOT NULL, "twitter_description" varchar(2000) NOT NULL, "extended_object_id" integer NOT NULL UNIQUE REFERENCES "cms_title" ("id") DEFERRABLE INITIALLY DEFERRED, "image_id" integer NULL REFERENCES "filer_file" ("id") DEFERRABLE INITIALLY DEFERRED, "schemaorg_description" varchar(255) NOT NULL, "schemaorg_name" varchar(255) NOT NULL, "public_extension_id" bigint NULL UNIQUE REFERENCES "djangocms_page_meta_titlemeta" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "djangocms_picture_picture" ("cmsplugin_ptr_id" integer NOT NULL PRIMARY KEY REFERENCES "cms_cmsplugin" ("id") DEFERRABLE INITIALLY DEFERRED, "height" integer unsigned NULL CHECK ("height" >= 0), "width" integer unsigned NULL CHECK ("width" >= 0), "picture_id" integer NULL REFERENCES "filer_image" ("file_ptr_id") DEFERRABLE INITIALLY DEFERRED, "attributes" text NOT NULL, "caption_text" text NULL, "link_attributes" text NOT NULL, "link_target" varchar(255) NOT NULL, "use_automatic_scaling" bool NOT NULL, "use_crop" bool NOT NULL, "use_no_cropping" bool NOT NULL, "use_upscale" bool NOT NULL, "thumbnail_options_id" integer NULL REFERENCES "filer_thumbnailoption" ("id") DEFERRABLE INITIALLY DEFERRED, "external_picture" varchar(255) NULL, "template" varchar(255) NOT NULL, "alignment" varchar(255) NOT NULL, "link_page_id" integer NULL REFERENCES "cms_page" ("id") DEFERRABLE INITIALLY DEFERRED, "use_responsive_image" varchar(7) NOT NULL, "link_url" varchar(2040) NULL);
CREATE TABLE IF NOT EXISTS "django_redirect" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "old_path" varchar(200) NOT NULL, "new_path" varchar(200) NOT NULL, "response_code" varchar(3) NOT NULL, "site_id" integer NOT NULL REFERENCES "django_site" ("id") DEFERRABLE INITIALLY DEFERRED, "catchall_redirect" bool NOT NULL, "subpath_match" bool NOT NULL);
CREATE TABLE IF NOT EXISTS "djangocms_snippet_snippetptr" ("snippet_id" integer NOT NULL REFERENCES "djangocms_snippet_snippet" ("id") DEFERRABLE INITIALLY DEFERRED, "cmsplugin_ptr_id" integer NOT NULL PRIMARY KEY REFERENCES "cms_cmsplugin" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "djangocms_snippet_snippet" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(255) NOT NULL UNIQUE, "html" text NOT NULL, "template" varchar(255) NOT NULL, "slug" varchar(255) NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS "djangocms_socialshare_sociallinkspluginmodel" ("cmsplugin_ptr_id" integer NOT NULL PRIMARY KEY REFERENCES "cms_cmsplugin" ("id") DEFERRABLE INITIALLY DEFERRED, "alignment" varchar(32) NOT NULL, "size" integer NOT NULL, "background_color" varchar(32) NOT NULL);
CREATE TABLE IF NOT EXISTS "djangocms_socialshare_socialsharepluginmodel" ("cmsplugin_ptr_id" integer NOT NULL PRIMARY KEY REFERENCES "cms_cmsplugin" ("id") DEFERRABLE INITIALLY DEFERRED, "alignment" varchar(32) NOT NULL, "size" integer NOT NULL, "background_color" varchar(32) NOT NULL);
CREATE TABLE IF NOT EXISTS "djangocms_socialshare_sociallink" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "type" varchar(32) NOT NULL, "order" integer unsigned NOT NULL CHECK ("order" >= 0), "url" varchar(200) NOT NULL, "plugin_id" integer NOT NULL REFERENCES "djangocms_socialshare_sociallinkspluginmodel" ("cmsplugin_ptr_id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "djangocms_socialshare_socialsharebutton" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "type" varchar(32) NOT NULL, "order" integer unsigned NOT NULL CHECK ("order" >= 0), "plugin_id" integer NOT NULL REFERENCES "djangocms_socialshare_socialsharepluginmodel" ("cmsplugin_ptr_id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "djangocms_text_ckeditor_text" ("body" text NOT NULL, "cmsplugin_ptr_id" integer NOT NULL PRIMARY KEY REFERENCES "cms_cmsplugin" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "djangocms_video_videosource" ("cmsplugin_ptr_id" integer NOT NULL PRIMARY KEY REFERENCES "cms_cmsplugin" ("id") DEFERRABLE INITIALLY DEFERRED, "text_title" varchar(255) NOT NULL, "text_description" text NOT NULL, "attributes" text NOT NULL, "source_file_id" integer NULL REFERENCES "filer_file" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "djangocms_video_videotrack" ("cmsplugin_ptr_id" integer NOT NULL PRIMARY KEY REFERENCES "cms_cmsplugin" ("id") DEFERRABLE INITIALLY DEFERRED, "kind" varchar(255) NOT NULL, "srclang" varchar(255) NOT NULL, "label" varchar(255) NOT NULL, "attributes" text NOT NULL, "src_id" integer NULL REFERENCES "filer_file" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "djangocms_video_videoplayer" ("cmsplugin_ptr_id" integer NOT NULL PRIMARY KEY REFERENCES "cms_cmsplugin" ("id") DEFERRABLE INITIALLY DEFERRED, "embed_link" varchar(255) NOT NULL, "poster_id" integer NULL REFERENCES "filer_image" ("file_ptr_id") DEFERRABLE INITIALLY DEFERRED, "attributes" text NOT NULL, "label" varchar(255) NOT NULL, "template" varchar(255) NOT NULL, "parameters" text NOT NULL);
CREATE TABLE IF NOT EXISTS "easy_thumbnails_source" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "storage_hash" varchar(40) NOT NULL, "name" varchar(255) NOT NULL, "modified" datetime NOT NULL);
CREATE TABLE IF NOT EXISTS "easy_thumbnails_thumbnail" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "storage_hash" varchar(40) NOT NULL, "name" varchar(255) NOT NULL, "modified" datetime NOT NULL, "source_id" integer NOT NULL REFERENCES "easy_thumbnails_source" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "easy_thumbnails_thumbnaildimensions" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "thumbnail_id" integer NOT NULL UNIQUE REFERENCES "easy_thumbnails_thumbnail" ("id") DEFERRABLE INITIALLY DEFERRED, "width" integer unsigned NULL CHECK ("width" >= 0), "height" integer unsigned NULL CHECK ("height" >= 0));
CREATE TABLE IF NOT EXISTS "email_notifications_emailnotification" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "theme" varchar(200) NOT NULL, "to_name" varchar(200) NOT NULL, "to_email" varchar(200) NOT NULL, "from_name" varchar(200) NOT NULL, "from_email" varchar(200) NOT NULL, "subject" varchar(200) NOT NULL, "body_text" text NOT NULL, "body_html" text NOT NULL, "to_user_id" bigint NULL REFERENCES "backend_auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "form_id" integer NOT NULL REFERENCES "aldryn_forms_formplugin" ("cmsplugin_ptr_id") DEFERRABLE INITIALLY DEFERRED, "reply_to_email" varchar(200) NOT NULL);
CREATE TABLE IF NOT EXISTS "filer_file" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "file" varchar(255) NULL, "_file_size" bigint NULL, "sha1" varchar(40) NOT NULL, "has_all_mandatory_data" bool NOT NULL, "original_filename" varchar(255) NULL, "name" varchar(255) NOT NULL, "description" text NULL, "uploaded_at" datetime NOT NULL, "modified_at" datetime NOT NULL, "is_public" bool NOT NULL, "folder_id" integer NULL REFERENCES "filer_folder" ("id") DEFERRABLE INITIALLY DEFERRED, "owner_id" bigint NULL REFERENCES "backend_auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "polymorphic_ctype_id" integer NULL REFERENCES "django_content_type" ("id") DEFERRABLE INITIALLY DEFERRED, "mime_type" varchar(255) NOT NULL);
CREATE TABLE IF NOT EXISTS "filer_folder" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(255) NOT NULL, "uploaded_at" datetime NOT NULL, "created_at" datetime NOT NULL, "modified_at" datetime NOT NULL, "owner_id" bigint NULL REFERENCES "backend_auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "parent_id" integer NULL REFERENCES "filer_folder" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "filer_image" ("file_ptr_id" integer NOT NULL PRIMARY KEY REFERENCES "filer_file" ("id") DEFERRABLE INITIALLY DEFERRED, "_height" real NULL, "_width" real NULL, "date_taken" datetime NULL, "default_alt_text" varchar(255) NULL, "default_caption" varchar(255) NULL, "author" varchar(255) NULL, "must_always_publish_author_credit" bool NOT NULL, "must_always_publish_copyright" bool NOT NULL, "subject_location" varchar(64) NOT NULL, "_transparent" bool NOT NULL);
CREATE TABLE IF NOT EXISTS "horizontal_line_horizontallineplugin" ("cmsplugin_ptr_id" integer NOT NULL PRIMARY KEY REFERENCES "cms_cmsplugin" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "link_all_linkallpluginmodel" ("cmsplugin_ptr_id" integer NOT NULL PRIMARY KEY REFERENCES "cms_cmsplugin" ("id") DEFERRABLE INITIALLY DEFERRED, "link_instance_pk" integer unsigned NULL CHECK ("link_instance_pk" >= 0), "link_url" varchar(1024) NOT NULL, "link_label" varchar(1024) NOT NULL, "link_content_type_id" integer NULL REFERENCES "django_content_type" ("id") DEFERRABLE INITIALLY DEFERRED, "link_is_open_in_new_tab" bool NOT NULL, "link_type" varchar(64) NOT NULL);
CREATE TABLE IF NOT EXISTS "link_all_linkbuttonpluginmodel" ("cmsplugin_ptr_id" integer NOT NULL PRIMARY KEY REFERENCES "cms_cmsplugin" ("id") DEFERRABLE INITIALLY DEFERRED, "link_type" varchar(64) NOT NULL, "link_instance_pk" integer unsigned NULL CHECK ("link_instance_pk" >= 0), "link_url" varchar(1024) NOT NULL, "link_label" varchar(1024) NOT NULL, "link_is_open_in_new_tab" bool NOT NULL, "link_is_button" bool NOT NULL, "link_button_color" varchar(64) NOT NULL, "link_is_button_full_width" bool NOT NULL, "link_is_button_outlined" bool NOT NULL, "link_content_type_id" integer NULL REFERENCES "django_content_type" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "menus_cachekey" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "language" varchar(255) NOT NULL, "site" integer unsigned NOT NULL CHECK ("site" >= 0), "key" varchar(255) NOT NULL);
CREATE TABLE IF NOT EXISTS "product_plugin_productmodel" ("cmsplugin_ptr_id" integer NOT NULL PRIMARY KEY REFERENCES "cms_cmsplugin" ("id") DEFERRABLE INITIALLY DEFERRED, "image_id" integer NULL REFERENCES "filer_image" ("file_ptr_id") DEFERRABLE INITIALLY DEFERRED, "product_id" bigint NULL REFERENCES "products" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "robots_rule_sites" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "rule_id" integer NOT NULL REFERENCES "robots_rule" ("id") DEFERRABLE INITIALLY DEFERRED, "site_id" integer NOT NULL REFERENCES "django_site" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "robots_rule_disallowed" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "rule_id" integer NOT NULL REFERENCES "robots_rule" ("id") DEFERRABLE INITIALLY DEFERRED, "url_id" integer NOT NULL REFERENCES "robots_url" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "robots_rule_allowed" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "rule_id" integer NOT NULL REFERENCES "robots_rule" ("id") DEFERRABLE INITIALLY DEFERRED, "url_id" integer NOT NULL REFERENCES "robots_url" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "robots_rule" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "robot" varchar(255) NOT NULL, "crawl_delay" decimal NULL);
CREATE TABLE IF NOT EXISTS "robots_url" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "pattern" varchar(255) NOT NULL);
CREATE TABLE IF NOT EXISTS "django_session" ("session_key" varchar(40) NOT NULL PRIMARY KEY, "session_data" text NOT NULL, "expire_date" datetime NOT NULL);
CREATE TABLE IF NOT EXISTS "django_site" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(50) NOT NULL, "domain" varchar(100) NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS "socialaccount_socialapp_sites" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "socialapp_id" integer NOT NULL REFERENCES "socialaccount_socialapp" ("id") DEFERRABLE INITIALLY DEFERRED, "site_id" integer NOT NULL REFERENCES "django_site" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "socialaccount_socialtoken" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "token" text NOT NULL, "token_secret" text NOT NULL, "expires_at" datetime NULL, "account_id" integer NOT NULL REFERENCES "socialaccount_socialaccount" ("id") DEFERRABLE INITIALLY DEFERRED, "app_id" integer NOT NULL REFERENCES "socialaccount_socialapp" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "socialaccount_socialapp" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "provider" varchar(30) NOT NULL, "name" varchar(40) NOT NULL, "client_id" varchar(191) NOT NULL, "key" varchar(191) NOT NULL, "secret" varchar(191) NOT NULL);
CREATE TABLE IF NOT EXISTS "socialaccount_socialaccount" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "provider" varchar(30) NOT NULL, "uid" varchar(191) NOT NULL, "last_login" datetime NOT NULL, "date_joined" datetime NOT NULL, "user_id" bigint NOT NULL REFERENCES "backend_auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "extra_data" text NOT NULL);
CREATE TABLE IF NOT EXISTS "taggit_tag" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(100) NOT NULL UNIQUE, "slug" varchar(100) NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS "newss" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "image" varchar(100) NOT NULL, "tag" varchar(1000) NOT NULL, "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL, "is_published" bool NOT NULL);
CREATE TABLE IF NOT EXISTS "newss_translation" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "language_code" varchar(15) NOT NULL, "name" varchar(100) NOT NULL, "description" varchar(1000) NOT NULL, "content" text NOT NULL, "master_id" bigint NULL REFERENCES "newss" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "news_plugin_newsmodel" ("cmsplugin_ptr_id" integer NOT NULL PRIMARY KEY REFERENCES "cms_cmsplugin" ("id") DEFERRABLE INITIALLY DEFERRED, "image_id" integer NULL REFERENCES "filer_image" ("file_ptr_id") DEFERRABLE INITIALLY DEFERRED, "news_id" bigint NULL REFERENCES "newss" ("id") DEFERRABLE INITIALLY DEFERRED);
