INSERT INTO products VALUES(2,'products/邮箱.png','TinySA Ultra Plus ZS406',752,'2024-12-20 11:20:41.040281','2025-03-29 02:20:41.138557',1,'<p><strong>TinySA Ultra are small, portable spectrum analyzers and signal generators with some nice features.</strong></p>');
INSERT INTO products VALUES(3,'products/LibreVNA_outlineWithPackage.jpg','LibreVNA2025 Normal',3299,'2024-12-20 11:21:03.571567','2025-03-29 02:20:54.654526',1,'<p>LibreVNA 2024 is a  100kHz-6GHz Vector Network Analyzer, USB Based Full 2-Port with External Reference Input/Output, 6-Layer PCB Design Measure Full S-Parameters.</p>');
INSERT INTO products VALUES(4,'products/bYmDNRkp_副本.png','LibreVNA2025 Plus',3450,'2024-12-20 11:21:20.125249','2025-03-29 02:21:34.222486',1,'<p>LibreVNA 2025 is a 100kHz-6GHz Vector Network Analyzer USB Based Full 2-Port with External Reference Input/Output,6-Layer PCB Design Measure Full S-Parameters. Special design with 6mm fins installed on the top side and 4 positioning holes are installed on the bottom side, so customers can install larger heat sinks or feet (M3*6 nuts) for easy use. The 2025 version also replaces the original brass SMA with a four-hole flange stainless steel SMA with more torque, both SMA fittings that can support up to 18G.</p>');
INSERT INTO products VALUES(5,'products/微信_6QOOI5Y.png','NanoVNA-F V2',560,'2024-12-20 11:21:55.382644','2025-03-02 13:02:22.514038',1,'<p><strong>NanoVNA-F V2</strong></p>');
