INSERT INTO djangocms_history_placeholderaction VALUES(425,'add_plugin','{"parent_id": 365, "order": []}','{"parent_id": 365, "plugins": [{"pk": 947, "creation_date": "2024-12-20T11:50:21.552Z", "position": 3, "plugin_type": "TextPlugin", "parent_id": 365, "data": {"body": "<p><span style=\"color: #999999;\">\u6b22\u8fce\u6765\u5230\u5fae\u578b\u5c04\u9891\u8bbe\u5907Tiny RF Equip\u7684\u7f51\u7ad9\uff0c\u8fd9\u91cc\u6db5\u76d6\u548c\u4ecb\u7ecd\u4e86\u5f88\u591a\u5fae\u578b\uff0c\u9ad8\u6548\u7684\u5c04\u9891\u5fae\u6ce2\u6d4b\u8bd5\u8bbe\u5907\uff0c\u5668\u4ef6\uff0c\u4ee5\u53ca\u76f8\u5173\u5c04\u9891\u6a21\u5757\u3002\u8fd9\u4e9b\u4ea7\u54c1\u4e3b\u8981\u7528\u6765\u6ee1\u8db3\u57fa\u672c\u7684\u65e0\u7ebf\u4ea7\u54c1\u6d4b\u8bd5\u9700\u8981\uff0c\u4e1a\u4f59\u65e0\u7ebf\u7535\u6d4b\u8bd5\u7231\u597d\u8005\u4ee5\u53ca\u5b66\u751f\u5b66\u4e60\u7684\u9700\u6c42\u3002\u8fd9\u662f\u4e00\u4e2a\u81ea\u7531\u5f00\u653e\u7684\u7f51\u7ad9\uff0c\u5e0c\u671b\u80fd\u5728\u8fd9\u91cc\u53ef\u4ee5\u548c\u5927\u5bb6\u66f4\u4e13\u4e1a\uff0c\u66f4\u5feb\u6377\u5730\u4ea4\u6d41\u5c04\u9891\u7684\u4e13\u4e1a\u95ee\u9898\uff0c\u8fd9\u91cc\u7684\u4ea7\u54c1\u529b\u4e89\u4e3a\u5ba2\u6237\u83b7\u5f97\u6700\u5927\u7684\u7684\u7ecf\u6d4e\u6295\u5165\u4ea7\u51fa\u6bd4\u3002</span></p>\n\n<p><span style=\"color: #999999;\">\u540c\u65f6\u672c\u5de5\u4f5c\u5ba4\u5de5\u7a0b\u5e08\u7cbe\u901a\u662f\u5fb7\uff0c\u7f57\u5fb7\uff0c\u5b89\u7acb\u7684\u76f8\u5173\u5c04\u9891\u4eea\u8868\uff0c\u63d0\u4f9b\u5728\u7ebf\u548c\u73b0\u573a\u57f9\u8bad\u54a8\u8be2\uff0c\u66f4\u591a\u4fe1\u606f\u8bf7\u76f4\u63a5\u6dd8\u5b9d\u6216\u8005email\u8054\u7cfb\u3002</span></p>\n\n<p><span style=\"color: #999999;\"><strong>\u76ee\u524d\u5305\u542b\u4ea7\u54c1\u6709\uff1aTinySA, TinySA Ultra, NanoVNA\uff0cNanoVNA-H2, NanoVNA-H4, \u00a0NanoVNA SAA2, LiteVNA, LibreVNA\u00a0</strong></span></p>"}}], "order": []}','zh-hans',1,416,12);
