INSERT INTO djangocms_history_placeholderaction VALUES(539,'change_plugin','{"plugins": [{"pk": 2577, "creation_date": "2024-12-20T12:37:21.671Z", "position": 0, "plugin_type": "TextPlugin", "parent_id": 2576, "data": {"body": "<p><strong>TinySA\u662f\u4e00\u79cd\u5c0f\u578b\u9891\u8c31\u5206\u6790\u4eea\u548c\u4fe1\u53f7\u53d1\u751f\u5668\uff0c\u5177\u6709\u4e00\u4e9b\u4e0d\u9519\u7684\u529f\u80fd\uff1a</strong></p>\n\n<ul>\n\t<li><strong>TinySA\u57fa\u672c\u7279\u70b9:</strong>\n\n\t<ul>\n\t\t<li>\u5c4f\u5e55\u5c3a\u5bf8 2.8\u82f1\u5bf8</li>\n\t\t<li>\u5e26\u4e24\u4e2a\u8f93\u5165\u7aef\u53e3\u7684\u9891\u8c31\u5206\u6790\u4eea\uff0cLow\u7aef\u53e3\u7528\u4e8e 10KHz-350MHz \u7684\u9ad8\u8d28\u91cf MF/HF/VHF \u8f93\u5165\uff0cHigh\u7aef\u53e3\u7528\u4e8e 240MHz-960MHz \u7684 UHF \u8f93\u5165\u3002</li>\n\t\t<li>\u4fe1\u53f7\u53d1\u751f\u5668\u5177\u6709\u4e24\u4e2a\u8f93\u51fa\uff0c\u6b63\u5f26\u6ce2\u8f93\u51fa\u4e3a100KHz - 350MHz\uff0c\u65b9\u6ce2\u8f93\u51fa\u4e3a 240MHz-960MHz\uff0c\u4fe1\u53f7\u53d1\u751f\u5668\u548c\u9891\u8c31\u5206\u6790\u4eea\u540c\u4e00\u65f6\u523b\u53ea\u80fd\u9009\u62e9\u5176\u4e2d\u7684\u4e00\u4e2a\u529f\u80fd\u3002</li>\n\t\t<li>\u5f69\u8272\u663e\u793a\u5c4f\u663e\u793a\u6700\u591a 290\u4e2a\u626b\u63cf\u70b9\uff0c\u63d0\u4f9b\u957f\u8fbe\u6574\u4e2a\u4f4e\u9891\u6216\u9ad8\u9891\u8303\u56f4\u7684\u65e0\u95f4\u9699\u8986\u76d6\u3002</li>\n\t</ul>\n\t</li>\n\t<li><strong>TinySA</strong>\u00a0<strong>Ultra\u57fa\u672c\u7279\u70b9:</strong>\n\t<ul>\n\t\t<li>\u5c4f\u5e55\u5c3a\u5bf8 4\u82f1\u5bf8</li>\n\t\t<li>\u9891\u8c31\u5206\u6790\u4eea\u6a21\u5f0f\uff0c\u521d\u59cb\u72b6\u6001\u4e3a10KHz-800MHz\uff0c\u5728\u542f\u7528\u72ec\u7279\u7684Ultra\u6a21\u5f0f\u7684\u60c5\u51b5\u4e0b\uff0c\u53ef\u4ee5\u76d1\u6d4b\u9ad8\u8fbe12GHz\u7684\u4fe1\u53f7\u3002</li>\n\t\t<li>\u4fe1\u53f7\u53d1\u751f\u5668\u6a21\u5f0f\uff0c\u6b63\u5f26\u6ce2\u8f93\u51fa\u5728100KHz-800MHz\u4e4b\u95f4\uff0c\u5c04\u9891\u6d4b\u8bd5\u4fe1\u53f7\u7684\u65b9\u6ce2\u8f93\u51fa\u9ad8\u8fbe5.3GHz\u3002</li>\n\t\t<li>200Hz\u81f3850KHz\u7684RBW\u8bbe\u7f6e\u63d0\u4f9b\u66f4\u9ad8\u7684\u7075\u654f\u5ea6\u8303\u56f4\u3002</li>\n\t\t<li>\u5185\u7f6e 20dB \u53ef\u9009 LNA</li>\n\t\t<li>\u5f69\u8272\u663e\u793a\u5c4f\u663e\u793a\u6700\u5927 450 \u4e2a\u70b9\uff0c\u63d0\u4f9b\u957f\u8fbe\u6574\u4e2a\u9891\u7387\u8303\u56f4\u7684\u65e0\u95f4\u9699\u8986\u76d6\u3002</li>\n\t\t<li>MicroSD\u5361\u63d2\u69fd\uff0c\u7528\u4e8e\u5b58\u50a8\u6d4b\u91cf\u503c\uff0c\u8bbe\u7f6e\u548c\u5c4f\u5e55\u622a\u56fe\u3002</li>\n\t</ul>\n\t</li>\n\t<li>\u8f93\u5165\u6b65\u8fdb\u8870\u51cf\u5668\u4ece0dB\u523031dB\uff08\u4e0d\u80fd\u4e0eLNA\u7ed3\u5408\u4f7f\u7528\uff09\u3002</li>\n\t<li>\u5185\u7f6e\u6821\u51c6\u4fe1\u53f7\u53d1\u751f\u5668\uff0c\u7528\u4e8e\u81ea\u52a8\u81ea\u68c0\u548c\uff08\u4f4e\uff09\u8f93\u5165\u6821\u51c6\u3002</li>\n\t<li>\u901a\u8fc7USB\u8fde\u63a5\u5230PC\uff0c\u5b83\u6210\u4e3aPC\u63a7\u5236\u7684\u9891\u8c31\u5206\u6790\u4eea\u6216\u4fe1\u53f7\u53d1\u751f\u5668</li>\n\t<li>\u9ad8\u8fbe3000mah\u7684\u53ef\u5145\u7535\u7535\u6c60\uff0c\u53ef\u643a\u5e26\u81f3\u5c112\u5c0f\u65f6\u3002</li>\n\t<li>\u6700\u5927\u8f93\u5165\u7535\u5e73 +6dBm\u3002</li>\n\t<li>\u4fe1\u53f7\u53d1\u751f\u5668\u529f\u80fd\u4e0d\u80fd\u7528\u4f5c\u8ddf\u8e2a\u53d1\u751f\u5668\uff0c\u56e0\u4e3a\u60a8\u4e0d\u80fd\u540c\u65f6\u4f7f\u7528\u9891\u8c31\u5206\u6790\u4eea\u548c\u4fe1\u53f7\u53d1\u751f\u5668\u529f\u80fd\u3002</li>\n\t<li>\u7531\u4e8e\u4f4e\u6210\u672c\u548c\u975e\u5e38\u5c0f\u7684\u5916\u5f62\u5c3a\u5bf8\uff0c\u5b58\u5728\u67d0\u4e9b\u76f8\u5173\u7684\u5fae\u5c0fSA\u9650\u5236\u548c\u5fae\u5c0fSA\u8d85\u9650\u5236\u3002</li>\n</ul>\n\n<figure><img alt=\"\" src=\"https://tinysa.org/wiki/uploads/Main/tinySA_housing.jpg\"></figure>\n\n<figure><img alt=\"\" src=\"https://tinysa.org/wiki/uploads/Main/tinySA_ultra.jpg\"></figure>\n\n<p><strong>\u89c6\u9891\u6559\u5b66\uff1a</strong></p>\n\n<p>\u53ef\u4ee5\u5728B\u7ad9\u4e5f\u5c31\u662f\u54d4\u54e9\u54d4\u54e9_bilibili\u7f51\u7ad9\u641c\u7d22TinyRFEquip\u8d26\u53f7\u627e\u5230\u4ecb\u7ecdTinySA\u548cTinySA Ultra\u4ee5\u53ca\u5176\u4ed6TinyRFEquip\u4eea\u5668\u7684\u4e3b\u8981\u529f\u80fd\u4ecb\u7ecd\u89c6\u9891\u3002\u4f8b\u5982\uff1a</p>\n\n<p><a href=\"https://www.bilibili.com/video/BV1yt421u7Y2/?vd_source=8d60a323bdde2d574cb0a85c07cb3212\">TinySA Ultra\u5bf9\u4e8e\u65e0\u7ebf\u8bdd\u7b52\u7684\u9891\u7387\u7279\u6027\u68c0\u5b9a\u6d4b\u91cf_\u54d4\u54e9\u54d4\u54e9_bilibili</a></p>\n\n<p>https://www.bilibili.com/video/BV1yt421u7Y2/?vd_source=8d60a323bdde2d574cb0a85c07cb3212</p>\n\n<p><strong>\u6cd5\u5f8b\u5185\u5bb9</strong></p>\n\n<p>TinySA\u548cTinySA Ultra\u7684\u540d\u79f0\u4ee5\u53caTinySA\u5fbd\u6807\u662f\u6211\u4eec\u62e5\u6709\u7684\u6ce8\u518c\u5546\u6807\u3002\u672a\u7ecf\u4e66\u9762\u8bb8\u53ef\uff0c\u4e0d\u5141\u8bb8\u5176\u4ed6\u4eba\u4f7f\u7528TinySA\u8fd9\u4e2a\u540d\u5b57 \u6216 TinySA Ultra \u7528\u4e8e\u4efb\u4f55\u9891\u8c31\u5206\u6790\u4eea\u4ea7\u54c1\u3002</p>"}}]}','{"plugins": [{"pk": 2577, "creation_date": "2024-12-20T12:37:21.671Z", "position": 0, "plugin_type": "TextPlugin", "parent_id": 2576, "data": {"body": "<figure><img src=\"https://www.tinyrfequip.com/librevna1.jpg\"></figure>\n\n<figure><img src=\"https://www.tinyrfequip.com/librevna2.jpg\"></figure>\n\n<p>\u00a0</p>\n\n<figure><img alt=\"6\" src=\"https://m.media-amazon.com/images/S/aplus-media-library-service-media/87b5e939-0676-4ad9-8fcb-0cf1df63526f.__CR0,0,970,600_PT0_SX970_V1___.jpg\"></figure>\n\n<p>\u00a0</p>\n\n<figure><img alt=\"2\" src=\"https://m.media-amazon.com/images/S/aplus-media-library-service-media/48423d91-b7e1-4ba8-9b31-61b36dbc35ba.__CR0,0,970,600_PT0_SX970_V1___.jpg\"></figure>\n\n<p>\u00a0</p>\n\n<figure><img src=\"https://github.com/jankae/LibreVNA/raw/master/Documentation/Pictures/RevisionB6LTop.JPG\"></figure>\n\n<p>\u00a0</p>\n\n<p>\u00a0</p>\n\n<p>\u00a0</p>\n\n<figure><img alt=\"secondPrototypeBottom.JPG\" src=\"https://github.com/jankae/LibreVNA/blob/master/Documentation/Pictures/secondPrototypeBottom.JPG?raw=true\"></figure>\n\n<figure><img alt=\"IMG_5516.JPG\" src=\"https://github.com/jankae/LibreVNA/blob/master/Documentation/Pictures/IMG_5516.JPG?raw=true\"></figure>\n\n<figure><img alt=\"ShieldingTop.JPG\" src=\"https://github.com/jankae/LibreVNA/blob/master/Documentation/Pictures/ShieldingTop.JPG?raw=true\"></figure>\n\n<h2 id=\"\u5b83\u662f\u5982\u4f55\u5de5\u4f5c\u7684\">\u5b83\u662f\u5982\u4f55\u5de5\u4f5c\u7684\uff1f</h2>\n\n<p>PCB\u786c\u4ef6\u5b9e\u9645\u4e0a\u53ea\u662f\u5177\u6709\u4e00\u5b9a\u5904\u7406\u80fd\u529b\u7684RF\u524d\u7aef\u3002\u4e00\u65e6\u6570\u636e\u901a\u8fc7USB\u4f20\u8f93\uff0c\u5176\u4ed6\u4e00\u5207\u90fd\u5728PC\u5e94\u7528\u7a0b\u5e8f\u4e2d\u5904\u7406\u3002\u60a8\u53ef\u4ee5\u5728\u6ca1\u6709PCB\u7684\u60c5\u51b5\u4e0b\u8bd5\u7528\u8be5\u5e94\u7528\u7a0b\u5e8f\uff08\u663e\u7136\u65e0\u6cd5\u8fdb\u884c\u6d4b\u91cf\uff0c\u4f46\u60a8\u53ef\u4ee5\u5bfc\u5165\u63d0\u4f9b\u7684\u793a\u4f8b\u6d4b\u91cf\u503c\uff0c\u5e76\u4e86\u89e3\u5b83\u53ef\u4ee5\u505a\u4ec0\u4e48\u548c\u4e0d\u80fd\u505a\u4ec0\u4e48\uff09\u3002</p>\n\n<h3 id=\"\u5c04\u9891\u8def\u5f84\">\u5c04\u9891\u8def\u5f84\uff1a</h3>\n\n<figure><img alt=\"\" src=\"https://github.com/jankae/LibreVNA/raw/master/Documentation/DeveloperInfo/RFBlockdiagram.svg\"></figure>\n\n<ul>\n\t<li>\u4e3b\u65f6\u949f\u6e90\u662fSi5351C\uff0c\u4e3a\u4e0d\u540c\u6a21\u5757\u63d0\u4f9b\u6240\u6709\u5fc5\u9700\u7684\u65f6\u949f\u3002\u5b83\u8fd8\u53ef\u4ee5\u4f5c\u4e3a\u4f4e\u4e8e25MHz\u9891\u7387\u7684\u6fc0\u52b1\u6e90\u3002\u5b83\u81ea\u8eab\u7684\u53c2\u8003\u65f6\u949f\u662f26MHz\u6676\u4f53\u6216\u5916\u90e810MHz\u4fe1\u53f7\u3002</li>\n\t<li>\u9891\u7387\u9ad8\u4e8e25MHz\u7684\u6fc0\u52b1\u6e90\u662fMAX2871\u3002\u5176\u8f93\u51fa\u4fe1\u53f7\u7ecf\u8fc7\u8f7b\u5fae\u6ee4\u6ce2\u4ee5\u51cf\u5c11\u8c10\u6ce2\u91cf\u3002</li>\n\t<li>\u6fc0\u52b1\u4fe1\u53f7\u529f\u7387\u53ef\u901a\u8fc7\u6570\u5b57\u8870\u51cf\u5668\uff08RFSA42\uff09\u5728\u5927\u7ea6-10\u81f3-3714dbm\u4e4b\u95f4\u8c03\u8282\u3002</li>\n\t<li>\u5728\u653e\u5927\u5668\uff08TRF37A73\uff09\u4e4b\u540e\uff0c\u4fe1\u53f7\u88ab\u5206\u79bb\uff0c\u4fe1\u53f7\u8f83\u5f31\u7684\u90e8\u5206\u9988\u5165\u53c2\u8003\u63a5\u6536\u5668\u3002</li>\n\t<li>\u4fe1\u53f7\u7684\u8f83\u5f3a\u90e8\u5206\u53ef\u4ee5\u8def\u7531\u5230\u4efb\u4e00\u7aef\u53e3\u3002\u5728\u6bcf\u4e2a\u4fe1\u53f7\u8def\u5f84\u4e2d\uff0c\u4e24\u4e2aRF\u5f00\u5173\u4e32\u8054\u4f7f\u7528\uff0c\u4ee5\u5b9e\u73b0\u7aef\u53e3\u4e4b\u95f4\u7684\u66f4\u9ad8\u9694\u79bb\u5ea6\u3002</li>\n\t<li>\u4ee3\u66ff\u5b9a\u5411\u8026\u5408\u5668\uff0c\u4f7f\u7528\u963b\u6027\u56de\u6ce2\u635f\u8017\u6865\uff08\u5728\u5bbd\u5e26\u5bbd\u4e0b\u66f4\u5bb9\u6613\u5b9e\u73b0\uff09\u3002</li>\n\t<li>\u4e24\u4e2a\u7aef\u53e3\u90fd\u6709\u5b8c\u5168\u72ec\u7acb\u7684\u63a5\u6536\u8def\u5f84\u3002\u8fd9\u589e\u52a0\u4e86BOM\u6210\u672c\uff0c\u4f46\u5141\u8bb8\u540c\u65f6\u6d4b\u91cf\u4e24\u4e2a\u53c2\u6570\uff08S11\u548cS21\u6216S22\u548cS12\uff09\u3002\u5b83\u8fd8\u907f\u514d\u4e86\u63a5\u6536\u8def\u5f84\u5408\u5e76\u5230\u5355\u4e2a\u6df7\u9891\u5668/ADC\u65f6\u53ef\u80fd\u51fa\u73b0\u7684\u6f5c\u5728\u9694\u79bb\u95ee\u9898\u3002</li>\n\t<li>\u6bcf\u4e2a\u63a5\u6536\u5668\u7531\u4e24\u4e2a\u4e0b\u53d8\u9891\u6df7\u9891\u5668\u7ec4\u6210\u3002IF1\u4f4d\u4e8e60MHz\uff0cIF2\u4f4d\u4e8e250kHz\u3002</li>\n\t<li>ADC\u4f7f\u752816bit@800kHz\u5bf9\u6700\u7ec8IF\u8fdb\u884c\u91c7\u6837\u3002</li>\n</ul>\n\n<h3 id=\"\u6570\u5b57\u90e8\u5206\">\u6570\u5b57\u90e8\u5206\uff1a</h3>\n\n<figure><img alt=\"\" src=\"https://github.com/jankae/LibreVNA/raw/master/Documentation/DeveloperInfo/DigitalBlockdiagram.svg\"></figure>\n\n<ul>\n\t<li>\u6838\u5fc3\u5143\u7d20\u662fSpartan6 FPGA\u3002\u5b83\u5904\u7406\u4e0eRF\u6a21\u5757\u7684\u6240\u6709\u901a\u4fe1\uff0c\u5e76\u5bf9ADC\u8fdb\u884c\u91c7\u6837\u3002\u8fd9\u5141\u8bb8\u8fd1\u4e4e\u5373\u65f6\u5730\u5207\u6362\u6d4b\u91cf\u9891\u7387\uff0c\u4ec5\u53d7PLL\u5efa\u7acb\u65f6\u95f4\u7684\u9650\u5236\u3002</li>\n\t<li>\u5fae\u63a7\u5236\u5668\u5904\u7406FPGA\u4e2d\u7684\u626b\u63cf\u8bbe\u7f6e\uff0c\u63d0\u53d6\u548c\u9884\u5904\u7406\u6d4b\u91cf\u7ed3\u679c\uff0c\u5e76\u901a\u8fc7USB\u4f20\u9012\u3002</li>\n\t<li>\u95ea\u5b58\u5305\u542bFPGA\u6bd4\u7279\u6d41\u3002\u7531\u4e8e\u5fae\u63a7\u5236\u5668\u53ef\u4ee5\u8bbf\u95ee\u95ea\u5b58\uff0c\u56e0\u6b64\u4e0d\u9700\u8981\u4e0eFPGA\u76f8\u5173\u7684\u786c\u4ef6\u5de5\u5177\uff08\u4f8b\u5982JTAG\u7f16\u7a0b\u5668\uff09\uff0c\u6240\u6709\u5185\u5bb9\u90fd\u53ef\u4ee5\u901a\u8fc7USB\u8fdb\u884c\u66f4\u65b0\u3002</li>\n</ul>\n\n<h3 id=\"\u7535\u6e90\">\u7535\u6e90\uff1a</h3>\n\n<figure><img alt=\"\" src=\"https://github.com/jankae/LibreVNA/raw/master/Documentation/DeveloperInfo/PowerBlockdiagram.svg\"></figure>\n\n<ul>\n\t<li>\u4e00\u5207\u90fd\u7531 USB \u4f9b\u7535\uff08\u6216\u53ef\u9009\u7531\u5916\u90e8 5V DC \u4f9b\u7535\uff09</li>\n\t<li>\u51e0\u4e4e\u6bcf\u4e2aRF\u6a21\u5757\u90fd\u6709\u81ea\u5df1\u7684\u672c\u5730\u8c03\u8282\u5668\uff0c\u53ef\u9632\u6b62\u8026\u5408\u5230\u7535\u6e90\u7ebf\u7684\u566a\u58f0\u548c\u4fe1\u53f7\u5728\u6574\u4e2aPCB\u4e0a\u4f20\u64ad</li>\n</ul>"}}]}','zh-hans',1,527,53);
INSERT INTO djangocms_history_placeholderaction VALUES(540,'change_plugin','{"plugins": [{"pk": 2577, "creation_date": "2024-12-20T12:37:21.671Z", "position": 0, "plugin_type": "TextPlugin", "parent_id": 2576, "data": {"body": "<figure><img src=\"https://www.tinyrfequip.com/librevna1.jpg\"></figure>\n\n<figure><img src=\"https://www.tinyrfequip.com/librevna2.jpg\"></figure>\n\n<p>\u00a0</p>\n\n<figure><img alt=\"6\" src=\"https://m.media-amazon.com/images/S/aplus-media-library-service-media/87b5e939-0676-4ad9-8fcb-0cf1df63526f.__CR0,0,970,600_PT0_SX970_V1___.jpg\"></figure>\n\n<p>\u00a0</p>\n\n<figure><img alt=\"2\" src=\"https://m.media-amazon.com/images/S/aplus-media-library-service-media/48423d91-b7e1-4ba8-9b31-61b36dbc35ba.__CR0,0,970,600_PT0_SX970_V1___.jpg\"></figure>\n\n<p>\u00a0</p>\n\n<figure><img src=\"https://github.com/jankae/LibreVNA/raw/master/Documentation/Pictures/RevisionB6LTop.JPG\"></figure>\n\n<p>\u00a0</p>\n\n<p>\u00a0</p>\n\n<p>\u00a0</p>\n\n<figure><img alt=\"secondPrototypeBottom.JPG\" src=\"https://github.com/jankae/LibreVNA/blob/master/Documentation/Pictures/secondPrototypeBottom.JPG?raw=true\"></figure>\n\n<figure><img alt=\"IMG_5516.JPG\" src=\"https://github.com/jankae/LibreVNA/blob/master/Documentation/Pictures/IMG_5516.JPG?raw=true\"></figure>\n\n<figure><img alt=\"ShieldingTop.JPG\" src=\"https://github.com/jankae/LibreVNA/blob/master/Documentation/Pictures/ShieldingTop.JPG?raw=true\"></figure>\n\n<h2 id=\"\u5b83\u662f\u5982\u4f55\u5de5\u4f5c\u7684\">\u5b83\u662f\u5982\u4f55\u5de5\u4f5c\u7684\uff1f</h2>\n\n<p>PCB\u786c\u4ef6\u5b9e\u9645\u4e0a\u53ea\u662f\u5177\u6709\u4e00\u5b9a\u5904\u7406\u80fd\u529b\u7684RF\u524d\u7aef\u3002\u4e00\u65e6\u6570\u636e\u901a\u8fc7USB\u4f20\u8f93\uff0c\u5176\u4ed6\u4e00\u5207\u90fd\u5728PC\u5e94\u7528\u7a0b\u5e8f\u4e2d\u5904\u7406\u3002\u60a8\u53ef\u4ee5\u5728\u6ca1\u6709PCB\u7684\u60c5\u51b5\u4e0b\u8bd5\u7528\u8be5\u5e94\u7528\u7a0b\u5e8f\uff08\u663e\u7136\u65e0\u6cd5\u8fdb\u884c\u6d4b\u91cf\uff0c\u4f46\u60a8\u53ef\u4ee5\u5bfc\u5165\u63d0\u4f9b\u7684\u793a\u4f8b\u6d4b\u91cf\u503c\uff0c\u5e76\u4e86\u89e3\u5b83\u53ef\u4ee5\u505a\u4ec0\u4e48\u548c\u4e0d\u80fd\u505a\u4ec0\u4e48\uff09\u3002</p>\n\n<h3 id=\"\u5c04\u9891\u8def\u5f84\">\u5c04\u9891\u8def\u5f84\uff1a</h3>\n\n<figure><img alt=\"\" src=\"https://github.com/jankae/LibreVNA/raw/master/Documentation/DeveloperInfo/RFBlockdiagram.svg\"></figure>\n\n<ul>\n\t<li>\u4e3b\u65f6\u949f\u6e90\u662fSi5351C\uff0c\u4e3a\u4e0d\u540c\u6a21\u5757\u63d0\u4f9b\u6240\u6709\u5fc5\u9700\u7684\u65f6\u949f\u3002\u5b83\u8fd8\u53ef\u4ee5\u4f5c\u4e3a\u4f4e\u4e8e25MHz\u9891\u7387\u7684\u6fc0\u52b1\u6e90\u3002\u5b83\u81ea\u8eab\u7684\u53c2\u8003\u65f6\u949f\u662f26MHz\u6676\u4f53\u6216\u5916\u90e810MHz\u4fe1\u53f7\u3002</li>\n\t<li>\u9891\u7387\u9ad8\u4e8e25MHz\u7684\u6fc0\u52b1\u6e90\u662fMAX2871\u3002\u5176\u8f93\u51fa\u4fe1\u53f7\u7ecf\u8fc7\u8f7b\u5fae\u6ee4\u6ce2\u4ee5\u51cf\u5c11\u8c10\u6ce2\u91cf\u3002</li>\n\t<li>\u6fc0\u52b1\u4fe1\u53f7\u529f\u7387\u53ef\u901a\u8fc7\u6570\u5b57\u8870\u51cf\u5668\uff08RFSA42\uff09\u5728\u5927\u7ea6-10\u81f3-3714dbm\u4e4b\u95f4\u8c03\u8282\u3002</li>\n\t<li>\u5728\u653e\u5927\u5668\uff08TRF37A73\uff09\u4e4b\u540e\uff0c\u4fe1\u53f7\u88ab\u5206\u79bb\uff0c\u4fe1\u53f7\u8f83\u5f31\u7684\u90e8\u5206\u9988\u5165\u53c2\u8003\u63a5\u6536\u5668\u3002</li>\n\t<li>\u4fe1\u53f7\u7684\u8f83\u5f3a\u90e8\u5206\u53ef\u4ee5\u8def\u7531\u5230\u4efb\u4e00\u7aef\u53e3\u3002\u5728\u6bcf\u4e2a\u4fe1\u53f7\u8def\u5f84\u4e2d\uff0c\u4e24\u4e2aRF\u5f00\u5173\u4e32\u8054\u4f7f\u7528\uff0c\u4ee5\u5b9e\u73b0\u7aef\u53e3\u4e4b\u95f4\u7684\u66f4\u9ad8\u9694\u79bb\u5ea6\u3002</li>\n\t<li>\u4ee3\u66ff\u5b9a\u5411\u8026\u5408\u5668\uff0c\u4f7f\u7528\u963b\u6027\u56de\u6ce2\u635f\u8017\u6865\uff08\u5728\u5bbd\u5e26\u5bbd\u4e0b\u66f4\u5bb9\u6613\u5b9e\u73b0\uff09\u3002</li>\n\t<li>\u4e24\u4e2a\u7aef\u53e3\u90fd\u6709\u5b8c\u5168\u72ec\u7acb\u7684\u63a5\u6536\u8def\u5f84\u3002\u8fd9\u589e\u52a0\u4e86BOM\u6210\u672c\uff0c\u4f46\u5141\u8bb8\u540c\u65f6\u6d4b\u91cf\u4e24\u4e2a\u53c2\u6570\uff08S11\u548cS21\u6216S22\u548cS12\uff09\u3002\u5b83\u8fd8\u907f\u514d\u4e86\u63a5\u6536\u8def\u5f84\u5408\u5e76\u5230\u5355\u4e2a\u6df7\u9891\u5668/ADC\u65f6\u53ef\u80fd\u51fa\u73b0\u7684\u6f5c\u5728\u9694\u79bb\u95ee\u9898\u3002</li>\n\t<li>\u6bcf\u4e2a\u63a5\u6536\u5668\u7531\u4e24\u4e2a\u4e0b\u53d8\u9891\u6df7\u9891\u5668\u7ec4\u6210\u3002IF1\u4f4d\u4e8e60MHz\uff0cIF2\u4f4d\u4e8e250kHz\u3002</li>\n\t<li>ADC\u4f7f\u752816bit@800kHz\u5bf9\u6700\u7ec8IF\u8fdb\u884c\u91c7\u6837\u3002</li>\n</ul>\n\n<h3 id=\"\u6570\u5b57\u90e8\u5206\">\u6570\u5b57\u90e8\u5206\uff1a</h3>\n\n<figure><img alt=\"\" src=\"https://github.com/jankae/LibreVNA/raw/master/Documentation/DeveloperInfo/DigitalBlockdiagram.svg\"></figure>\n\n<ul>\n\t<li>\u6838\u5fc3\u5143\u7d20\u662fSpartan6 FPGA\u3002\u5b83\u5904\u7406\u4e0eRF\u6a21\u5757\u7684\u6240\u6709\u901a\u4fe1\uff0c\u5e76\u5bf9ADC\u8fdb\u884c\u91c7\u6837\u3002\u8fd9\u5141\u8bb8\u8fd1\u4e4e\u5373\u65f6\u5730\u5207\u6362\u6d4b\u91cf\u9891\u7387\uff0c\u4ec5\u53d7PLL\u5efa\u7acb\u65f6\u95f4\u7684\u9650\u5236\u3002</li>\n\t<li>\u5fae\u63a7\u5236\u5668\u5904\u7406FPGA\u4e2d\u7684\u626b\u63cf\u8bbe\u7f6e\uff0c\u63d0\u53d6\u548c\u9884\u5904\u7406\u6d4b\u91cf\u7ed3\u679c\uff0c\u5e76\u901a\u8fc7USB\u4f20\u9012\u3002</li>\n\t<li>\u95ea\u5b58\u5305\u542bFPGA\u6bd4\u7279\u6d41\u3002\u7531\u4e8e\u5fae\u63a7\u5236\u5668\u53ef\u4ee5\u8bbf\u95ee\u95ea\u5b58\uff0c\u56e0\u6b64\u4e0d\u9700\u8981\u4e0eFPGA\u76f8\u5173\u7684\u786c\u4ef6\u5de5\u5177\uff08\u4f8b\u5982JTAG\u7f16\u7a0b\u5668\uff09\uff0c\u6240\u6709\u5185\u5bb9\u90fd\u53ef\u4ee5\u901a\u8fc7USB\u8fdb\u884c\u66f4\u65b0\u3002</li>\n</ul>\n\n<h3 id=\"\u7535\u6e90\">\u7535\u6e90\uff1a</h3>\n\n<figure><img alt=\"\" src=\"https://github.com/jankae/LibreVNA/raw/master/Documentation/DeveloperInfo/PowerBlockdiagram.svg\"></figure>\n\n<ul>\n\t<li>\u4e00\u5207\u90fd\u7531 USB \u4f9b\u7535\uff08\u6216\u53ef\u9009\u7531\u5916\u90e8 5V DC \u4f9b\u7535\uff09</li>\n\t<li>\u51e0\u4e4e\u6bcf\u4e2aRF\u6a21\u5757\u90fd\u6709\u81ea\u5df1\u7684\u672c\u5730\u8c03\u8282\u5668\uff0c\u53ef\u9632\u6b62\u8026\u5408\u5230\u7535\u6e90\u7ebf\u7684\u566a\u58f0\u548c\u4fe1\u53f7\u5728\u6574\u4e2aPCB\u4e0a\u4f20\u64ad</li>\n</ul>"}}]}','{"plugins": [{"pk": 2577, "creation_date": "2024-12-20T12:37:21.671Z", "position": 0, "plugin_type": "TextPlugin", "parent_id": 2576, "data": {"body": "<figure>\n<figure><img src=\"https://www.tinyrfequip.com/librevna1.jpg\"></figure>\n\n<figure><img src=\"https://www.tinyrfequip.com/librevna2.jpg\"></figure>\n\n<p>\u00a0</p>\n\n<figure><img alt=\"6\" src=\"https://m.media-amazon.com/images/S/aplus-media-library-service-media/87b5e939-0676-4ad9-8fcb-0cf1df63526f.__CR0,0,970,600_PT0_SX970_V1___.jpg\"></figure>\n\n<p>\u00a0</p>\n\n<figure><img alt=\"2\" src=\"https://m.media-amazon.com/images/S/aplus-media-library-service-media/48423d91-b7e1-4ba8-9b31-61b36dbc35ba.__CR0,0,970,600_PT0_SX970_V1___.jpg\"></figure>\n\n<p>\u00a0</p>\n\n<figure><img src=\"https://github.com/jankae/LibreVNA/raw/master/Documentation/Pictures/RevisionB6LTop.JPG\"></figure>\n\n<p>\u00a0</p>\n\n<p>\u00a0</p>\n\n<p>\u00a0</p>\n\n<figure><img alt=\"secondPrototypeBottom.JPG\" src=\"https://github.com/jankae/LibreVNA/blob/master/Documentation/Pictures/secondPrototypeBottom.JPG?raw=true\"></figure>\n\n<figure><img alt=\"IMG_5516.JPG\" src=\"https://github.com/jankae/LibreVNA/blob/master/Documentation/Pictures/IMG_5516.JPG?raw=true\"></figure>\n\n<figure><img alt=\"ShieldingTop.JPG\" src=\"https://github.com/jankae/LibreVNA/blob/master/Documentation/Pictures/ShieldingTop.JPG?raw=true\"></figure>\n\n<h2 id=\"\u5b83\u662f\u5982\u4f55\u5de5\u4f5c\u7684\">\u5b83\u662f\u5982\u4f55\u5de5\u4f5c\u7684\uff1f</h2>\n\n<p>PCB\u786c\u4ef6\u5b9e\u9645\u4e0a\u53ea\u662f\u5177\u6709\u4e00\u5b9a\u5904\u7406\u80fd\u529b\u7684RF\u524d\u7aef\u3002\u4e00\u65e6\u6570\u636e\u901a\u8fc7USB\u4f20\u8f93\uff0c\u5176\u4ed6\u4e00\u5207\u90fd\u5728PC\u5e94\u7528\u7a0b\u5e8f\u4e2d\u5904\u7406\u3002\u60a8\u53ef\u4ee5\u5728\u6ca1\u6709PCB\u7684\u60c5\u51b5\u4e0b\u8bd5\u7528\u8be5\u5e94\u7528\u7a0b\u5e8f\uff08\u663e\u7136\u65e0\u6cd5\u8fdb\u884c\u6d4b\u91cf\uff0c\u4f46\u60a8\u53ef\u4ee5\u5bfc\u5165\u63d0\u4f9b\u7684\u793a\u4f8b\u6d4b\u91cf\u503c\uff0c\u5e76\u4e86\u89e3\u5b83\u53ef\u4ee5\u505a\u4ec0\u4e48\u548c\u4e0d\u80fd\u505a\u4ec0\u4e48\uff09\u3002</p>\n\n<h3 id=\"\u5c04\u9891\u8def\u5f84\">\u5c04\u9891\u8def\u5f84\uff1a</h3>\n\n<figure><img alt=\"\" src=\"https://github.com/jankae/LibreVNA/raw/master/Documentation/DeveloperInfo/RFBlockdiagram.svg\"></figure>\n\n<ul>\n\t<li>\u4e3b\u65f6\u949f\u6e90\u662fSi5351C\uff0c\u4e3a\u4e0d\u540c\u6a21\u5757\u63d0\u4f9b\u6240\u6709\u5fc5\u9700\u7684\u65f6\u949f\u3002\u5b83\u8fd8\u53ef\u4ee5\u4f5c\u4e3a\u4f4e\u4e8e25MHz\u9891\u7387\u7684\u6fc0\u52b1\u6e90\u3002\u5b83\u81ea\u8eab\u7684\u53c2\u8003\u65f6\u949f\u662f26MHz\u6676\u4f53\u6216\u5916\u90e810MHz\u4fe1\u53f7\u3002</li>\n\t<li>\u9891\u7387\u9ad8\u4e8e25MHz\u7684\u6fc0\u52b1\u6e90\u662fMAX2871\u3002\u5176\u8f93\u51fa\u4fe1\u53f7\u7ecf\u8fc7\u8f7b\u5fae\u6ee4\u6ce2\u4ee5\u51cf\u5c11\u8c10\u6ce2\u91cf\u3002</li>\n\t<li>\u6fc0\u52b1\u4fe1\u53f7\u529f\u7387\u53ef\u901a\u8fc7\u6570\u5b57\u8870\u51cf\u5668\uff08RFSA42\uff09\u5728\u5927\u7ea6-10\u81f3-3714dbm\u4e4b\u95f4\u8c03\u8282\u3002</li>\n\t<li>\u5728\u653e\u5927\u5668\uff08TRF37A73\uff09\u4e4b\u540e\uff0c\u4fe1\u53f7\u88ab\u5206\u79bb\uff0c\u4fe1\u53f7\u8f83\u5f31\u7684\u90e8\u5206\u9988\u5165\u53c2\u8003\u63a5\u6536\u5668\u3002</li>\n\t<li>\u4fe1\u53f7\u7684\u8f83\u5f3a\u90e8\u5206\u53ef\u4ee5\u8def\u7531\u5230\u4efb\u4e00\u7aef\u53e3\u3002\u5728\u6bcf\u4e2a\u4fe1\u53f7\u8def\u5f84\u4e2d\uff0c\u4e24\u4e2aRF\u5f00\u5173\u4e32\u8054\u4f7f\u7528\uff0c\u4ee5\u5b9e\u73b0\u7aef\u53e3\u4e4b\u95f4\u7684\u66f4\u9ad8\u9694\u79bb\u5ea6\u3002</li>\n\t<li>\u4ee3\u66ff\u5b9a\u5411\u8026\u5408\u5668\uff0c\u4f7f\u7528\u963b\u6027\u56de\u6ce2\u635f\u8017\u6865\uff08\u5728\u5bbd\u5e26\u5bbd\u4e0b\u66f4\u5bb9\u6613\u5b9e\u73b0\uff09\u3002</li>\n\t<li>\u4e24\u4e2a\u7aef\u53e3\u90fd\u6709\u5b8c\u5168\u72ec\u7acb\u7684\u63a5\u6536\u8def\u5f84\u3002\u8fd9\u589e\u52a0\u4e86BOM\u6210\u672c\uff0c\u4f46\u5141\u8bb8\u540c\u65f6\u6d4b\u91cf\u4e24\u4e2a\u53c2\u6570\uff08S11\u548cS21\u6216S22\u548cS12\uff09\u3002\u5b83\u8fd8\u907f\u514d\u4e86\u63a5\u6536\u8def\u5f84\u5408\u5e76\u5230\u5355\u4e2a\u6df7\u9891\u5668/ADC\u65f6\u53ef\u80fd\u51fa\u73b0\u7684\u6f5c\u5728\u9694\u79bb\u95ee\u9898\u3002</li>\n\t<li>\u6bcf\u4e2a\u63a5\u6536\u5668\u7531\u4e24\u4e2a\u4e0b\u53d8\u9891\u6df7\u9891\u5668\u7ec4\u6210\u3002IF1\u4f4d\u4e8e60MHz\uff0cIF2\u4f4d\u4e8e250kHz\u3002</li>\n\t<li>ADC\u4f7f\u752816bit@800kHz\u5bf9\u6700\u7ec8IF\u8fdb\u884c\u91c7\u6837\u3002</li>\n</ul>\n\n<h3 id=\"\u6570\u5b57\u90e8\u5206\">\u6570\u5b57\u90e8\u5206\uff1a</h3>\n\n<figure><img alt=\"\" src=\"https://github.com/jankae/LibreVNA/raw/master/Documentation/DeveloperInfo/DigitalBlockdiagram.svg\"></figure>\n\n<ul>\n\t<li>\u6838\u5fc3\u5143\u7d20\u662fSpartan6 FPGA\u3002\u5b83\u5904\u7406\u4e0eRF\u6a21\u5757\u7684\u6240\u6709\u901a\u4fe1\uff0c\u5e76\u5bf9ADC\u8fdb\u884c\u91c7\u6837\u3002\u8fd9\u5141\u8bb8\u8fd1\u4e4e\u5373\u65f6\u5730\u5207\u6362\u6d4b\u91cf\u9891\u7387\uff0c\u4ec5\u53d7PLL\u5efa\u7acb\u65f6\u95f4\u7684\u9650\u5236\u3002</li>\n\t<li>\u5fae\u63a7\u5236\u5668\u5904\u7406FPGA\u4e2d\u7684\u626b\u63cf\u8bbe\u7f6e\uff0c\u63d0\u53d6\u548c\u9884\u5904\u7406\u6d4b\u91cf\u7ed3\u679c\uff0c\u5e76\u901a\u8fc7USB\u4f20\u9012\u3002</li>\n\t<li>\u95ea\u5b58\u5305\u542bFPGA\u6bd4\u7279\u6d41\u3002\u7531\u4e8e\u5fae\u63a7\u5236\u5668\u53ef\u4ee5\u8bbf\u95ee\u95ea\u5b58\uff0c\u56e0\u6b64\u4e0d\u9700\u8981\u4e0eFPGA\u76f8\u5173\u7684\u786c\u4ef6\u5de5\u5177\uff08\u4f8b\u5982JTAG\u7f16\u7a0b\u5668\uff09\uff0c\u6240\u6709\u5185\u5bb9\u90fd\u53ef\u4ee5\u901a\u8fc7USB\u8fdb\u884c\u66f4\u65b0\u3002</li>\n</ul>\n\n<h3 id=\"\u7535\u6e90\">\u7535\u6e90\uff1a</h3>\n\n<figure><img alt=\"\" src=\"https://github.com/jankae/LibreVNA/raw/master/Documentation/DeveloperInfo/PowerBlockdiagram.svg\"></figure>\n\n<ul>\n\t<li>\u4e00\u5207\u90fd\u7531 USB \u4f9b\u7535\uff08\u6216\u53ef\u9009\u7531\u5916\u90e8 5V DC \u4f9b\u7535\uff09</li>\n\t<li>\u51e0\u4e4e\u6bcf\u4e2aRF\u6a21\u5757\u90fd\u6709\u81ea\u5df1\u7684\u672c\u5730\u8c03\u8282\u5668\uff0c\u53ef\u9632\u6b62\u8026\u5408\u5230\u7535\u6e90\u7ebf\u7684\u566a\u58f0\u548c\u4fe1\u53f7\u5728\u6574\u4e2aPCB\u4e0a\u4f20\u64ad</li>\n</ul>\n</figure>"}}]}','zh-hans',1,528,53);
