INSERT INTO djangocms_history_placeholderaction VALUES(1097,'change_plugin','{"plugins": [{"pk": 10444, "creation_date": "2024-12-20T12:30:45.026Z", "position": 0, "plugin_type": "HeadingPlugin", "parent_id": 10443, "data": {"ui_item": "Heading", "tag_type": "div", "config": {"heading_level": "h2", "heading": "LibreVNA", "heading_id": "", "heading_context": "dark", "heading_alignment": "", "attributes": {}, "margin_x": "", "margin_y": "", "margin_devices": null, "padding_x": "", "padding_y": "", "padding_devices": null}}}]}','{"plugins": [{"pk": 10444, "creation_date": "2024-12-20T12:30:45.026Z", "position": 0, "plugin_type": "HeadingPlugin", "parent_id": 10443, "data": {"ui_item": "Heading", "tag_type": "div", "config": {"heading_level": "h2", "heading": "LibreVNA2025", "heading_id": "", "heading_context": "dark", "heading_alignment": "", "attributes": {}, "margin_x": "", "margin_y": "", "margin_devices": null, "padding_x": "", "padding_y": "", "padding_devices": null}}}]}','en',1,1082,77);
INSERT INTO djangocms_history_placeholderaction VALUES(1098,'change_plugin','{"plugins": [{"pk": 10446, "creation_date": "2024-12-20T12:31:27.640Z", "position": 2, "plugin_type": "TextPlugin", "parent_id": 10443, "data": {"body": "<p><strong>LibreVNALibreVNALibreVNALibreVNALibreVNALibreVNALibreVNALibreVNALibreVNA</strong></p>"}}]}','{"plugins": [{"pk": 10446, "creation_date": "2024-12-20T12:31:27.640Z", "position": 2, "plugin_type": "TextPlugin", "parent_id": 10443, "data": {"body": "<p>LibreVNA 2025 is a 100kHz-6GHz Vector Network Analyzer USB Based Full 2-Port with External Reference Input/Output,6-Layer PCB Design Measure Full S-Parameters. Special design with 6mm fins installed on the top side and 4 positioning holes are installed on the bottom side, so customers can install larger heat sinks or feet (M3*6 nuts) for easy use.\u00a0The 2025 version also replaces the original brass SMA with a four-hole flange stainless steel SMA with more torque, both SMA fittings that can support up to 18G.</p>"}}]}','en',1,1083,77);
INSERT INTO djangocms_history_placeholderaction VALUES(1099,'change_plugin','{"plugins": [{"pk": 10452, "creation_date": "2024-12-20T12:37:21.671Z", "position": 0, "plugin_type": "TextPlugin", "parent_id": 10451, "data": {"body": "<p><strong>TinySA\u662f\u4e00\u79cd\u5c0f\u578b\u9891\u8c31\u5206\u6790\u4eea\u548c\u4fe1\u53f7\u53d1\u751f\u5668\uff0c\u5177\u6709\u4e00\u4e9b\u4e0d\u9519\u7684\u529f\u80fd\uff1a</strong></p>\n\n<ul>\n\t<li><strong>TinySA\u57fa\u672c\u7279\u70b9:</strong>\n\n\t<ul>\n\t\t<li>\u5c4f\u5e55\u5c3a\u5bf8 2.8\u82f1\u5bf8</li>\n\t\t<li>\u5e26\u4e24\u4e2a\u8f93\u5165\u7aef\u53e3\u7684\u9891\u8c31\u5206\u6790\u4eea\uff0cLow\u7aef\u53e3\u7528\u4e8e 10KHz-350MHz \u7684\u9ad8\u8d28\u91cf MF/HF/VHF \u8f93\u5165\uff0cHigh\u7aef\u53e3\u7528\u4e8e 240MHz-960MHz \u7684 UHF \u8f93\u5165\u3002</li>\n\t\t<li>\u4fe1\u53f7\u53d1\u751f\u5668\u5177\u6709\u4e24\u4e2a\u8f93\u51fa\uff0c\u6b63\u5f26\u6ce2\u8f93\u51fa\u4e3a100KHz - 350MHz\uff0c\u65b9\u6ce2\u8f93\u51fa\u4e3a 240MHz-960MHz\uff0c\u4fe1\u53f7\u53d1\u751f\u5668\u548c\u9891\u8c31\u5206\u6790\u4eea\u540c\u4e00\u65f6\u523b\u53ea\u80fd\u9009\u62e9\u5176\u4e2d\u7684\u4e00\u4e2a\u529f\u80fd\u3002</li>\n\t\t<li>\u5f69\u8272\u663e\u793a\u5c4f\u663e\u793a\u6700\u591a 290\u4e2a\u626b\u63cf\u70b9\uff0c\u63d0\u4f9b\u957f\u8fbe\u6574\u4e2a\u4f4e\u9891\u6216\u9ad8\u9891\u8303\u56f4\u7684\u65e0\u95f4\u9699\u8986\u76d6\u3002</li>\n\t</ul>\n\t</li>\n\t<li><strong>TinySA</strong>\u00a0<strong>Ultra\u57fa\u672c\u7279\u70b9:</strong>\n\t<ul>\n\t\t<li>\u5c4f\u5e55\u5c3a\u5bf8 4\u82f1\u5bf8</li>\n\t\t<li>\u9891\u8c31\u5206\u6790\u4eea\u6a21\u5f0f\uff0c\u521d\u59cb\u72b6\u6001\u4e3a10KHz-800MHz\uff0c\u5728\u542f\u7528\u72ec\u7279\u7684Ultra\u6a21\u5f0f\u7684\u60c5\u51b5\u4e0b\uff0c\u53ef\u4ee5\u76d1\u6d4b\u9ad8\u8fbe12GHz\u7684\u4fe1\u53f7\u3002</li>\n\t\t<li>\u4fe1\u53f7\u53d1\u751f\u5668\u6a21\u5f0f\uff0c\u6b63\u5f26\u6ce2\u8f93\u51fa\u5728100KHz-800MHz\u4e4b\u95f4\uff0c\u5c04\u9891\u6d4b\u8bd5\u4fe1\u53f7\u7684\u65b9\u6ce2\u8f93\u51fa\u9ad8\u8fbe5.3GHz\u3002</li>\n\t\t<li>200Hz\u81f3850KHz\u7684RBW\u8bbe\u7f6e\u63d0\u4f9b\u66f4\u9ad8\u7684\u7075\u654f\u5ea6\u8303\u56f4\u3002</li>\n\t\t<li>\u5185\u7f6e 20dB \u53ef\u9009 LNA</li>\n\t\t<li>\u5f69\u8272\u663e\u793a\u5c4f\u663e\u793a\u6700\u5927 450 \u4e2a\u70b9\uff0c\u63d0\u4f9b\u957f\u8fbe\u6574\u4e2a\u9891\u7387\u8303\u56f4\u7684\u65e0\u95f4\u9699\u8986\u76d6\u3002</li>\n\t\t<li>MicroSD\u5361\u63d2\u69fd\uff0c\u7528\u4e8e\u5b58\u50a8\u6d4b\u91cf\u503c\uff0c\u8bbe\u7f6e\u548c\u5c4f\u5e55\u622a\u56fe\u3002</li>\n\t</ul>\n\t</li>\n\t<li>\u8f93\u5165\u6b65\u8fdb\u8870\u51cf\u5668\u4ece0dB\u523031dB\uff08\u4e0d\u80fd\u4e0eLNA\u7ed3\u5408\u4f7f\u7528\uff09\u3002</li>\n\t<li>\u5185\u7f6e\u6821\u51c6\u4fe1\u53f7\u53d1\u751f\u5668\uff0c\u7528\u4e8e\u81ea\u52a8\u81ea\u68c0\u548c\uff08\u4f4e\uff09\u8f93\u5165\u6821\u51c6\u3002</li>\n\t<li>\u901a\u8fc7USB\u8fde\u63a5\u5230PC\uff0c\u5b83\u6210\u4e3aPC\u63a7\u5236\u7684\u9891\u8c31\u5206\u6790\u4eea\u6216\u4fe1\u53f7\u53d1\u751f\u5668</li>\n\t<li>\u9ad8\u8fbe3000mah\u7684\u53ef\u5145\u7535\u7535\u6c60\uff0c\u53ef\u643a\u5e26\u81f3\u5c112\u5c0f\u65f6\u3002</li>\n\t<li>\u6700\u5927\u8f93\u5165\u7535\u5e73 +6dBm\u3002</li>\n\t<li>\u4fe1\u53f7\u53d1\u751f\u5668\u529f\u80fd\u4e0d\u80fd\u7528\u4f5c\u8ddf\u8e2a\u53d1\u751f\u5668\uff0c\u56e0\u4e3a\u60a8\u4e0d\u80fd\u540c\u65f6\u4f7f\u7528\u9891\u8c31\u5206\u6790\u4eea\u548c\u4fe1\u53f7\u53d1\u751f\u5668\u529f\u80fd\u3002</li>\n\t<li>\u7531\u4e8e\u4f4e\u6210\u672c\u548c\u975e\u5e38\u5c0f\u7684\u5916\u5f62\u5c3a\u5bf8\uff0c\u5b58\u5728\u67d0\u4e9b\u76f8\u5173\u7684\u5fae\u5c0fSA\u9650\u5236\u548c\u5fae\u5c0fSA\u8d85\u9650\u5236\u3002</li>\n</ul>\n\n<figure><img alt=\"\" src=\"https://tinysa.org/wiki/uploads/Main/tinySA_housing.jpg\"></figure>\n\n<figure><img alt=\"\" src=\"https://tinysa.org/wiki/uploads/Main/tinySA_ultra.jpg\"></figure>\n\n<p><strong>\u89c6\u9891\u6559\u5b66\uff1a</strong></p>\n\n<p>\u53ef\u4ee5\u5728B\u7ad9\u4e5f\u5c31\u662f\u54d4\u54e9\u54d4\u54e9_bilibili\u7f51\u7ad9\u641c\u7d22TinyRFEquip\u8d26\u53f7\u627e\u5230\u4ecb\u7ecdTinySA\u548cTinySA Ultra\u4ee5\u53ca\u5176\u4ed6TinyRFEquip\u4eea\u5668\u7684\u4e3b\u8981\u529f\u80fd\u4ecb\u7ecd\u89c6\u9891\u3002\u4f8b\u5982\uff1a</p>\n\n<p><a href=\"https://www.bilibili.com/video/BV1yt421u7Y2/?vd_source=8d60a323bdde2d574cb0a85c07cb3212\">TinySA Ultra\u5bf9\u4e8e\u65e0\u7ebf\u8bdd\u7b52\u7684\u9891\u7387\u7279\u6027\u68c0\u5b9a\u6d4b\u91cf_\u54d4\u54e9\u54d4\u54e9_bilibili</a></p>\n\n<p>https://www.bilibili.com/video/BV1yt421u7Y2/?vd_source=8d60a323bdde2d574cb0a85c07cb3212</p>\n\n<p><strong>\u6cd5\u5f8b\u5185\u5bb9</strong></p>\n\n<p>TinySA\u548cTinySA Ultra\u7684\u540d\u79f0\u4ee5\u53caTinySA\u5fbd\u6807\u662f\u6211\u4eec\u62e5\u6709\u7684\u6ce8\u518c\u5546\u6807\u3002\u672a\u7ecf\u4e66\u9762\u8bb8\u53ef\uff0c\u4e0d\u5141\u8bb8\u5176\u4ed6\u4eba\u4f7f\u7528TinySA\u8fd9\u4e2a\u540d\u5b57 \u6216 TinySA Ultra \u7528\u4e8e\u4efb\u4f55\u9891\u8c31\u5206\u6790\u4eea\u4ea7\u54c1\u3002</p>"}}]}','{"plugins": [{"pk": 10452, "creation_date": "2024-12-20T12:37:21.671Z", "position": 0, "plugin_type": "TextPlugin", "parent_id": 10451, "data": {"body": "<ul>\n\t<li id=\"bundle-v2-btf-component-bullet-point-2-1\">[Upgraded Professional LibreVNA] LibreVNA is a open-source hardware, USB based full 2-port vector network analyzer (VNA) designed by Jankae, provides a 100kHz to 6GHz ultra-wide frequency range. Updated 6-layer PCB design that optimizes S12 port isolation and high-frequency port matching. Supports firmware update and can load a new microcontroller firmware and FPGA configuration into the LibreVNA</li>\n\t<li id=\"bundle-v2-btf-component-bullet-point-2-2\">[Comparable to Lab-grade Nano VNA] The ultra-low noise power supply design and the use of 16bit ADC, together with the precision CNC''s aluminum shielded housing, achieve up to 100dB of effective dynamics. Using 3 ADCs to sample data simultaneously and using FPGAs for signal processing, Libre VNA handheld antenna Analyzer is capable of scanning over 10,000 points of full dual-port measurements in less than 1 second</li>\n\t<li id=\"bundle-v2-btf-component-bullet-point-2-3\">[Frequency range] Supports a wide range of frequency measurements from 100kHz to 6GHz, upgraded Frequency Accuracy is &lt;2ppm. The S12 can achieve over 90dB of port isolation below 3GHz, allowing measurements above 6GHz use harmonics. During up to 9GHz actual tests, both S11 and S22 have more than 10dB port directivity, and S12, S21 have more than 40dB dynamics</li>\n\t<li id=\"bundle-v2-btf-component-bullet-point-2-4\">[Full S-Parameters Measurements] In the LibreVNA operating mode, the VNA can measure the complete S11, S21, S12 and S21 parameters. A source signal is generated and alternately applied to the RF ports. This incoming signal at both RF ports is measured, resulting in the four S-parameters S11 and S21(when signal routes to Port 1), as well as S12 and S22(when signal routes to Port 2)</li>\n\t<li id=\"bundle-v2-btf-component-bullet-point-2-5\">[3 In 1 Device] Although the VNA hardware is not designed to be used as spectrum analyzer and signal generator, the general hardware architecture of a spectrum analyzer and signal generator are similar enough to that of a VNA to implement basic spectrum measurements and output a CW signal, which might suffice if no other equipment is available. The main differences to a real spectrum analyzer and signal generator please refer to the product manual</li>\n\t<li id=\"bundle-v2-btf-component-bullet-point-2-6\">[PC Software Control] The LibreVNA needs to be used with the host computer software and a separate screen, as it does not have a built-in monitor. LibreVNA provides software for the Windows and Ubuntu platforms. You just need to download and unzip it to run. Supported Operating System: Windows, Linux, MacOS. (Only 64-bit software is available for now)</li>\n\t<li id=\"bundle-v2-btf-component-bullet-point-2-7\">[Packing List] 1x LibreVNA host, 1x USB type-C data cable, 1x USB power cable, 2x 30cm SMA male to male SS405 RF cable, 1x SMA male calibration kit - OPEN, 1x SMA male calibration kit - SHORT, 2x SMA male calibration kit - LOAD, 2x SMA female to female connector, 2x SMA male to male connector, 1x English manual. The LibreVNA is highly functional and capable of meeting the demands of RF engineers, researchers, or hobbyists for a wide range of RF measurements and microwave network parameter measurement</li>\n</ul>"}}]}','en',1,1084,77);
INSERT INTO djangocms_history_placeholderaction VALUES(1100,'change_plugin','{"plugins": [{"pk": 10452, "creation_date": "2024-12-20T12:37:21.671Z", "position": 0, "plugin_type": "TextPlugin", "parent_id": 10451, "data": {"body": "<ul>\n\t<li id=\"bundle-v2-btf-component-bullet-point-2-1\">[Upgraded Professional LibreVNA] LibreVNA is a open-source hardware, USB based full 2-port vector network analyzer (VNA) designed by Jankae, provides a 100kHz to 6GHz ultra-wide frequency range. Updated 6-layer PCB design that optimizes S12 port isolation and high-frequency port matching. Supports firmware update and can load a new microcontroller firmware and FPGA configuration into the LibreVNA</li>\n\t<li id=\"bundle-v2-btf-component-bullet-point-2-2\">[Comparable to Lab-grade Nano VNA] The ultra-low noise power supply design and the use of 16bit ADC, together with the precision CNC''s aluminum shielded housing, achieve up to 100dB of effective dynamics. Using 3 ADCs to sample data simultaneously and using FPGAs for signal processing, Libre VNA handheld antenna Analyzer is capable of scanning over 10,000 points of full dual-port measurements in less than 1 second</li>\n\t<li id=\"bundle-v2-btf-component-bullet-point-2-3\">[Frequency range] Supports a wide range of frequency measurements from 100kHz to 6GHz, upgraded Frequency Accuracy is &lt;2ppm. The S12 can achieve over 90dB of port isolation below 3GHz, allowing measurements above 6GHz use harmonics. During up to 9GHz actual tests, both S11 and S22 have more than 10dB port directivity, and S12, S21 have more than 40dB dynamics</li>\n\t<li id=\"bundle-v2-btf-component-bullet-point-2-4\">[Full S-Parameters Measurements] In the LibreVNA operating mode, the VNA can measure the complete S11, S21, S12 and S21 parameters. A source signal is generated and alternately applied to the RF ports. This incoming signal at both RF ports is measured, resulting in the four S-parameters S11 and S21(when signal routes to Port 1), as well as S12 and S22(when signal routes to Port 2)</li>\n\t<li id=\"bundle-v2-btf-component-bullet-point-2-5\">[3 In 1 Device] Although the VNA hardware is not designed to be used as spectrum analyzer and signal generator, the general hardware architecture of a spectrum analyzer and signal generator are similar enough to that of a VNA to implement basic spectrum measurements and output a CW signal, which might suffice if no other equipment is available. The main differences to a real spectrum analyzer and signal generator please refer to the product manual</li>\n\t<li id=\"bundle-v2-btf-component-bullet-point-2-6\">[PC Software Control] The LibreVNA needs to be used with the host computer software and a separate screen, as it does not have a built-in monitor. LibreVNA provides software for the Windows and Ubuntu platforms. You just need to download and unzip it to run. Supported Operating System: Windows, Linux, MacOS. (Only 64-bit software is available for now)</li>\n\t<li id=\"bundle-v2-btf-component-bullet-point-2-7\">[Packing List] 1x LibreVNA host, 1x USB type-C data cable, 1x USB power cable, 2x 30cm SMA male to male SS405 RF cable, 1x SMA male calibration kit - OPEN, 1x SMA male calibration kit - SHORT, 2x SMA male calibration kit - LOAD, 2x SMA female to female connector, 2x SMA male to male connector, 1x English manual. The LibreVNA is highly functional and capable of meeting the demands of RF engineers, researchers, or hobbyists for a wide range of RF measurements and microwave network parameter measurement</li>\n</ul>"}}]}','{"plugins": [{"pk": 10452, "creation_date": "2024-12-20T12:37:21.671Z", "position": 0, "plugin_type": "TextPlugin", "parent_id": 10451, "data": {"body": "<ul>\n\t<li id=\"bundle-v2-btf-component-bullet-point-2-1\">[Upgraded Professional LibreVNA] LibreVNA is a open-source hardware, USB based full 2-port vector network analyzer (VNA) designed by Jankae, provides a 100kHz to 6GHz ultra-wide frequency range. Updated 6-layer PCB design that optimizes