INSERT INTO djangocms_history_placeholderaction VALUES(1104,'change_plugin','{"plugins": [{"pk": 10446, "creation_date": "2024-12-20T12:31:27.640Z", "position": 2, "plugin_type": "TextPlugin", "parent_id": 10443, "data": {"body": "<p>LibreVNA 2025 is a 100kHz-6GHz Vector Network Analyzer USB Based Full 2-Port with External Reference Input/Output,6-Layer PCB Design Measure Full S-Parameters. Special design with 6mm fins installed on the top side and 4 positioning holes are installed on the bottom side, so customers can install larger heat sinks or feet (M3*6 nuts) for easy use.\u00a0The 2025 version also replaces the original brass SMA with a four-hole flange stainless steel SMA with more torque, both SMA fittings that can support up to 18G.</p>"}}]}','{"plugins": [{"pk": 10446, "creation_date": "2024-12-20T12:31:27.640Z", "position": 2, "plugin_type": "TextPlugin", "parent_id": 10443, "data": {"body": "<p>LibreVNA 2025 is a 100kHz-6GHz Vector Network Analyzer USB Based Full 2-Port with External Reference Input/Output,6-Layer PCB Design Measure Full S-Parameters. Special design with 6mm fins installed on the top side and 4 positioning holes are installed on the bottom side, so customers can install larger heat sinks or feet (M3*6 nuts) for easy use.\u00a0The 2025 version also replaces the original brass SMA with a four-hole flange stainless steel SMA with more torque, both SMA fittings that can support up to 18G.</p>\n\n<p>You can buy from\u00a0<cms-plugin alt=\"Link / Button - Link (13605) \" title=\"Link / Button - Link (13605)\" id=\"13605\"></cms-plugin><cms-plugin alt=\"Link / Button - Link (13604) \" title=\"Link / Button - Link (13604)\" id=\"13604\"></cms-plugin></p>"}}]}','en',1,1088,77);
