INSERT INTO djangocms_history_placeholderaction VALUES(1106,'change_plugin','{"plugins": [{"pk": 10446, "creation_date": "2024-12-20T12:31:27.640Z", "position": 2, "plugin_type": "TextPlugin", "parent_id": 10443, "data": {"body": "<p>LibreVNA 2025 is a 100kHz-6GHz Vector Network Analyzer USB Based Full 2-Port with External Reference Input/Output,6-Layer PCB Design Measure Full S-Parameters. Special design with 6mm fins installed on the top side and 4 positioning holes are installed on the bottom side, so customers can install larger heat sinks or feet (M3*6 nuts) for easy use.\u00a0The 2025 version also replaces the original brass SMA with a four-hole flange stainless steel SMA with more torque, both SMA fittings that can support up to 18G.</p>\n\n<p>You can buy from\u00a0<cms-plugin alt=\"Link / Button - Link (13605) \" title=\"Link / Button - Link (13605)\" id=\"13605\"></cms-plugin><cms-plugin alt=\"Link / Button - Link (13604) \" title=\"Link / Button - Link (13604)\" id=\"13604\"></cms-plugin></p>"}}]}','{"plugins": [{"pk": 10446, "creation_date": "2024-12-20T12:31:27.640Z", "position": 2, "plugin_type": "TextPlugin", "parent_id": 10443, "data": {"body": "<p>LibreVNA 2025 is a 100kHz-6GHz Vector Network Analyzer USB Based Full 2-Port with External Reference Input/Output,6-Layer PCB Design Measure Full S-Parameters. Special design with 6mm fins installed on the top side and 4 positioning holes are installed on the bottom side, so customers can install larger heat sinks or feet (M3*6 nuts) for easy use.\u00a0The 2025 version also replaces the original brass SMA with a four-hole flange stainless steel SMA with more torque, both SMA fittings that can support up to 18G.</p>\n\n<p>You can buy from\u00a0<cms-plugin alt=\"Link / Button - Link (13605) \" title=\"Link / Button - Link (13605)\" id=\"13605\"></cms-plugin></p>\n\n<p>You can learn by video from<cms-plugin alt=\"Link / Button - Link (13628) \" title=\"Link / Button - Link (13628)\" id=\"13628\"></cms-plugin><cms-plugin alt=\"Link / Button - Link (13604) \" title=\"Link / Button - Link (13604)\" id=\"13604\"></cms-plugin></p>"}}]}','en',1,1089,77);
INSERT INTO djangocms_history_placeholderaction VALUES(1107,'add_plugin','{"order": [13604, 13605], "parent_id": 10446}','{"order": [13604, 13605, 13628], "parent_id": 10446, "plugins": [{"pk": 13628, "creation_date": "2025-03-09T13:16:12.737Z", "position": 2, "plugin_type": "LinkPlugin", "parent_id": 10446, "data": {"ui_item": "Link", "tag_type": "div", "config": {"name": "Youtube Link", "template": "default", "link_type": "link", "link_context": "", "link_size": "", "link_outline": false, "link_block": false, "icon_left": "", "icon_right": "", "link_stretched": false, "attributes": {}, "margin_x": "", "margin_y": "", "margin_devices": null, "padding_x": "", "padding_y": "", "padding_devices": null, "external_link": "https://www.youtube.com/@RFTinyEquip-Terry", "internal_link": "", "file_link": null, "anchor": "", "mailto": "", "phone": "", "target": ""}}}]}','en',2,1089,77);
INSERT INTO djangocms_history_placeholderaction VALUES(1108,'change_plugin','{"plugins": [{"pk": 1340, "creation_date": "2024-12-20T12:31:27.640Z", "position": 2, "plugin_type": "TextPlugin", "parent_id": 1337, "data": {"body": "<p><strong>\u00a0TinySA Ultra\u00a0TinySA Ultra\u00a0TinySA Ultra\u00a0TinySA Ultra\u00a0TinySA Ultra\u00a0TinySA Ultra\u00a0TinySA Ultra\u00a0TinySA Ultra</strong></p>"}}]}','{"plugins": [{"pk": 1340, "creation_date": "2024-12-20T12:31:27.640Z", "position": 2, "plugin_type": "TextPlugin", "parent_id": 1337, "data": {"body": "<ul>\n\t<li>Tinysa ULTRA+ zs406 owns high performance frequency in 100khz to 900MHz, and when in ultra mode, the analyzer can reach 5.4GHz. With new 4'''' touchscreen display and installed with the latest hardware system V0.4.6. Built-in 32Gb micro TF\u00a0card for data transfer and storage</li>\n\t<li>[Frequency Range] Tinysa ultra measures from 100KHz-5.4GHz: Spectrum Analyzer for 0.1MHz-900MHz, with Ultra mode enabled, level calibrated up to 6GHz, can observe signals up to 12GHz. RBW from 200Hz-850kHz, you can fast and accurate execute measurement tests. Color display showing max 450 points providing gapless covering up to the full frequency range</li>\n</ul>"}}]}','en',1,1090,47);
INSERT INTO djangocms_history_placeholderaction VALUES(1109,'change_plugin','{"plugins": [{"pk": 1346, "creation_date": "2024-12-20T12:37:21.671Z", "position": 0, "plugin_type": "TextPlugin", "parent_id": 1345, "data": {"body": "<p><strong>TinySA\u662f\u4e00\u79cd\u5c0f\u578b\u9891\u8c31\u5206\u6790\u4eea\u548c\u4fe1\u53f7\u53d1\u751f\u5668\uff0c\u5177\u6709\u4e00\u4e9b\u4e0d\u9519\u7684\u529f\u80fd\uff1a</strong></p>\n\n<ul>\n\t<li><strong>TinySA\u57fa\u672c\u7279\u70b9:</strong>\n\n\t<ul>\n\t\t<li>\u5c4f\u5e55\u5c3a\u5bf8 2.8\u82f1\u5bf8</li>\n\t\t<li>\u5e26\u4e24\u4e2a\u8f93\u5165\u7aef\u53e3\u7684\u9891\u8c31\u5206\u6790\u4eea\uff0cLow\u7aef\u53e3\u7528\u4e8e 10KHz-350MHz \u7684\u9ad8\u8d28\u91cf MF/HF/VHF \u8f93\u5165\uff0cHigh\u7aef\u53e3\u7528\u4e8e 240MHz-960MHz \u7684 UHF \u8f93\u5165\u3002</li>\n\t\t<li>\u4fe1\u53f7\u53d1\u751f\u5668\u5177\u6709\u4e24\u4e2a\u8f93\u51fa\uff0c\u6b63\u5f26\u6ce2\u8f93\u51fa\u4e3a100KHz - 350MHz\uff0c\u65b9\u6ce2\u8f93\u51fa\u4e3a 240MHz-960MHz\uff0c\u4fe1\u53f7\u53d1\u751f\u5668\u548c\u9891\u8c31\u5206\u6790\u4eea\u540c\u4e00\u65f6\u523b\u53ea\u80fd\u9009\u62e9\u5176\u4e2d\u7684\u4e00\u4e2a\u529f\u80fd\u3002</li>\n\t\t<li>\u5f69\u8272\u663e\u793a\u5c4f\u663e\u793a\u6700\u591a 290\u4e2a\u626b\u63cf\u70b9\uff0c\u63d0\u4f9b\u957f\u8fbe\u6574\u4e2a\u4f4e\u9891\u6216\u9ad8\u9891\u8303\u56f4\u7684\u65e0\u95f4\u9699\u8986\u76d6\u3002</li>\n\t</ul>\n\t</li>\n\t<li><strong>TinySA</strong>\u00a0<strong>Ultra\u57fa\u672c\u7279\u70b9:</strong>\n\t<ul>\n\t\t<li>\u5c4f\u5e55\u5c3a\u5bf8 fsfda\u00a0</li>\n\t\t<li>\u9891\u8c31\u5206\u6790\u4eea\u6a21\u5f0f\uff0c\u521d\u59cb\u72b6\u6001\u4e3a10KHz-800MHz\uff0c\u5728\u542f\u7528\u72ec\u7279\u7684Ultra\u6a21\u5f0f\u7684\u60c5\u51b5\u4e0b\uff0c\u53ef\u4ee5\u76d1\u6d4b\u9ad8\u8fbe12GHz\u7684\u4fe1\u53f7\u3002</li>\n\t\t<li>\u4fe1\u53f7\u53d1\u751f\u5668\u6a21\u5f0f\uff0c\u6b63\u5f26\u6ce2\u8f93\u51fa\u5728100KHz-800MHz\u4e4b\u95f4\uff0c\u5c04\u9891\u6d4b\u8bd5\u4fe1\u53f7\u7684\u65b9\u6ce2\u8f93\u51fa\u9ad8\u8fbe5.3GHz\u3002</li>\n\t\t<li>200Hz\u81f3850KHz\u7684RBW\u8bbe\u7f6e\u63d0\u4f9b\u66f4\u9ad8\u7684\u7075\u654f\u5ea6\u8303\u56f4\u3002</li>\n\t\t<li>\u5185\u7f6e 20dB \u53ef\u9009 LNA</li>\n\t\t<li>\u5f69\u8272\u663e\u793a\u5c4f\u663e\u793a\u6700\u5927 450 \u4e2a\u70b9\uff0c\u63d0\u4f9b\u957f\u8fbe\u6574\u4e2a\u9891\u7387\u8303\u56f4\u7684\u65e0\u95f4\u9699\u8986\u76d6\u3002</li>\n\t\t<li>MicroSD\u5361\u63d2\u69fd\uff0c\u7528\u4e8e\u5b58\u50a8\u6d4b\u91cf\u503c\uff0c\u8bbe\u7f6e\u548c\u5c4f\u5e55\u622a\u56fe\u3002</li>\n\t</ul>\n\t</li>\n\t<li>\u8f93\u5165\u6b65\u8fdb\u8870\u51cf\u5668\u4ece0dB\u523031dB\uff08\u4e0d\u80fd\u4e0eLNA\u7ed3\u5408\u4f7f\u7528\uff09\u3002</li>\n\t<li>\u5185\u7f6e\u6821\u51c6\u4fe1\u53f7\u53d1\u751f\u5668\uff0c\u7528\u4e8e\u81ea\u52a8\u81ea\u68c0\u548c\uff08\u4f4e\uff09\u8f93\u5165\u6821\u51c6\u3002</li>\n\t<li>\u901a\u8fc7USB\u8fde\u63a5\u5230PC\uff0c\u5b83\u6210\u4e3aPC\u63a7\u5236\u7684\u9891\u8c31\u5206\u6790\u4eea\u6216\u4fe1\u53f7\u53d1\u751f\u5668</li>\n\t<li>\u9ad8\u8fbe3000mah\u7684\u53ef\u5145\u7535\u7535\u6c60\uff0c\u53ef\u643a\u5e26\u81f3\u5c112\u5c0f\u65f6\u3002</li>\n\t<li>\u6700\u5927\u8f93\u5165\u7535\u5e73 +6dBm\u3002</li>\n\t<li>\u4fe1\u53f7\u53d1\u751f\u5668\u529f\u80fd\u4e0d\u80fd\u7528\u4f5c\u8ddf\u8e2a\u53d1\u751f\u5668\uff0c\u56e0\u4e3a\u60a8\u4e0d\u80fd\u540c\u65f6\u4f7f\u7528\u9891\u8c31\u5206\u6790\u4eea\u548c\u4fe1\u53f7\u53d1\u751f\u5668\u529f\u80fd\u3002</li>\n\t<li>\u7531\u4e8e\u4f4e\u6210\u672c\u548c\u975e\u5e38\u5c0f\u7684\u5916\u5f62\u5c3a\u5bf8\uff0c\u5b58\u5728\u67d0\u4e9b\u76f8\u5173\u7684\u5fae\u5c0fSA\u9650\u5236\u548c\u5fae\u5c0fSA\u8d85\u9650\u5236\u3002</li>\n</ul>\n\n<figure><img alt=\"\" src=\"https://tinysa.org/wiki/uploads/Main/tinySA_housing.jpg\"></figure>\n\n<figure><img alt=\"\" src=\"https://tinysa.org/wiki/uploads/Main/tinySA_ultra.jpg\"></figure>\n\n<p><strong>\u89c6\u9891\u6559\u5b66\uff1a</strong></p>\n\n<p>\u53ef\u4ee5\u5728B\u7ad9\u4e5f\u5c31\u662f\u54d4\u54e9\u54d4\u54e9_bilibili\u7f51\u7ad9\u641c\u7d22TinyRFEquip\u8d26\u53f7\u627e\u5230\u4ecb\u7ecdTinySA\u548cTinySA Ultra\u4ee5\u53ca\u5176\u4ed6TinyRFEquip\u4eea\u5668\u7684\u4e3b\u8981\u529f\u80fd\u4ecb\u7ecd\u89c6\u9891\u3002\u4f8b\u5982\uff1a</p>\n\n<p><a href=\"https://www.bilibili.com/video/BV1yt421u7Y2/?vd_source=8d60a323bdde2d574cb0a85c07cb3212\">TinySA Ultra\u5bf9\u4e8e\u65e0\u7ebf\u8bdd\u7b52\u7684\u9891\u7387\u7279\u6027\u68c0\u5b9a\u6d4b\u91cf_\u54d4\u54e9\u54d4\u54e9_bilibili</a></p>\n\n<p>https://www.bilibili.com/video/BV1yt421u7Y2/?vd_source=8d60a323bdde2d574cb0a85c07cb3212</p>\n\n<p><strong>\u6cd5\u5f8b\u5185\u5bb9</strong></p>\n\n<p>TinySA\u548cTinySA Ultra\u7684\u540d\u79f0\u4ee5\u53caTinySA\u5fbd\u6807\u662f\u6211\u4eec\u62e5\u6709\u7684\u6ce8\u518c\u5546\u6807\u3002\u672a\u7ecf\u4e66\u9762\u8bb8\u53ef\uff0c\u4e0d\u5141\u8bb8\u5176\u4ed6\u4eba\u4f7f\u7528TinySA\u8fd9\u4e2a\u540d\u5b57 \u6216 TinySA Ultra \u7528\u4e8e\u4efb\u4f55\u9891\u8c31\u5206\u6790\u4eea\u4ea7\u54c1\u3002</p>"}}]}','{"plugins": [{"pk": 1346, "creation_date": "2024-12-20T12:37:21.671Z", "position": 0, "plugin_type": "TextPlugin", "parent_id": 1345, "data": {"body": "<ul>\n\t<li id=\"bundle-v2-btf-component-bullet-point-1-2\">[Upgraded TinySA Ultra ZS406] TinySA Ultra owns high performance frequency in 100khz to 900MHz, and when in ultra mode, the analyzer can reach 5.4GHz. With new 4'''' touchscreen display and installed with the latest hardware system V0.4.6. Built-in 32Gb micro TF card for data transfer and storage</li>\n\t<li id=\"bundle-v2-btf-component-bullet-point-1-3\">[Frequency Range] Tiny sa ultra measures from 100KHz-5.4GHz: Spectrum Analyzer for 0.1MHz-900MHz, with Ultra mode enabled, level calibrated up to 6GHz, can observe signals up to 12GHz. RBW can be set from 200Hz-850kHz, you can fast and accurate execute measurement tests. Color display showing max 450 points providing gapless covering up to the full frequency range</li>\n\t<li id=\"bundle-v2-btf-component-bullet-point-1-4\">[2 in 1 Device] When not used as Spectrum Analyzer it can be used as Signal Generator, MF/HF/VHF sinus output between 100kHZ-900MHz, UHF square wave output between 800mHz-4.4GHz, Mixing signal output is between 4.4GHz-5.4GHz. Built-in calibration signal generator that is used for automatic self test and level calibration</li>\n\t<li id=\"bundle-v2-btf-component-bullet-point-1-5\">[PC Operation] Connected to a PC via USB. The USB interface implements CDC protocol and there is a large set of commands that can be invoked over the serial interface. These command can be used to perform MEAS or update internal settings. Tinysa-APP transfers data directly to the computer. The driver for Windows will install automatically after connecting to a Windows10 or Win11 PC. The driver for Linux is built into the kernel</li>\n\t<li id=\"bundle-v2-btf-component-bullet-point-1-6\">[200Hz-850kHz RBW] RBW frequency from 200hz to 850khz which can be set to match the measurement requirements, meet SBB two-tone test requirements and fast scanning. The RBW is as low as 200Hz, which can effectively distinguish adjacent signals and meet the requirements of SSB dual-satellite inter-modulation test. Input Step attenuator from 0dB to 31dB (can not be used not in combination with LNA)</li>\n\t<li id=\"bundle-v2-btf-component-bullet-point-1-7\">[What You Get] 1x Tinysa ULTRA (4inch touchscreen, 5000mah rechargeable battery); 2x 30cm ALSR100 SMA cables; 1 x USB Type-C data cable; 1x SMA-SMA barrel connector; 1x TLanyard and touch plectrum; 1x Antenna with SMA connector; 1x 32GB MicroSD card(plugged in the host), 1x Stylus Pen</li>\n</ul>\n\n<figure>\u00a0</figure>\n\n<figure><img alt=\"\" src=\"https://tinysa.org/wiki/uploads/Main/tinySA_ultra.jpg\"></figure>\n\n<p>\u00a0</p>"}}]}','en',1,1091,47);
INSERT INTO djangocms_history_placeholderaction VALUES(1110,'change_plugin','{"plugins": [{"pk": 1345, "creation_date": "2024-12-20T12:36:25.484Z", "position": 0, "plugin_type": "TabItemPlugin", "parent_id": 1344, "data": {"ui_item": "TabItem", "tag_type": "div", "config": {"tab_title": "\u4ea7\u54c1\u8be6\u60c5", "tab_bordered": false, "attributes": {}, "padding_x": "", "padding_y": "", "padding_devices": null}}}]}','{"plugins": [{"pk": 1345, "creation_date": "2024-12-20T12:36:25.484Z", "position": 0, "plugin_type": "TabItemPlugin", "parent_id": 1344, "data": {"ui_item": "TabItem", "tag_type": "div", "config": {"tab_title": "Product Detail:", "tab_bordered": false, "attributes": {}, "padding_x": "", "padding_y": "", "padding_devices": null}}}]}','en',1,1092,47);
INSERT INTO djangocms_history_placeholderaction VALUES(1111,'change_plugin','{"plugins": [{"pk": 1346, "creation_date": "2024-12-20T12:37:21.671Z", "position": 0, "plugin_type": "TextPlugin", "parent_id": 1345, "data": {"body": "<ul>\n\t<li id=\"bundle-v2-btf-component-bullet-point-1-2\">[Upgraded TinySA Ultra ZS406] TinySA Ultra owns high performance frequency in 100khz to 900MHz, and when in ultra mode, the analyzer can reach 5.4GHz. With new 4'''' touchscreen display and installed with the latest hardware system V0.4.6. Built-in 32Gb micro TF card for data transfer and storage</li>\n\t<li id=\"bundle-v2-btf-component-bullet-point-1-3\">[Frequency Range] Tiny sa ultra measures from 100KHz-5.4GHz: Spectrum Analyzer for 0.1MHz-900MHz, with Ultra mode enabled, level calibrated up to 6GHz, can observe signals up to 12GHz. RBW can be set from 200Hz-850kHz, you can fast and accurate execute measurement tests. Color display showing max 450 points providing gapless covering up to the full frequency range</li>\n\t<li id=\"bundle-v2-btf-component-bullet-point-1-4\">[2 in 1 Device] When not used as Spectrum Analyzer it can be used as Signal Generator, MF/HF/VHF sinus output between 100kHZ-900MHz, UHF square wave output between 800mHz-4.4GHz, Mixing signal output is between 4.4GHz-5.4GHz. Built-in calibration signal generator that is used for automatic self test and level calibration</li>\n\t<li id=\"bundle-v2-btf-component-bullet-point-1-5\">[PC Operation] Connected to a PC via USB. The USB interface implements CDC protocol and there is a large set of commands that can be invoked over the serial interface. These command can be used to perform MEAS or update internal settings. Tinysa-APP transfers data directly to the computer. The driver for Windows will install automatically after connecting to a Windows10 or Win11 PC. The driver for Linux is built into the kernel</li>\n\t<li id=\"bundle-v2-btf-component-bullet-point-1-6\">[200Hz-850kHz RBW] RBW frequency from 200hz to 850khz which can be set to match the measurement requirements, meet SBB two-tone test requirements and fast scanning. The RBW is as low as 200Hz, which can effectively distinguish adjacent signals and meet the requirements of SSB dual-satellite inter-modulation test. Input Step attenuator from 0dB to 31dB (can not be used not in combination with LNA)</li>\n\t<li id=\"bundle-v2-btf-component-bullet-point-1-7\">[What You Get] 1x Tinysa ULTRA (4inch touchscreen, 5000mah rechargeable battery); 2x 30cm ALSR100 SMA cables; 1 x USB Type-C data cable; 1x SMA-SMA barrel connector; 1x TLanyard and touch plectrum; 1x Antenna with SMA connector; 1x 32GB MicroSD card(plugged in the host), 1x Stylus Pen</li>\n</ul>\n\n<figure>\u00a0</figure>\n\n<figure><img alt=\"\" src=\"https://tinysa.org/wiki/uploads/Main/tinySA_ultra.jpg\"></figure>\n\n<p>\u00a0</p>"}}]}','{"plugins": [{"pk": 1346, "creation_date": "2024-12-20T12:37:21.671Z", "position": 0, "plugin_type": "TextPlugin", "parent_id": 1345, "data": {"body": "<ul>\n\t<li id=\"bundle-v2-btf-component-bullet-point-1-2\">[Upgraded TinySA Ultra ZS406] TinySA Ultra owns high performance frequency in 100khz to 900MHz, and when in ultra mode, the analyzer can reach 5.4GHz. With new 4'''' touchscreen display and installed with the latest hardware system V0.4.6. Built-in 32Gb micro TF card for data transfer and storage</li>\n\t<li id=\"bundle-v2-btf-component-bullet-point-1-3\">[Frequency Range] Tiny sa ultra measures from 100KHz-5.4GHz: Spectrum Analyzer for 0.1MHz-900MHz, with Ultra mode enabled, level calibrated up to 6GHz, can observe signals up to 12GHz. RBW can be set from 200Hz-850kHz, you can fast and accurate execute measurement tests. Color display showing max 450 points providing gapless covering up to the full frequency range</li>\n\t<li id=\"bundle-v2-btf-component-bullet-point-1-4\">[2 in 1 Device] When not used as Spectrum Analyzer it can be used as Signal Generator, MF/HF/VHF sinus output between 100kHZ-900MHz, UHF square wave output between 800mHz-4.4GHz, Mixing signal output is between 4.4GHz-5.4GHz. Built-in calibration signal generator that is used for automatic self test and level calibration</li>\n\t<li id=\"bundle-v2-btf-component-bullet-point-1-5\">[PC Operation] Connected to a PC via USB. The USB interface implements CDC protocol and there is a large set of commands that can be invoked over the serial interface. These command can be used to perform MEAS or update internal settings. Tinysa-APP transfers data directly to the computer. The driver for Windows will install automatically after connecting to a Windows10 or Win11 PC. The driver for Linux is built into the kernel</li>\n\t<li id=\"bundle-v2-btf-component-bullet-point-1-6\">[200Hz-850kHz RBW] RBW frequency from 200hz to 850khz which can be set to match the measurement requirements, meet SBB two-tone test requirements and fast scanning. The RBW is as low as 200Hz, which can effectively distinguish adjacent signals and meet the requirements of SSB dual-satellite inter-modulation test. Input Step attenuator from 0dB to 31dB (can not be used not in combination with LNA)</li>\n\t<li id=\"bundle-v2-btf-component-bullet-point-1-7\">[What You Get] 1x Tinysa ULTRA (4inch touchscreen, 5000mah rechargeable battery); 2x 30cm ALSR100 SMA cables; 1 x USB Type-C data cable; 1x SMA-SMA barrel connector; 1x TLanyard and touch plectrum; 1x Antenna with SMA connector; 1x 32GB MicroSD card(plugged in the host), 1x Stylus Pen</li>\n</ul>\n\n<figure>\u00a0</figure>\n\n<figure>\n<p><img alt=\"\" src=\"https://tinysa.org/wiki/uploads/Main/tinySA_ultra.jpg\"></p>\n\n<p>Using TinySa to test saterlite RF module for transmition.</p>\n\n<p><cms-plugin alt=\"Picture / Image - Image (13692) \" title=\"Picture / Image - Image (13692)\" id=\"13692\"></cms-plugin></p>\n</figure>\n\n<p>\u00a0</p>"}}]}','en',1,1093,47);
INSERT INTO djangocms_history_placeholderaction VALUES(1112,'add_plugin','{"order": [], "parent_id": 1346}','{"order": [13692], "parent_id": 1346, "plugins": [{"pk": 13692, "creation_date": "2025-03-09T13:34:20.316Z", "position": 0, "plugin_type": "ImagePlugin", "parent_id": 1346, "data": {"ui_item": "Image", "tag_type": "div", "config": {"template": "default", "picture": {"model": "filer.image", "pk": 119}, "external_picture": "", "lazy_loading": false, "width": null, "height": null, "alignment": "", "link_attributes": {}, "use_automatic_scaling": false, "use_crop": false, "use_no_cropping": false, "use_upscale": false, "use_responsive_image": "inherit", "thumbnail_options": null, "picture_fluid": true, "picture_rounded": false, "picture_thumbnail": false, "attributes": {}, "external_link": "", "internal_link": "", "file_link": null, "anchor": "", "mailto": "", "phone": "", "target": "", "responsive_visibility": null, "margin_x": "", "margin_y": "", "margin_devices": null}}}]}','en',2,1093,47);
INSERT INTO djangocms_history_placeholderaction VALUES(1113,'change_plugin','{"plugins": [{"pk": 1346, "creation_date": "2024-12-20T12:37:21.671Z", "position": 0, "plugin_type": "TextPlugin", "parent_id": 1345, "data": {"body": "<ul>\n\t<li id=\"bundle-v2-btf-component-bullet-point-1-2\">[Upgraded TinySA Ultra ZS406] TinySA Ultra owns high performance frequency in 100khz to 900MHz, and when in ultra mode, the analyzer can reach 5.4GHz. With new 4'''' touchscreen display and installed with the latest hardware system V0.4.6. Built-in 32Gb micro TF card for data transfer and storage</li>\n\t<li id=\"bundle-v2-btf-component-bullet-point-1-3\">[Frequency Range] Tiny sa ultra measures from 100KHz-5.4GHz: Spectrum Analyzer for 0.1MHz-900MHz, with Ultra mode enabled, level calibrated up to 6GHz, can observe signals up to 12GHz. RBW can be set from 200Hz-850kHz, you can fast and accurate execute measurement tests. Color display showing max 450 points providing gapless covering up to the full frequency range</li>\n\t<li id=\"bundle-v2-btf-component-bullet-point-1-4\">[2 in 1 Device] When not used as Spectrum Analyzer it can be used as Signal Generator, MF/HF/VHF sinus output between 100kHZ-900MHz, UHF square wave output between 800mHz-4.4GHz, Mixing signal output is between 4.4GHz-5.4GHz. Built-in calibration signal generator that is used for automatic self test and level calibration</li>\n\t<li id=\"bundle-v2-btf-component-bullet-point-1-5\">[PC Operation] Connected to a PC via USB. The USB interface implements CDC protocol and there is a large set of commands that can be invoked over the serial interface. These command can be used to perform MEAS or update internal settings. Tinysa-APP transfers data directly to the computer. The driver for Windows will install automatically after connecting to a Windows10 or Win11 PC. The driver for Linux is built into the kernel</li>\n\t<li id=\"bundle-v2-btf-component-bullet-point-1-6\">[200Hz-850kHz RBW] RBW frequency from 200hz to 850khz which can be set to match the measurement requirements, meet SBB two-tone test requirements and fast scanning. The RBW is as low as 200Hz, which can effectively distinguish adjacent signals and meet the requirements of SSB dual-satellite inter-modulation test. Input Step attenuator from 0dB to 31dB (can not be used not in combination with LNA)</li>\n\t<li id=\"bundle-v2-btf-component-bullet-point-1-7\">[What You Get] 1x Tinysa ULTRA (4inch touchscreen, 5000mah rechargeable battery); 2x 30cm ALSR100 SMA cables; 1 x USB Type-C data cable; 1x SMA-SMA barrel connector; 1x TLanyard and touch plectrum; 1x Antenna with SMA connector; 1x 32GB MicroSD card(plugged in the host), 1x Stylus Pen</li>\n</ul>\n\n<figure>\u00a0</figure>\n\n<figure>\n<p><img alt=\"\" src=\"https://tinysa.org/wiki/uploads/Main/tinySA_ultra.jpg\"></p>\n\n<p>Using TinySa to test saterlite RF module for transmition.</p>\n\n<p><cms-plugin alt=\"Picture / Image - Image (13692) \" title=\"Picture / Image - Image (13692)\" id=\"13692\"></cms-plugin></p>\n</figure>\n\n<p>\u00a0</p>"}}]}','{"plugins": [{"pk": 1346, "creation_date": "2024-12-20T12:37:21.671Z", "position": 0, "plugin_type": "TextPlugin", "parent_id": 1345, "data": {"body": "<ul>\n\t<li id=\"bundle-v2-btf-component-bullet-point-1-2\">[Upgraded TinySA Ultra ZS406] TinySA Ultra owns high performance frequency in 100khz to 900MHz, and when in ultra mode, the analyzer can reach 5.4GHz. With new 4'''' touchscreen display and installed with the latest hardware system V0.4.6. Built-in 32Gb micro TF card for data transfer and storage</li>\n\t<li id=\"bundle-v2-btf-component-bullet-point-1-3\">[Frequency Range] Tiny sa ultra measures from 100KHz-5.4GHz: Spectrum Analyzer for 0.1MHz-900MHz, with Ultra mode enabled, level calibrated up to 6GHz, can observe signals up to 12GHz. RBW can be set from 200Hz-850kHz, you can fast and accurate execute measurement tests. Color display showing max 450 points providing gapless covering up to the full frequency range</li>\n\t<li id=\"bundle-v2-btf-component-bullet-point-1-4\">[2 in 1 Device] When not used as Spectrum Analyzer it can be used as Signal Generator, MF/HF/VHF sinus output between 100kHZ-900MHz, UHF square wave output between 800mHz-4.4GHz, Mixing signal output is between 4.4GHz-5.4GHz. Built-in calibration signal generator that is used for automatic self test and level calibration</li>\n\t<li id=\"bundle-v2-btf-component-bullet-point-1-5\">[PC Operation] Connected to a PC via USB. The USB interface implements CDC protocol and there is a large set of commands that can be invoked over the serial interface. These command can be used to perform MEAS or update internal settings. Tinysa-APP transfers data directly to the computer. The driver for Windows will install automatically after connecting to a Windows10 or Win11 PC. The driver for Linux is built into the kernel</li>\n\t<li id=\"bundle-v2-btf-component-bullet-point-1-6\">[200Hz-850kHz RBW] RBW frequency from 200hz to 850khz which can be set to match the measurement requirements, meet SBB two-tone test requirements and fast scanning. The RBW is as low as 200Hz, which can effectively distinguish adjacent signals and meet the requirements of SSB dual-satellite inter-modulation test. Input Step attenuator from 0dB to 31dB (can not be used not in combination with LNA)</li>\n\t<li id=\"bundle-v2-btf-component-bullet-point-1-7\">[What You Get] 1x Tinysa ULTRA (4inch touchscreen, 5000mah rechargeable battery); 2x 30cm ALSR100 SMA cables; 1 x USB Type-C data cable; 1x SMA-SMA barrel connector; 1x TLanyard and touch plectrum; 1x Antenna with SMA connector; 1x 32GB MicroSD card(plugged in the host), 1x Stylus Pen</li>\n</ul>\n\n<figure>\u00a0</figure>\n\n<figure>\n<p><img alt=\"\" src=\"https://tinysa.org/wiki/uploads/Main/tinySA_ultra.jpg\"></p>\n\n<p>Using TinySA to test satellite RF module for transmission.\u00a0</p>\n\n<p><cms-plugin alt=\"Picture / Image - Image (13692) \" title=\"Picture / Image - Image (13692)\" id=\"13692\"></cms-plugin></p>\n</figure>\n\n<p>\u00a0</p>"}}]}','en',1,1094,47);
