INSERT INTO djangocms_history_placeholderaction VALUES(1136,'change_plugin','{"plugins": [{"pk": 307, "creation_date": "2024-12-18T07:31:25.662Z", "position": 0, "plugin_type": "TextPlugin", "parent_id": 12066, "data": {"body": "<div style=\"margin-top: 13px; text-indent: 0in; text-align: left;\"><span style=\"\"><span style=\"font-weight: normal;\"><span style=\"font-style: normal;\">Welcome to the website of </span></span></span><span style=\"\"><span style=\"font-weight: normal;\"><span style=\"font-style: normal;\">TinyRF</span></span></span><span style=\"\">Equip</span><span style=\"\"><span style=\"font-weight: normal;\"><span style=\"font-style: normal;\">, </span></span></span><span style=\"\"><span style=\"font-weight: normal;\"><span style=\"font-style: normal;\">which covers and introduces </span></span></span><span style=\"\"><span style=\"font-weight: normal;\"><span style=\"font-style: normal;\">microwave </span></span></span><span style=\"\"><span style=\"font-weight: normal;\"><span style=\"font-style: normal;\">test </span></span></span><span style=\"\">e</span><span style=\"\"><span style=\"font-weight: normal;\"><span style=\"font-style: normal;\">quipment</span></span></span><span style=\"\"><span style=\"font-weight: normal;\"><span style=\"font-style: normal;\">, </span></span></span><span style=\"\"><span style=\"font-weight: normal;\"><span style=\"font-style: normal;\">devices, and related radio frequency modules. </span></span><span style=\"unicode-bidi: embed;\"><span style=\"\"><span style=\"\"><span style=\"\"><span style=\"font-weight: normal;\"><span style=\"font-style: normal;\"> These products are mainly used to meet the needs of basic wireless product testing, amateur radio test enthusiasts and students'' learning needs.</span></span></span></span></span></span></span></div>\n\n<div style=\"margin-top: 13px; text-indent: 0in; text-align: left;\"><strong>Our Company is in China MainLand, so we try our best to give you RF products wit