INSERT INTO djangocms_history_placeholderaction VALUES(1157,'change_plugin','{"plugins": [{"pk": 9701, "creation_date": "2024-12-20T12:31:27.640Z", "position": 2, "plugin_type": "TextPlugin", "parent_id": 9698, "data": {"body": "<p>Portable TinySA Spectrum Analyzer, Upgraded V0.3.1 Handheld Tiny Frequency Analyzer 100kHz to 960MHz MF/HF/VHF UHF Input, 2.8 inch Touch Screen with ESD Protect Function</p>"}}]}','{"plugins": [{"pk": 9701, "creation_date": "2024-12-20T12:31:27.640Z", "position": 2, "plugin_type": "TextPlugin", "parent_id": 9698, "data": {"body": "<p>Portable TinySA Spectrum Analyzer, Upgraded V0.3.1 Handheld Tiny Frequency Analyzer 100kHz to 960MHz MF/HF/VHF UHF Input, 2.8 inch Touch Screen with ESD Protect Function</p>\n\n<h2>Product details</h2>\n\n<ul>\n\t<li>Package Dimensions \u200f : \u200e\u00a010.35 x 7.6 x 1.3 inches; 2.2 Pounds</li>\n\t<li>Batteries \u200f : \u200e\u00a01pcs of\u00a0 500mah\u00a0Lithium Ion batteries required. (included)</li>\n</ul>"}}]}','en',1,1133,75);
INSERT INTO djangocms_history_placeholderaction VALUES(1158,'change_plugin','{"plugins": [{"pk": 9701, "creation_date": "2024-12-20T12:31:27.640Z", "position": 2, "plugin_type": "TextPlugin", "parent_id": 9698, "data": {"body": "<p>Portable TinySA Spectrum Analyzer, Upgraded V0.3.1 Handheld Tiny Frequency Analyzer 100kHz to 960MHz MF/HF/VHF UHF Input, 2.8 inch Touch Screen with ESD Protect Function</p>\n\n<h2>Product details</h2>\n\n<ul>\n\t<li>Package Dimensions \u200f : \u200e\u00a010.35 x 7.6 x 1.3 inches; 2.2 Pounds</li>\n\t<li>Batteries \u200f : \u200e\u00a01pcs of\u00a0 500mah\u00a0Lithium Ion batteries required. (included)</li>\n</ul>"}}]}','{"plugins": [{"pk": 9701, "creation_date": "2024-12-20T12:31:27.640Z", "position": 2, "plugin_type": "TextPlugin", "parent_id": 9698, "data": {"body": "<p>Portable TinySA Spectrum Analyzer, Upgraded V0.3.1 Handheld Tiny Frequency Analyzer 100kHz to 960MHz MF/HF/VHF UHF Input, 2.8 inch Touch Screen with ESD Protect Function</p>\n\n<p>Product details</p>\n\n<ul>\n\t<li>Package Dimensions \u200f : \u200e\u00a010.35 x 7.6 x 1.3 inches; 2.2 Pounds</li>\n\t<li>Batteries \u200f : \u200e\u00a01pcs of\u00a0 500mah\u00a0Lithium Ion batteries required. (included)</li>\n</ul>"}}]}','en',1,1134,75);
INSERT INTO djangocms_history_placeholderaction VALUES(1159,'change_plugin','{"plugins": [{"pk": 1346, "creation_date": "2024-12-20T12:37:21.671Z", "position": 0, "plugin_type": "TextPlugin", "parent_id": 1345, "data": {"body": "<ul>\n\t<li id=\"bundle-v2-btf-component-bullet-point-1-2\">[Upgraded TinySA Ultra ZS406] TinySA Ultra owns high performance frequency in 100khz to 900MHz, and when in ultra mode, the analyzer can reach 5.4GHz. With new 4'''' touchscreen display and installed with the latest hardware system V0.4.6. Built-in 32Gb micro TF card for data transfer and storage</li>\n\t<li id=\"bundle-v2-btf-component-bullet-point-1-3\">[Frequency Range] Tiny sa ultra measures from 100KHz-5.4GHz: Spectrum Analyzer for 0.1MHz-900MHz, with Ultra mode enabled, level calibrated up to 6GHz, can observe signals up to 12GHz. RBW can be set from 200Hz-850kHz, you can fast and accurate execute measurement tests. Color display showing max 450 points providing gapless covering up to the full frequency range</li>\n\t<li id=\"bundle-v2-btf-component-bullet-point-1-4\">[2 in 1 Device] When not used as Spectrum Analyzer it can be used as Signal Generator, MF/HF/VHF sinus output between 100kHZ-900MHz, UHF square wave output between 800mHz-4.4GHz, Mixing signal output is between 4.4GHz-5.4GHz. Built-in calibration signal generator that is used for automatic self test and level calibration</li>\n\t<li id=\"bundle-v2-btf-component-bullet-point-1-5\">[PC Operation] Connected to a PC via USB. The USB interface implements CDC protocol and there is a large set of commands that can be invoked over the serial interface. These command can be used to perform MEAS or update internal settings. Tinysa-APP transfers data directly to the computer. The driver for Windows will install automatically after connecting to a Windows10 or Win11 PC. The driver for Linux is built into the kernel</li>\n\t<li id=\"bundle-v2-btf-component-bullet-point-1-6\">[200Hz-850kHz RBW] RBW frequency from 200hz to 850khz which can be set to match the measurement requirements, meet SBB two-tone test requirements and fast scanning. The RBW is as low as 200Hz, which can effectively distinguish adjacent signals and meet the requirements of SSB dual-satellite inter-modulation test. Input Step attenuator from 0dB to 31dB (can not be used not in combination with LNA)</li>\n\t<li id=\"bundle-v2-btf-component-bullet-point-1-7\">[What You Get] 1x Tinysa ULTRA (4inch touchscreen, 5000mah rechargeable battery); 2x 30cm ALSR100 SMA cables; 1 x USB Type-C data cable; 1x SMA-SMA barrel connector; 1x TLanyard and touch plectrum; 1x Antenna with SMA connector; 1x 32GB MicroSD card(plugged in the host), 1x Stylus Pen</li>\n</ul>\n\n<figure>\u00a0</figure>\n\n<figure>\n<p><img alt=\"\" src=\"https://tinysa.org/wiki/uploads/Main/tinySA_ultra.jpg\"></p>\n\n<p>Using TinySA to test satellite RF module for transmission.\u00a0</p>\n\n<p><cms-plugin alt=\"Picture / Image - Image (13692) \" title=\"Picture / Image - Image (13692)\" id=\"13692\"></cms-plugin></p>\n\n<p><cms-plugin alt=\"Picture / Image - Image (13693) \" title=\"Picture / Image - Image (13693)\" id=\"13693\"></cms-plugin></p>\n</figure>\n\n<p>\u00a0</p>"}}]}','{"plugins": [{"pk": 1346, "creation_date": "2024-12-20T12:37:21.671Z", "position": 0, "plugin_type": "TextPlugin", "parent_id": 1345, "data": {"body": "<ul>\n\t<li id=\"bundle-v2-btf-component-bullet-point-1-2\">[Upgraded TinySA Ultra ZS406] TinySA Ultra owns high performance frequency in 100khz to 900MHz, and when in ultra mode, the analyzer can reach 5.4GHz. With new 4'''' touchscreen display and installed with the latest hardware system V0.4.6. Built-in 32Gb micro TF card for data transfer and storage</li>\n\t<li id=\"bundle-v2-btf-component-bullet-point-1-3\">[Frequency Range] Tiny sa ultra measures from 100KHz-5.4GHz: Spectrum Analyzer for 0.1MHz-900MHz, with Ultra mode enabled, level calibrated up to 6GHz, can observe signals up to 12GHz. RBW can be set from 200Hz-850kHz, you can fast and accurate execute measurement tests. Color display showing max 450 points providing gapless covering up to the full frequency range</li>\n\t<li id=\"bundle-v2-btf-component-bullet-point-1-4\">[2 in 1 Device] When not used as Spectrum Analyzer it can be used as Signal Generator, MF/HF/VHF sinus output between 100kHZ-900MHz, UHF square wave output between 800mHz-4.4GHz, Mixing signal output is between 4.4GHz-5.4GHz. Built-in calibration signal generator that is used for automatic self test and level calibration</li>\n\t<li id=\"bundle-v2-btf-component-bullet-point-1-5\">[PC Operation] Connected to a PC via USB. The USB interface implements CDC protocol and there is a large set of commands that can be invoked over the serial interface. These command can be used to perform MEAS or update internal settings. Tinysa-APP transfers data directly to the computer. The driver for Windows will install automatically after connecting to a Windows10 or Win11 PC. The driver for Linux is built into the kernel</li>\n\t<li id=\"bundle-v2-btf-component-bullet-point-1-6\">[200Hz-850kHz RBW] RBW frequency from 200hz to 850khz which can be set to match the measurement requirements, meet SBB two-tone test requirements and fast scanning. The RBW is as low as 200Hz, which can effectively distinguish adjacent signals and meet the requirements of SSB dual-satellite inter-modulation test. Input Step attenuator from 0dB to 31dB (can not be used not in combination with LNA)</li>\n\t<li id=\"bundle-v2-btf-component-bullet-point-1-7\">[What You Get] 1x Tinysa ULTRA (4inch touchscreen, 5000mah rechargeable battery); 2x 30cm ALSR100 SMA cables; 1 x USB Type-C data cable; 1x SMA-SMA barrel connector; 1x TLanyard and touch plectrum; 1x Antenna with SMA connector; 1x 32GB MicroSD card(plugged in the host), 1x Stylus Pen</li>\n</ul>\n\n<figure>\u00a0</figure>\n\n<figure>\n<p><img alt=\"\" src=\"https://tinysa.org/wiki/uploads/Main/tinySA_ultra.jpg\"></p>\n\n<p><cms-plugin alt=\"Picture / Image - Image (14325) \" title=\"Picture / Image - Image (14325)\" id=\"14325\"></cms-plugin></p>\n\n<p>Using TinySA to test satellite RF module for transmission.\u00a0</p>\n\n<p><cms-plugin alt=\"Picture / Image - Image (13692) \" title=\"Picture / Image - Image (13692)\" id=\"13692\"></cms-plugin></p>\n\n<p><cms-plugin alt=\"Picture / Image - Image (13693) \" title=\"Picture / Image - Image (13693)\" id=\"13693\"></cms-plugin></p>\n</figure>\n\n<p><cms-plugin alt=\"Picture / Image - Image (14326) \" title=\"Picture / Image - Image (14326)\" id=\"14326\"></cms-plugin></p>"}}]}','en',1,1135,47);
