INSERT INTO djangocms_history_placeholderaction VALUES(1161,'change_plugin','{"plugins": [{"pk": 1340, "creation_date": "2024-12-20T12:31:27.640Z", "position": 2, "plugin_type": "TextPlugin", "parent_id": 1337, "data": {"body": "<ul>\n\t<li>Tinysa ULTRA+ zs406 owns high performance frequency in 100khz to 900MHz, and when in ultra mode, the analyzer can reach 5.4GHz. With new 4'''' touchscreen display and installed with the latest hardware system V0.4.6. Built-in 32Gb micro TF\u00a0card for data transfer and storage</li>\n\t<li>[Frequency Range] Tinysa ultra measures from 100KHz-5.4GHz: Spectrum Analyzer for 0.1MHz-900MHz, with Ultra mode enabled, level calibrated up to 6GHz, can observe signals up to 12GHz. RBW from 200Hz-850kHz, you can fast and accurate execute measurement tests. Color display showing max 450 points providing gapless covering up to the full frequency range</li>\n</ul>"}}]}','{"plugins": [{"pk": 1340, "creation_date": "2024-12-20T12:31:27.640Z", "position": 2, "plugin_type": "TextPlugin", "parent_id": 1337, "data": {"body": "<ul>\n\t<li>Tinysa ULTRA+ ZS406 owns high performance frequency in 100khz to 900MHz, and when in ultra mode, the analyzer can reach 5.4GHz. With new 4'''' touchscreen display and installed with the latest hardware system V0.4.6. Built-in 32Gb micro TF\u00a0card for data transfer and storage</li>\n\t<li>[Frequency Range] Tinysa ultra measures from 100KHz-5.4GHz: Spectrum Analyzer for 0.1MHz-900MHz, with Ultra mode enabled, level calibrated up to 6GHz, can observe signals up to 12GHz. RBW from 200Hz-850kHz, you can fast and accurate execute measurement tests. Color display showing max 450 points providing gapless covering up to the full frequency range</li>\n</ul>"}}]}','en',1,1136,47);
INSERT INTO djangocms_history_placeholderaction VALUES(1162,'change_plugin','{"plugins": [{"pk": 13908, "creation_date": "2024-12-20T12:31:27.640Z", "position": 2, "plugin_type": "TextPlugin", "parent_id": 13905, "data": {"body": "<ul>\n\t<li>Tinysa ULTRA+ zs406 owns high performance frequency in 100khz to 900MHz, and when in ultra mode, the analyzer can reach 5.4GHz. With new 4'''' touchscreen display and installed with the latest hardware system V0.4.6. Built-in 32Gb micro TF\u00a0card for data transfer and storage</li>\n\t<li>[Frequency Range] Tinysa ultra measures from 100KHz-5.4GHz: Spectrum Analyzer for 0.1MHz-900MHz, with Ultra mode enabled, level calibrated up to 6GHz, can observe signals up to 12GHz. RBW from 200Hz-850kHz, you can fast and accurate execute measurement tests. Color display showing max 450 points providing gapless covering up to the full frequency range</li>\n</ul>"}}]}','{"plugins": [{"pk": 13908, "creation_date": "2024-12-20T12:31:27.640Z", "position": 2, "plugin_type": "TextPlugin", "parent_id": 13905, "data": {"body": "<ul>\n\t<li>\n\t<h1 id=\"title\">4.0 Inch 100kHz-7.3GHz Handheld Frequency Analyzer, 2-in-1 Signal Generator 100kHz to 900MHz</h1>\n\t</li>\n\t<li>AURSINC 2025 Upgraded Tinysa Ultra+ ZS407 spectrum analyzer: With ultra-wide frequency range of 100kHz-7.3GHz, enabling you to capture and analyze a broader spectrum of signals precisely. With 4\u201d IPS-TFT LCD (480\u00d7320) display can show a maximum of 450 points per scan, clearly presenting signal details and measurement results. Supports PC control, enabling easy data transfer and analysis</li>\n\t<li>Ultra-Wide Frequency Range: The TinySA Ultra+ ZS407 Spectrum Analyzer covers a frequency range of 0.1 - 900MHz, with Ultra mode enabled up to 7.3 GHz, level calibrated up to 7.3GHz. Can observe signals up to 12GHz, which represents a significant improvement over previous models. It can accurately capture and analyze a broader range of signals, making it suitable for a variety of complex RF testing scenarios</li>\n\t<li>Powerful Signal Generation Capability: The Tiny sa Ultra+ ZS407 can act as a Signal Generator with sine wave output between 0.1 MHz and 900 MHz, square wave output up to 6.3 GHz, or RF test signal output up to 7.3 GHz. It has a rich variety of signal generation types and a wide frequency range</li>\n\t<li>[USB Interface Powered] The ZK05-BM is a USB-powered RF low noise amplifier. Based on the ZKxx-UM, ZK05-BM adds a battery and reduces power consumption, making it suitable for portable use. Broadband, Low power, Low Noise. Good flatness in the 1-6 GHz range. Gain: 20dB, OP1dB: 18dBm Typ</li>\n\t<li>[Built-in Battery] Built-in 300mAh battery, it has a flatter and more consistent gain, lower noise figure, smaller size, and longer battery life (Charging 210mA, Total 230mA, Battery life 12 hours). Recommended for use as tinySA ULTRA 5.8GHz preamplifier. Since the LNA in tinySA ULTRA is effective only below 3.5GHz, adding an LNA can enhance high-frequency sensitivity. ZK05-BM is helpful for users requiring measurements at 5.8GHz</li>\n</ul>"}}]}','en',1,1137,97);
INSERT INTO djangocms_history_placeholderaction VALUES(1163,'change_plugin','{"plugins": [{"pk": 13908, "creation_date": "2024-12-20T12:31:27.640Z", "position": 2, "plugin_type": "TextPlugin", "parent_id": 13905, "data": {"body": "<ul>\n\t<li>\n\t<h1 id=\"title\">4.0 Inch 100kHz-7.3GHz Handheld Frequency Analyzer, 2-in-1 Signal Generator 100kHz to 900MHz</h1>\n\t</li>\n\t<li>AURSINC 2025 Upgraded Tinysa Ultra+ ZS407 spectrum analyzer: With ultra-wide frequency range of 100kHz-7.3GHz, enabling you to capture and analyze a broader spectrum of signals precisely. With 4\u201d IPS-TFT LCD (480\u00d7320) display can show a maximum of 450 points per scan, clearly presenting signal details and measurement results. Supports PC control, enabling easy data transfer and analysis</li>\n\t<li>Ultra-Wide Frequency Range: The TinySA Ultra+ ZS407 Spectrum Analyzer covers a frequency range of 0.1 - 900MHz, with Ultra mode enabled up to 7.3 GHz, level calibrated up to 7.3GHz. Can observe signals up to 12GHz, which represents a significant improvement over previous models. It can accurately capture and analyze a broader range of signals, making it suitable for a variety of complex RF testing scenarios</li>\n\t<li>Powerful Signal Generation Capability: The Tiny sa Ultra+ ZS407 can act as a Signal Generator with sine wave output between 0.1 MHz and 900 MHz, square wave output up to 6.3 GHz, or RF test signal output up to 7.3 GHz. It has a rich variety of signal generation types and a wide frequency range</li>\n\t<li>[USB Interface Powered] The ZK05-BM is a USB-powered RF low noise amplifier. Based on the ZKxx-UM, ZK05-BM adds a battery and reduces power consumption, making it suitable for portable use. Broadband, Low power, Low Noise. Good flatness in the 1-6 GHz range. Gain: 20dB, OP1dB: 18dBm Typ</li>\n\t<li>[Built-in Battery] Built-in 300mAh battery, it has a flatter and more consistent gain, lower noise figure, smaller size, and longer battery life (Charging 210mA, Total 230mA, Battery life 12 hours). Recommended for use as tinySA ULTRA 5.8GHz preamplifier. Since the LNA in tinySA ULTRA is effective only below 3.5GHz, adding an LNA can enhance high-frequency sensitivity. ZK05-BM is helpful for users requiring measurements at 5.8GHz</li>\n</ul>"}}]}','{"plugins": [{"pk": 13908, "creation_date": "2024-12-20T12:31:27.640Z", "position": 2, "plugin_type": "TextPlugin", "parent_id": 13905, "data": {"body": "<ul>\n\t<li>\n\t<p id=\"title\">Tinysa Ultra+ ZS407 spectrum analyzer: With ultra-wide frequency range of 100kHz-7.3GHz, enabling you to capture and analyze a broader spectrum of signals precisely. With 4\u201d IPS-TFT LCD (480\u00d7320) display can show a maximum of 450 points per scan, clearly presenting signal details and measurement results. Supports PC control, enabling easy data transfer and analysis</p>\n\t</li>\n\t<li>Ultra-Wide Frequency Range: The TinySA Ultra+ ZS407 Spectrum Analyzer covers a frequency range of 0.1 - 900MHz, with Ultra mode enabled up to 7.3 GHz, level calibrated up to 7.3GHz. Can observe signals up to 12GHz, which represents a significant improvement over previous models. It can accurately capture and analyze a broader range of signals, making it suitable for a variety of complex RF testing scenarios</li>\n\t<li>Signal Generation Capability: ZS407 have the SG function, but the SG function is not calibrated and the max output power is -18.5dbm, sine wave output between 0.1 MHz and 900 MHz, square wave output up to 6.3 GHz, or RF test signal output up to 7.3 GHz. It has a rich variety of signal generation types and a wide frequency range</li>\n</ul>"}}]}','en',1,1138,97);
INSERT INTO djangocms_history_placeholderaction VALUES(1164,'change_plugin','{"plugins": [{"pk": 13914, "creation_date": "2024-12-20T12:37:21.671Z", "position": 0, "plugin_type": "TextPlugin", "parent_id": 13913, "data": {"body": "<ul>\n\t<li id=\"bundle-v2-btf-component-bullet-point-1-2\">[Upgraded TinySA Ultra ZS406] TinySA Ultra owns high performance frequency in 100khz to 900MHz, and when in ultra mode, the analyzer can reach 5.4GHz. With new 4'''' touchscreen display and installed with the latest hardware system V0.4.6. Built-in 32Gb micro TF card for data transfer and storage</li>\n\t<li id=\"bundle-v2-btf-component-bullet-point-1-3\">[Frequency Range] Tiny sa ultra measures from 100KHz-5.4GHz: Spectrum Analyzer for 0.1MHz-900MHz, with Ultra mode enabled, level calibrated up to 6GHz, can observe signals up to 12GHz. RBW can be set from 200Hz-850kHz, you can fast and accurate execute measurement tests. Color display showing max 450 points providing gapless covering up to the full frequency range</li>\n\t<li id=\"bundle-v2-btf-component-bullet-point-1-4\">[2 in 1 Device] When not used as Spectrum Analyzer it can be used as Signal Generator, MF/HF/VHF sinus output between 100kHZ-900MHz, UHF square wave output between 800mHz-4.4GHz, Mixing signal output is between 4.4GHz-5.4GHz. Built-in calibration signal generator that is used for automatic self test and level calibration</li>\n\t<li id=\"bundle-v2-btf-component-bullet-point-1-5\">[PC Operation] Connected to a PC via USB. The USB interface implements CDC protocol and there is a large set of commands that can be invoked over the serial interface. These command can be used to perform MEAS or update internal settings. Tinysa-APP transfers data directly to the computer. The driver for Windows will install automatically after connecting to a Windows10 or Win11 PC. The driver for Linux is built into the kernel</li>\n\t<li id=\"bundle-v2-btf-component-bullet-point-1-6\">[200Hz-850kHz RBW] RBW frequency from 200hz to 850khz which can be set to match the measurement requirements, meet SBB two-tone test requirements and fast scanning. The RBW is as low as 200Hz, which can effectively distinguish adjacent signals and meet the requirements of SSB dual-satellite inter-modulation test. Input Step attenuator from 0dB to 31dB (can not be used not in combination with LNA)</li>\n\t<li id=\"bundle-v2-btf-component-bullet-point-1-7\">[What You Get] 1x Tinysa ULTRA (4inch touchscreen, 5000mah rechargeable battery); 2x 30cm ALSR100 SMA cables; 1 x USB Type-C data cable; 1x SMA-SMA barrel connector; 1x TLanyard and touch plectrum; 1x Antenna with SMA connector; 1x 32GB MicroSD card(plugged in the host), 1x Stylus Pen</li>\n</ul>\n\n<figure>\u00a0</figure>\n\n<figure>\n<p><img alt=\"\" src=\"https://tinysa.org/wiki/uploads/Main/tinySA_ultra.jpg\"></p>\n\n<p>Using TinySA to test satellite RF module for transmission.\u00a0</p>\n\n<p><cms-plugin alt=\"Picture / Image - Image (13915) \" title=\"Picture / Image - Image (13915)\" id=\"13915\"></cms-plugin></p>\n\n<p><cms-plugin alt=\"Picture / Image - Image (13916) \" title=\"Picture / Image - Image (13916)\" id=\"13916\"></cms-plugin></p>\n</figure>\n\n<p>\u00a0</p>"}}]}','{"plugins": [{"pk": 13914, "creation_date": "2024-12-20T12:37:21.671Z", "position": 0, "plugin_type": "TextPlugin", "parent_id": 13913, "data": {"body": "<ul>\n\t<li id=\"bundle-v2-btf-component-bullet-point-1-1\">ZS407 spectrum analyzer: With ultra-wide frequency range of 100kHz-7.3GHz, enabling you to capture and analyze a broader spectrum of signals precisely. With 4\u201d IPS-TFT LCD (480\u00d7320) display can show a maximum of 450 points per scan, clearly presenting signal details and measurement results. Supports PC control, enabling easy data transfer and analysis</li>\n\t<li id=\"bundle-v2-btf-component-bullet-point-1-4\">Long-Lasting Battery: Equipped with a Li-polymer 3.7V 5000mAh battery, the battery life is significantly increased compared to previous models. It can meet the needs of continuous testing for a long time or outdoor operations, reducing the inconvenience of frequent charging and improving work efficiency. Built-in 32GB micro SD card, solving the on-site data storage issue, convenient for data sharing and storage</li>\n\t<li id=\"bundle-v2-btf-component-bullet-point-1-5\">High-Gain Low-Noise Amplifier (LNA): The internal LNA gain can reach 20dB up to 7.3GHz, effectively enhancing the reception ability of weak signals. At the same time, at 100MHz, the DANL is as low as -169dBm/Hz when the LNA is on, reducing noise interference and improving the accuracy of signal measurement</li>\n\t<li id=\"bundle-v2-btf-component-bullet-point-1-6\">Excellent Phase Noise Performance: The phase noise is -100dBc/Hz at a 10kHz offset and -103dBc/Hz at a 100kHz offset. The low phase noise indicates high signal purity, enabling more accurate analysis of signal frequency stability and spectral purity. It is crucial for high-precision RF measurement and communication system performance evaluation</li>\n\t<li id=\"bundle-v2-btf-component-bullet-point-1-7\">Paking List: 1x Tinysa ULTRA+ ZS407 Spectrum Analyzer (built-in 5000mah rechargeable battery); 1x 32GB Micro SD card (plugged in the host); 2x 30cm ALSR100 SMA cables; 1 x USB Type-C data cable; 1x SMA-SMA barrel connector; 1x TLanyard and touch plectrum; 1x Antenna with SMA connector; 1x stylus pen</li>\n</ul>\n\n<figure>\u00a0</figure>\n\n<figure>\n<p><img alt=\"\" src=\"https://tinysa.org/wiki/uploads/Main/tinySA_ultra.jpg\"></p>\n\n<p>Using TinySA to test satellite RF module for transmission.\u00a0</p>\n\n<p><cms-plugin alt=\"Picture / Image - Image (13915) \" title=\"Picture / Image - Image (13915)\" id=\"13915\"></cms-plugin></p>\n\n<p><cms-plugin alt=\"Picture / Image - Image (13916) \" title=\"Picture / Image - Image (13916)\" id=\"13916\"></cms-plugin></p>\n</figure>\n\n<p>\u00a0</p>"}}]}','en',1,1139,97);
INSERT INTO djangocms_history_placeholderaction VALUES(1165,'change_plugin','{"plugins": [{"pk": 1573, "creation_date": "2024-12-20T12:30:45.026Z", "position": 0, "plugin_type": "HeadingPlugin", "parent_id": 1572, "data": {"ui_item": "Heading", "tag_type": "div", "config": {"heading_level": "h2", "heading": "NanoVNA", "heading_id": "", "heading_context": "dark", "heading_alignment": "", "attributes": {}, "margin_x": "", "margin_y": "", "margin_devices": null, "padding_x": "", "padding_y": "", "padding_devices": null}}}]}','{"plugins": [{"pk": 1573, "creation_date": "2024-12-20T12:30:45.026Z", "position": 0, "plugin_type": "HeadingPlugin", "parent_id": 1572, "data": {"ui_item": "Heading", "tag_type": "div", "config": {"heading_level": "h2", "heading": "NanoVNA-F V2", "heading_id": "", "heading_context": "dark", "heading_alignment": "", "attributes": {}, "margin_x": "", "margin_y": "", "margin_devices": null, "padding_x": "", "padding_y": "", "padding_devices": null}}}]}','en',1,1140,49);
INSERT INTO djangocms_history_placeholderaction VALUES(1166,'change_plugin','{"plugins": [{"pk": 1575, "creation_date": "2024-12-20T12:31:27.640Z", "position": 2, "plugin_type": "TextPlugin", "parent_id": 1572, "data": {"body": "<p><strong>\u00a0TinySA Ultra\u00a0TinySA Ultra\u00a0TinySA Ultra\u00a0TinySA Ultra\u00a0TinySA Ultra\u00a0TinySA Ultra\u00a0TinySA Ultra\u00a0TinySA Ultra</strong></p>"}}]}','{"plugins": [{"pk": 1575, "creation_date": "2024-12-20T12:31:27.640Z", "position": 2, "plugin_type": "TextPlugin", "parent_id": 1572, "data": {"body": "<ul>\n\t<li>\u00a0 The measurement range of\u00a0 NanoVNA-F V2 is extended to 50k-4.4GHz,the dynamic range is improved, reach to 80db. Can be used to debug the duplexer, more accurate, and simple.Which can measure S-parameter, voltage standing wave ratio SWR, phase map, group delay, Smith chart and so on.</li>\n\t<li>\u00a0Built-in 5000mAh lithium battery, standby time up to 2-3\u00a0hours, Using high current 2A charging IC to Shorten charging time, and extended 5V/1A USB output interface. It can be used as a Mobile Power Pack to charge mobile phones when not in use.</li>\n\t<li>Support Chinese and English interface;Support interpolation of calibration results.</li>\n\t<li>NanoVNA V2 with 4.3-inch IPS LCD display,ultra-wide viewing angle,support screen brightness adjustment,long-term use does not hurt your eyes.Full touching screen design, with 3 side buttons at the same time, flexible and convenient operation.</li>\n\t<li>\u3010Package List\u30111 * 4.3inch 3G NanoVNA-F V2 Host;1 * SMA Open Calibration Kit;1 * SMA Short-circuit Calibration Kit;1 * SMA 50\u03a9 Load Calibration Kit;1 * SMA-KK Double-Head Female Hole Adapter;1 * SMA-JJ Double-Head Male Pin Adapter;1 * SMA-JKW Elbow Outer Screw Inner Hole To Inner Screw Inner Needles Adapter;2 * 200mm SMA-JJ RG405 RF Cable;1 * USB Type-C Cable;1 * White Touchscreen Pen</li>\n</ul>"}}]}','en',1,1141,49);
