INSERT INTO djangocms_history_placeholderaction VALUES(1195,'change_plugin','{"plugins": [{"pk": 10515, "creation_date": "2024-12-20T12:37:21.671Z", "position": 0, "plugin_type": "TextPlugin", "parent_id": 10514, "data": {"body": "<p><strong>TinySA\u662f\u4e00\u79cd\u5c0f\u578b\u9891\u8c31\u5206\u6790\u4eea\u548c\u4fe1\u53f7\u53d1\u751f\u5668\uff0c\u5177\u6709\u4e00\u4e9b\u4e0d\u9519\u7684\u529f\u80fd\uff1a</strong></p>\n\n<ul>\n\t<li><strong>TinySA\u57fa\u672c\u7279\u70b9:</strong>\n\n\t<ul>\n\t\t<li>\u5c4f\u5e55\u5c3a\u5bf8 2.8\u82f1\u5bf8</li>\n\t\t<li>\u5e26\u4e24\u4e2a\u8f93\u5165\u7aef\u53e3\u7684\u9891\u8c31\u5206\u6790\u4eea\uff0cLow\u7aef\u53e3\u7528\u4e8e 10KHz-350MHz \u7684\u9ad8\u8d28\u91cf MF/HF/VHF \u8f93\u5165\uff0cHigh\u7aef\u53e3\u7528\u4e8e 240MHz-960MHz \u7684 UHF \u8f93\u5165\u3002</li>\n\t\t<li>\u4fe1\u53f7\u53d1\u751f\u5668\u5177\u6709\u4e24\u4e2a\u8f93\u51fa\uff0c\u6b63\u5f26\u6ce2\u8f93\u51fa\u4e3a100KHz - 350MHz\uff0c\u65b9\u6ce2\u8f93\u51fa\u4e3a 240MHz-960MHz\uff0c\u4fe1\u53f7\u53d1\u751f\u5668\u548c\u9891\u8c31\u5206\u6790\u4eea\u540c\u4e00\u65f6\u523b\u53ea\u80fd\u9009\u62e9\u5176\u4e2d\u7684\u4e00\u4e2a\u529f\u80fd\u3002</li>\n\t\t<li>\u5f69\u8272\u663e\u793a\u5c4f\u663e\u793a\u6700\u591a 290\u4e2a\u626b\u63cf\u70b9\uff0c\u63d0\u4f9b\u957f\u8fbe\u6574\u4e2a\u4f4e\u9891\u6216\u9ad8\u9891\u8303\u56f4\u7684\u65e0\u95f4\u9699\u8986\u76d6\u3002</li>\n\t</ul>\n\t</li>\n\t<li><strong>TinySA</strong>\u00a0<strong>Ultra\u57fa\u672c\u7279\u70b9:</strong>\n\t<ul>\n\t\t<li>\u5c4f\u5e55\u5c3a\u5bf8 4\u82f1\u5bf8</li>\n\t\t<li>\u9891\u8c31\u5206\u6790\u4eea\u6a21\u5f0f\uff0c\u521d\u59cb\u72b6\u6001\u4e3a10KHz-800MHz\uff0c\u5728\u542f\u7528\u72ec\u7279\u7684Ultra\u6a21\u5f0f\u7684\u60c5\u51b5\u4e0b\uff0c\u53ef\u4ee5\u76d1\u6d4b\u9ad8\u8fbe12GHz\u7684\u4fe1\u53f7\u3002</li>\n\t\t<li>\u4fe1\u53f7\u53d1\u751f\u5668\u6a21\u5f0f\uff0c\u6b63\u5f26\u6ce2\u8f93\u51fa\u5728100KHz-800MHz\u4e4b\u95f4\uff0c\u5c04\u9891\u6d4b\u8bd5\u4fe1\u53f7\u7684\u65b9\u6ce2\u8f93\u51fa\u9ad8\u8fbe5.3GHz\u3002</li>\n\t\t<li>200Hz\u81f3850KHz\u7684RBW\u8bbe\u7f6e\u63d0\u4f9b\u66f4\u9ad8\u7684\u7075\u654f\u5ea6\u8303\u56f4\u3002</li>\n\t\t<li>\u5185\u7f6e 20dB \u53ef\u9009 LNA</li>\n\t\t<li>\u5f69\u8272\u663e\u793a\u5c4f\u663e\u793a\u6700\u5927 450 \u4e2a\u70b9\uff0c\u63d0\u4f9b\u957f\u8fbe\u6574\u4e2a\u9891\u7387\u8303\u56f4\u7684\u65e0\u95f4\u9699\u8986\u76d6\u3002</li>\n\t\t<li>MicroSD\u5361\u63d2\u69fd\uff0c\u7528\u4e8e\u5b58\u50a8\u6d4b\u91cf\u503c\uff0c\u8bbe\u7f6e\u548c\u5c4f\u5e55\u622a\u56fe\u3002</li>\n\t</ul>\n\t</li>\n\t<li>\u8f93\u5165\u6b65\u8fdb\u8870\u51cf\u5668\u4ece0dB\u523031dB\uff08\u4e0d\u80fd\u4e0eLNA\u7ed3\u5408\u4f7f\u7528\uff09\u3002</li>\n\t<li>\u5185\u7f6e\u6821\u51c6\u4fe1\u53f7\u53d1\u751f\u5668\uff0c\u7528\u4e8e\u81ea\u52a8\u81ea\u68c0\u548c\uff08\u4f4e\uff09\u8f93\u5165\u6821\u51c6\u3002</li>\n\t<li>\u901a\u8fc7USB\u8fde\u63a5\u5230PC\uff0c\u5b83\u6210\u4e3aPC\u63a7\u5236\u7684\u9891\u8c31\u5206\u6790\u4eea\u6216\u4fe1\u53f7\u53d1\u751f\u5668</li>\n\t<li>\u9ad8\u8fbe3000mah\u7684\u53ef\u5145\u7535\u7535\u6c60\uff0c\u53ef\u643a\u5e26\u81f3\u5c112\u5c0f\u65f6\u3002</li>\n\t<li>\u6700\u5927\u8f93\u5165\u7535\u5e73 +6dBm\u3002</li>\n\t<li>\u4fe1\u53f7\u53d1\u751f\u5668\u529f\u80fd\u4e0d\u80fd\u7528\u4f5c\u8ddf\u8e2a\u53d1\u751f\u5668\uff0c\u56e0\u4e3a\u60a8\u4e0d\u80fd\u540c\u65f6\u4f7f\u7528\u9891\u8c31\u5206\u6790\u4eea\u548c\u4fe1\u53f7\u53d1\u751f\u5668\u529f\u80fd\u3002</li>\n\t<li>\u7531\u4e8e\u4f4e\u6210\u672c\u548c\u975e\u5e38\u5c0f\u7684\u5916\u5f62\u5c3a\u5bf8\uff0c\u5b58\u5728\u67d0\u4e9b\u76f8\u5173\u7684\u5fae\u5c0fSA\u9650\u5236\u548c\u5fae\u5c0fSA\u8d85\u9650\u5236\u3002</li>\n</ul>\n\n<figure><img alt=\"\" src=\"https://tinysa.org/wiki/uploads/Main/tinySA_housing.jpg\"></figure>\n\n<figure><img alt=\"\" src=\"https://tinysa.org/wiki/uploads/Main/tinySA_ultra.jpg\"></figure>\n\n<p><strong>\u89c6\u9891\u6559\u5b66\uff1a</strong></p>\n\n<p>\u53ef\u4ee5\u5728B\u7ad9\u4e5f\u5c31\u662f\u54d4\u54e9\u54d4\u54e9_bilibili\u7f51\u7ad9\u641c\u7d22TinyRFEquip\u8d26\u53f7\u627e\u5230\u4ecb\u7ecdTinySA\u548cTinySA Ultra\u4ee5\u53ca\u5176\u4ed6TinyRFEquip\u4eea\u5668\u7684\u4e3b\u8981\u529f\u80fd\u4ecb\u7ecd\u89c6\u9891\u3002\u4f8b\u5982\uff1a</p>\n\n<p><a href=\"https://www.bilibili.com/video/BV1yt421u7Y2/?vd_source=8d60a323bdde2d574cb0a85c07cb3212\">TinySA Ultra\u5bf9\u4e8e\u65e0\u7ebf\u8bdd\u7b52\u7684\u9891\u7387\u7279\u6027\u68c0\u5b9a\u6d4b\u91cf_\u54d4\u54e9\u54d4\u54e9_bilibili</a></p>\n\n<p>https://www.bilibili.com/video/BV1yt421u7Y2/?vd_source=8d60a323bdde2d574cb0a85c07cb3212</p>\n\n<p><strong>\u6cd5\u5f8b\u5185\u5bb9</strong></p>\n\n<p>TinySA\u548cTinySA Ultra\u7684\u540d\u79f0\u4ee5\u53caTinySA\u5fbd\u6807\u662f\u6211\u4eec\u62e5\u6709\u7684\u6ce8\u518c\u5546\u6807\u3002\u672a\u7ecf\u4e66\u9762\u8bb8\u53ef\uff0c\u4e0d\u5141\u8bb8\u5176\u4ed6\u4eba\u4f7f\u7528TinySA\u8fd9\u4e2a\u540d\u5b57 \u6216 TinySA Ultra \u7528\u4e8e\u4efb\u4f55\u9891\u8c31\u5206\u6790\u4eea\u4ea7\u54c1\u3002</p>"}}]}','{"plugins": [{"pk": 10515, "creation_date": "2024-12-20T12:37:21.671Z", "position": 0, "plugin_type": "TextPlugin", "parent_id": 10514, "data": {"body": "<p>This NanoVNA-F V3 vna analyzer is a new production machine , with 4.3 inch 800 x 480 large touchscreen display, 1MHz to 6GHz widely measuring range, the scan speed of NanoVNA-F V3 is up to 200 points/s and the maximum scanning points is up to 801.In addition, the nanovna analyzer supports TDR function which is useful for cable lengths measurement.</p>\n\n<p>Compared to the Nanovna-F V2 (50kHz-3GHz), the upgraded Nanovna-F V3 has 1MHz-6GHz ultra-wide measuring frequency range, The S21 dynamic range of NanoVNA-F V3 is 65 dB, while the S11 dynamic range is 50 dB. The scan points is up to 101-801 and the calibration result storage is 12, covering up to the full low or high frequency range. Faster and more accurate measurement performance, you can easily cope with measurement testes in various fields.</p>\n\n<p>This nano vna analyzer measuring tool is made of metal material, which is durable and can effectively shield electromagnetic interference. With SMA connector design which can be used to connect DUTs directly.In addition,it is support PC Software control and compatible with NanoVNA-Saver for convenient measurement data transfer.Built-in 4500m-ah rechargeable battery,with type-C charging cable and LED charging indicator,it can be fully charged within 3 hours,no need to charge frequently.</p>\n\n<p>NanoVNA-F V3 antenna analyzer is suitable for antenna testing of MF/HF/VHF/UHF/SHF bands. Supports a variety of display formats: Log Mag, Linear Mag, Phase, Smith R+jX, Smith R+L/C, VSWR, Polar, Group delay, Resistance, Reactance, etc. It can also be used to measure filters, amplifiers, attenuators, cables, power dividers, couplers, duplexers and other RF components. For the amateur radio operator or radio enthusiast, this latest vna antenna analyzer will be a very handy analyzer to have.</p>"}}]}','en',1,1167,78);
INSERT INTO djangocms_history_placeholderaction VALUES(1196,'change_plugin','{"plugins": [{"pk": 10515, "creation_date": "2024-12-20T12:37:21.671Z", "position": 0, "plugin_type": "TextPlugin", "parent_id": 10514, "data": {"body": "<p>This NanoVNA-F V3 vna analyzer is a new production machine , with 4.3 inch 800 x 480 large touchscreen display, 1MHz to 6GHz widely measuring range, the scan speed of NanoVNA-F V3 is up to 200 points/s and the maximum scanning points is up to 801.In addition, the nanovna analyzer supports TDR function which is useful for cable lengths measurement.</p>\n\n<p>Compared to the Nanovna-F V2 (50kHz-3GHz), the upgraded Nanovna-F V3 has 1MHz-6GHz ultra-wide measuring frequency range, The S21 dynamic range of NanoVNA-F V3 is 65 dB, while the S11 dynamic range is 50 dB. The scan points is up to 101-801 and the calibration result storage is 12, covering up to the full low or high frequency range. Faster and more accurate measurement performance, you can easily cope with measurement testes in various fields.</p>\n\n<p>This nano vna analyzer measuring tool is made of metal material, which is durable and can effectively shield electromagnetic interference. With SMA connector design which can be used to connect DUTs directly.In addition,it is support PC Software control and compatible with NanoVNA-Saver for convenient measurement data transfer.Built-in 4500m-ah rechargeable battery,with type-C charging cable and LED charging indicator,it can be fully charged within 3 hours,no need to charge frequently.</p>\n\n<p>NanoVNA-F V3 antenna analyzer is suitable for antenna testing of MF/HF/VHF/UHF/SHF bands. Supports a variety of display formats: Log Mag, Linear Mag, Phase, Smith R+jX, Smith R+L/C, VSWR, Polar, Group delay, Resistance, Reactance, etc. It can also be used to measure filters, amplifiers, attenuators, cables, power dividers, couplers, duplexers and other RF components. For the amateur radio operator or radio enthusiast, this latest vna antenna analyzer will be a very handy analyzer to have.</p>"}}]}','{"plugins": [{"pk": 10515, "creation_date": "2024-12-20T12:37:21.671Z", "position": 0, "plugin_type": "TextPlugin", "parent_id": 10514, "data": {"body": "<p>This NanoVNA-F V3 vna analyzer is a new production machine , with 4.3 inch 800 x 480 large touchscreen display, 1MHz to 6GHz widely measuring range, the scan speed of NanoVNA-F V3 is up to 200 points/s and the maximum scanning points is up to 801.In addition, the nanovna analyzer supports TDR function which is useful for cable lengths measurement.</p>\n\n<p>Compared to the Nanovna-F V2 (50kHz-3GHz), the upgraded Nanovna-F V3 has 1MHz-6GHz ultra-wide measuring frequency range, The S21 dynamic range of NanoVNA-F V3 is 65 dB, while the S11 dynamic range is 50 dB. The scan points is up to 101-801 and the calibration result storage is 12, covering up to the full low or high frequency range. Faster and more accurate measurement performance, you can easily cope with measurement testes in various fields.</p>\n\n<p>This nano vna analyzer measuring tool is made of metal material, which is durable and can effectively shield electromagnetic interference. With SMA connector design which can be used to connect DUTs directly.In addition,it is support PC Software control and compatible with NanoVNA-Saver for convenient measurement data transfer.Built-in 4500m-ah rechargeable battery,with type-C charging cable and LED charging indicator,it can be fully charged within 3 hours,no need to charge frequently.</p>\n\n<p>NanoVNA-F V3 antenna analyzer is suitable for antenna testing of MF/HF/VHF/UHF/SHF bands. Supports a variety of display formats: Log Mag, Linear Mag, Phase, Smith R+jX, Smith R+L/C, VSWR, Polar, Group delay, Resistance, Reactance, etc. It can also be used to measure filters, amplifiers, attenuators, cables, power dividers, couplers, duplexers and other RF components. For the amateur radio operator or radio enthusiast, this latest vna antenna analyzer will be a very handy analyzer to have.</p>\n\n<p>After optimizing the RF design in our store, the NanoVNA-F V3 uses an independent local oscillator generation chip instead of the harmonic components commonly used in most imitations as a cheap option for local oscillator signals. Additionally, the customized all metal casing and high-quality SMA connector can support customers for longer use and better external shielding performance.</p>\n\n<p>Especially the factory has perfectly calibrated the S21 performance of 3G-6G, far exceeding LiteVNA. It can conveniently monitor power dividers, combiners, filters, attenuators, antennas, cables, amplifiers, mixers, duplexers, couplers, isolators, circulators, adapters, waveguides, differential devices, etc.<br>\nCommon testing functions include: TDR cable connection, standing wave ratio, return loss, insertion loss, flatness, out of band suppression, attenuation, gain, isolation, characteristic impedance, input-output impedance, phase, delay, and 1dB compression point.</p>"}}]}','en',1,1168,78);
INSERT INTO djangocms_history_placeholderaction VALUES(1197,'change_plugin','{"plugins": [{"pk": 10515, "creation_date": "2024-12-20T12:37:21.671Z", "position": 0, "plugin_type": "TextPlugin", "parent_id": 10514, "data": {"body": "<p>This NanoVNA-F V3 vna analyzer is a new production machine , with 4.3 inch 800 x 480 large touchscreen display, 1MHz to 6GHz widely measuring range, the scan speed of NanoVNA-F V3 is up to 200 points/s and the maximum scanning points is up to 801.In addition, the nanovna analyzer supports TDR function which is useful for cable lengths measurement.</p>\n\n<p>Compared to the Nanovna-F V2 (50kHz-3GHz), the upgraded Nanovna-F V3 has 1MHz-6GHz ultra-wide measuring frequency range, The S21 dynamic range of NanoVNA-F V3 is 65 dB, while the S11 dynamic range is 50 dB. The scan points is up to 101-801 and the calibration result storage is 12, covering up to the full low or high frequency range. Faster and more accurate measurement performance, you can easily cope with measurement testes in various fields.</p>\n\n<p>This nano vna analyzer measuring tool is made of metal material, which is durable and can effectively shield electromagnetic interference. With SMA connector design which can be used to connect DUTs directly.In addition,it is support PC Software control and compatible with NanoVNA-Saver for convenient measurement data transfer.Built-in 4500m-ah rechargeable battery,with type-C charging cable and LED charging indicator,it can be fully charged within 3 hours,no need to charge frequently.</p>\n\n<p>NanoVNA-F V3 antenna analyzer is suitable for antenna testing of MF/HF/VHF/UHF/SHF bands. Supports a variety of display formats: Log Mag, Linear Mag, Phase, Smith R+jX, Smith R+L/C, VSWR, Polar, Group delay, Resistance, Reactance, etc. It can also be used to measure filters, amplifiers, attenuators, cables, power dividers, couplers, duplexers and other RF components. For the amateur radio operator or radio enthusiast, this latest vna antenna analyzer will be a very handy analyzer to have.</p>\n\n<p>After optimizing the RF design in our store, the NanoVNA-F V3 uses an independent local oscillator generation chip instead of the harmonic components commonly used in most imitations as a cheap option for local oscillator signals. Additionally, the customized all metal casing and high-quality SMA connector can support customers for longer use and better external shielding performance.</p>\n\n<p>Especially the factory has perfectly calibrated the S21 performance of 3G-6G, far exceeding LiteVNA. It can conveniently monitor power dividers, combiners, filters, attenuators, antennas, cables, amplifiers, mixers, duplexers, couplers, isolators, circulators, adapters, waveguides, differential devices, etc.<br>\nCommon testing functions include: TDR cable connection, standing wave ratio, return loss, insertion loss, flatness, out of band suppression, attenuation, gain, isolation, characteristic impedance, input-output impedance, phase, delay, and 1dB compression point.</p>"}}]}','{"plugins": [{"pk": 10515, "creation_date": "2024-12-20T12:37:21.671Z", "position": 0, "plugin_type": "TextPlugin", "parent_id": 10514, "data": {"body": "<p>\u00a0</p>\n\n<p>NanoVNA-F V3 antenna analyzer is suitable for antenna testing of MF/HF/VHF/UHF/SHF bands. Supports a variety of display formats: Log Mag, Linear Mag, Phase, Smith R+jX, Smith R+L/C, VSWR, Polar, Group delay, Resistance, Reactance, etc. It can also be used to measure filters, amplifiers, attenuators, cables, power dividers, couplers, duplexers and other RF components. For the amateur radio operator or radio enthusiast, this latest vna antenna analyzer will be a very handy analyzer to have.</p>\n\n<p>After optimizing the RF design in our store, the NanoVNA-F V3 uses an independent local oscillator generation chip instead of the harmonic components commonly used in most imitations as a cheap option for local oscillator signals. Additionally, the customized all metal casing and high-quality SMA connector can support customers for longer use and better external shielding performance.</p>\n\n<p>Especially the factory has perfectly calibrated the S21 performance of 3G-6G, far exceeding LiteVNA. It can conveniently monitor power dividers, combiners, filters, attenuators, antennas, cables, amplifiers, mixers, duplexers, couplers, isolators, circulators, adapters, waveguides, differential devices, etc.<br>\nCommon testing functions include: TDR cable connection, standing wave ratio, return loss, insertion loss, flatness, out of band suppression, attenuation, gain, isolation, characteristic impedance, input-output impedance, phase, delay, and 1dB compression point.</p>"}}]}','en',1,1169,78);
INSERT INTO djangocms_history_placeholderaction VALUES(1198,'change_plugin','{"plugins": [{"pk": 10509, "creation_date": "2024-12-20T12:31:27.640Z", "position": 2, "plugin_type": "TextPlugin", "parent_id": 10506, "data": {"body": "<p><strong>\u00a0TinySA Ultra\u00a0TinySA Ultra\u00a0TinySA Ultra\u00a0TinySA Ultra\u00a0TinySA Ultra\u00a0TinySA Ultra\u00a0TinySA Ultra\u00a0TinySA Ultra</strong></p>"}}]}','{"plugins": [{"pk": 10509, "creation_date": "2024-12-20T12:31:27.640Z", "position": 2, "plugin_type": "TextPlugin", "parent_id": 10506, "data": {"body": "<p>This NanoVNA-F V3 vna analyzer is a new production machine , with 4.3 inch 800 x 480 large touchscreen display, 1MHz to 6GHz widely measuring range, the scan speed of NanoVNA-F V3 is up to 200 points/s and the maximum scanning points is up to 801.In addition, the nanovna analyzer supports TDR function which is useful for cable lengths measurement.</p>\n\n<p>Compared to the Nanovna-F V2 (50kHz-3GHz), the upgraded Nanovna-F V3 has 1MHz-6GHz ultra-wide measuring frequency range, The S21 dynamic range of NanoVNA-F V3 is 65 dB, while the S11 dynamic range is 50 dB. The scan points is up to 101-801 and the calibration result storage is 12, covering up to the full low or high frequency range. Faster and more accurate measurement performance, you can easily cope with measurement testes in various fields.</p>\n\n<p>This nano vna analyzer measuring tool is made of metal material, which is durable and can effectively shield electromagnetic interference. With SMA connector design which can be used to connect DUTs directly.In addition,it is support PC Software control and compatible with NanoVNA-Saver for convenient measurement data transfer.Built-in 4500m-ah rechargeable battery,with type-C charging cable and LED charging indicator,it can be fully charged within 3 hours,no need to charge frequently.</p>"}}]}','en',1,1170,78);
INSERT INTO djangocms_history_placeholderaction VALUES(1199,'change_plugin','{"plugins": [{"pk": 10515, "creation_date": "2024-12-20T12:37:21.671Z", "position": 0, "plugin_type": "TextPlugin", "parent_id": 10514, "data": {"body": "<p>\u00a0</p>\n\n<p>NanoVNA-F V3 antenna analyzer is suitable for antenna testing of MF/HF/VHF/UHF/SHF bands. Supports a variety of display formats: Log Mag, Linear Mag, Phase, Smith R+jX, Smith R+L/C, VSWR, Polar, Group delay, Resistance, Reactance, etc. It can also be used to measure filters, amplifiers, attenuators, cables, power dividers, couplers, duplexers and other RF components. For the amateur radio operator or radio enthusiast, this latest vna antenna analyzer will be a very handy analyzer to have.</p>\n\n<p>After optimizing the RF design in our store, the NanoVNA-F V3 uses an independent local oscillator generation chip instead of the harmonic components commonly used in most imitations as a cheap option for local oscillator signals. Additionally, the customized all metal casing and high-quality SMA connector can support customers for longer use and better external shielding performance.</p>\n\n<p>Especially the factory has perfectly calibrated the S21 performance of 3G-6G, far exceeding LiteVNA. It can conveniently monitor power dividers, combiners, filters, attenuators, antennas, cables, amplifiers, mixers, duplexers, couplers, isolators, circulators, adapters, waveguides, differential devices, etc.<br>\nCommon testing functions include: TDR cable connection, standing wave ratio, return loss, insertion loss, flatness, out of band suppression, attenuation, gain, isolation, characteristic impedance, input-output impedance, phase, delay, and 1dB compression point.</p>"}}]}','{"plugins": [{"pk": 10515, "creation_date": "2024-12-20T12:37:21.671Z", "position": 0, "plugin_type": "TextPlugin", "parent_id": 10514, "data": {"body": "<p>NanoVNA-F V3 is a Portable Vector Network Analyzer (VNA) with frequency range of 1MHz~6GHz. It can be used for S11 and S21 measurements. The S21 dynamic range of NanoVNA-F V3 is 65 dB, while the S11 dynamic range is 50 dB.</p>\n\n<p>NanoVNA-F V3 antenna analyzer is suitable for antenna testing of MF/HF/VHF/UHF/SHF bands. Supports a variety of display formats: Log Mag, Linear Mag, Phase, Smith R+jX, Smith R+L/C, VSWR, Polar, Group delay, Resistance, Reactance, etc. It can also be used to measure filters, amplifiers, attenuators, cables, power dividers, couplers, duplexers and other RF components. For the amateur radio operator or radio enthusiast, this latest vna antenna analyzer will be a very handy analyzer to have.</p>\n\n<p>After optimizing the RF design in our store, the NanoVNA-F V3 uses an independent local oscillator generation chip instead of the harmonic components commonly used in most imitations as a cheap option for local oscillator signals. Additionally, the customized all metal casing and high-quality SMA connector can support customers for longer use and better external shielding performance.</p>\n\n<p>Especially the factory has perfectly calibrated the S21 performance of 3G-6G, far exceeding LiteVNA. It can conveniently monitor power dividers, combiners, filters, attenuators, antennas, cables, amplifiers, mixers, duplexers, couplers, isolators, circulators, adapters, waveguides, differential devices, etc.<br>\nCommon testing functions include: TDR cable connection, standing wave ratio, return loss, insertion loss, flatness, out of band suppression, attenuation, gain, isolation, characteristic impedance, input-output impedance, phase, delay, and 1dB compression point.</p>\n\n<p><b>\u00a0Features:</b><br>\nFrequency range: 1MHz-6GHz<br>\nS21 dynamic range: 65dB and S11 dynamic range: 50dB<br>\n4.3\" high-brightness IPS display with resistive touch panel<br>\nMetal case can effectively shield electromagnetic interference<br>\nSMA connector is stable and durable to use<br>\nFull touch screen and 3 physical buttons enable convenient and smooth operation<br>\nDimensions: 125 x 75 x 20mm/4.9 x 3 x 0.8\"<br>\nBuilt-in 4500mAh lithium-ion batteries with endurance time up to 5 hours<br>\nTDR function can be used to measure cable length<br>\nUp to 4 reference traces<br>\nUp to 4 markers, and the marker table can be dragged to anywhere on the screen<br>\n12 save/recall slots<br>\nCharging via USB Type-C, and the charging voltage is 5V DC<br>\nDesigned with a 5V/1A USB power output port<br>\nFirmware upgrade via virtual U disk with USB Type-C cable<br>\nComes with SMA calibration kit and 2 x 20cm/7.9\" SMA-JJ RG405 coaxial cable<br>\nSupports console commands and PC software</p>\n\n<p>\u00a0</p>"}}]}','en',1,1171,78);
INSERT INTO djangocms_history_placeholderaction VALUES(1200,'change_plugin','{"plugins": [{"pk": 10513, "creation_date": "2024-12-20T12:36:07.302Z", "position": 0, "plugin_type": "TabPlugin", "parent_id": 10512, "data": {"ui_item": "Tab", "tag_type": "div", "config": {"template": "default", "tab_type": "nav-tabs", "tab_alignment": "", "tab_index": 1, "tab_effect": "", "attributes": {}}}}]}','{"plugins": [{"pk": 10513, "creation_date": "2024-12-20T12:36:07.302Z", "position": 0, "plugin_type": "TabPlugin", "parent_id": 10512, "data": {"ui_item": "Tab", "tag_type": "div", "config": {"template": "default", "tab_type": "nav-tabs", "tab_alignment": "", "tab_index": 1, "tab_effect": "", "attributes": {}}}}]}','en',1,1172,78);
