INSERT INTO djangocms_history_placeholderaction VALUES(1221,'change_plugin','{"plugins": [{"pk": 7333, "creation_date": "2025-01-25T04:25:13.945Z", "position": 0, "plugin_type": "ImagePlugin", "parent_id": 1636, "data": {"ui_item": "Image", "tag_type": "div", "config": {"template": "default", "picture": {"model": "filer.image", "pk": 81}, "external_picture": "", "lazy_loading": false, "width": null, "height": null, "alignment": "", "link_attributes": {}, "use_automatic_scaling": false, "use_crop": false, "use_no_cropping": false, "use_upscale": false, "use_responsive_image": "inherit", "thumbnail_options": null, "picture_fluid": true, "picture_rounded": false, "picture_thumbnail": false, "attributes": {}, "external_link": "", "internal_link": "", "file_link": null, "anchor": "", "mailto": "", "phone": "", "target": "", "responsive_visibility": null, "margin_x": "", "margin_y": "", "margin_devices": null}}}]}','{"plugins": [{"pk": 7333, "creation_date": "2025-01-25T04:25:13.945Z", "position": 0, "plugin_type": "ImagePlugin", "parent_id": 1636, "data": {"ui_item": "Image", "tag_type": "div", "config": {"template": "default", "picture": {"model": "filer.image", "pk": 109}, "external_picture": "", "lazy_loading": false, "width": null, "height": null, "alignment": "", "link_attributes": {}, "use_automatic_scaling": false, "use_crop": false, "use_no_cropping": false, "use_upscale": false, "use_responsive_image": "inherit", "thumbnail_options": null, "picture_fluid": true, "picture_rounded": false, "picture_thumbnail": false, "attributes": {}, "external_link": "", "internal_link": "", "file_link": null, "anchor": "", "mailto": "", "phone": "", "target": "", "responsive_visibility": null, "margin_x": "", "margin_y": "", "margin_devices": null}}}]}','en',1,1191,50);
INSERT INTO djangocms_history_placeholderaction VALUES(1222,'change_plugin','{"plugins": [{"pk": 1641, "creation_date": "2024-12-20T12:31:27.640Z", "position": 2, "plugin_type": "TextPlugin", "parent_id": 1638, "data": {"body": "<p><strong>litevnalitevnalitevnalitevnalitevnalitevnalitevnalit</strong></p>"}}]}','{"plugins": [{"pk": 1641, "creation_date": "2024-12-20T12:31:27.640Z", "position": 2, "plugin_type": "TextPlugin", "parent_id": 1638, "data": {"body": "<p>LiteVNA-64 improves on the popular NanoVNA and SAA2. Now you can get a portable vector network analyzer (VNA) as small as the NanoVNA and capable of meeting the ultra-wide measurement range of 50 kHz to 6.3 GHz.<br>\n<br>\nTo minimize power consumption and size, the LiteVNA-64 uses only one frequency mixer, with multiple internal RF switches for S11 and S21 measurements, and IFFT calculations for TDR and DTF measurements.<br>\n<br>\nDesigned with the community''s input in mind, the LiteVNA-64 now brings faster scanning speeds and more scan points in addition to a wider measurement range. Combined with an easy-to-use interface consistent with the NanoVNA, it can now be easily used as a field test tool.<br>\n<br>\nLiteVNA-64 includes a MicroSD slot, so you can save field test data or screens to a MicroSD card at any time. With a measurement range of up to 6.3GHz, the LiteVNA-64 is capable of meeting common amateur radio and IoT applications, as well as emerging 5GHz testing, enabling the application of the latest 5.8GHz wifi and 5.8GHz image transmission.<br>\n\u00a0</p>"}}]}','en',1,1192,50);
INSERT INTO djangocms_history_placeholderaction VALUES(1223,'change_plugin','{"plugins": [{"pk": 1639, "creation_date": "2024-12-20T12:30:45.026Z", "position": 0, "plugin_type": "HeadingPlugin", "parent_id": 1638, "data": {"ui_item": "Heading", "tag_type": "div", "config": {"heading_level": "h2", "heading": "LiteVNA", "heading_id": "", "heading_context": "dark", "heading_alignment": "", "attributes": {}, "margin_x": "", "margin_y": "", "margin_devices": null, "padding_x": "", "padding_y": "", "padding_devices": null}}}]}','{"plugins": [{"pk": 1639, "creation_date": "2024-12-20T12:30:45.026Z", "position": 0, "plugin_type": "HeadingPlugin", "parent_id": 1638, "data": {"ui_item": "Heading", "tag_type": "div", "config": {"heading_level": "h2", "heading": "LiteVNA-64", "heading_id": "", "heading_context": "dark", "heading_alignment": "", "attributes": {}, "margin_x": "", "margin_y": "", "margin_devices": null, "padding_x": "", "padding_y": "", "padding_devices": null}}}]}','en',1,1193,50);
INSERT INTO djangocms_history_placeholderaction VALUES(1224,'change_plugin','{"plugins": [{"pk": 1647, "creation_date": "2024-12-20T12:37:21.671Z", "position": 0, "plugin_type": "TextPlugin", "parent_id": 1646, "data": {"body": "<p><strong>TinySA\u662f\u4e00\u79cd\u5c0f\u578b\u9891\u8c31\u5206\u6790\u4eea\u548c\u4fe1\u53f7\u53d1\u751f\u5668\uff0c\u5177\u6709\u4e00\u4e9b\u4e0d\u9519\u7684\u529f\u80fd\uff1a</strong></p>\n\n<ul>\n\t<li><strong>TinySA\u57fa\u672c\u7279\u70b9:</strong>\n\n\t<ul>\n\t\t<li>\u5c4f\u5e55\u5c3a\u5bf8 2.8\u82f1\u5bf8</li>\n\t\t<li>\u5e26\u4e24\u4e2a\u8f93\u5165\u7aef\u53e3\u7684\u9891\u8c31\u5206\u6790\u4eea\uff0cLow\u7aef\u53e3\u7528\u4e8e 10KHz-350MHz \u7684\u9ad8\u8d28\u91cf MF/HF/VHF \u8f93\u5165\uff0cHigh\u7aef\u53e3\u7528\u4e8e 240MHz-960MHz \u7684 UHF \u8f93\u5165\u3002</li>\n\t\t<li>\u4fe1\u53f7\u53d1\u751f\u5668\u5177\u6709\u4e24\u4e2a\u8f93\u51fa\uff0c\u6b63\u5f26\u6ce2\u8f93\u51fa\u4e3a100KHz - 350MHz\uff0c\u65b9\u6ce2\u8f93\u51fa\u4e3a 240MHz-960MHz\uff0c\u4fe1\u53f7\u53d1\u751f\u5668\u548c\u9891\u8c31\u5206\u6790\u4eea\u540c\u4e00\u65f6\u523b\u53ea\u80fd\u9009\u62e9\u5176\u4e2d\u7684\u4e00\u4e2a\u529f\u80fd\u3002</li>\n\t\t<li>\u5f69\u8272\u663e\u793a\u5c4f\u663e\u793a\u6700\u591a 290\u4e2a\u626b\u63cf\u70b9\uff0c\u63d0\u4f9b\u957f\u8fbe\u6574\u4e2a\u4f4e\u9891\u6216\u9ad8\u9891\u8303\u56f4\u7684\u65e0\u95f4\u9699\u8986\u76d6\u3002</li>\n\t</ul>\n\t</li>\n\t<li><strong>TinySA</strong>\u00a0<strong>Ultra\u57fa\u672c\u7279\u70b9:</strong>\n\t<ul>\n\t\t<li>\u5c4f\u5e55\u5c3a\u5bf8 4\u82f1\u5bf8</li>\n\t\t<li>\u9891\u8c31\u5206\u6790\u4eea\u6a21\u5f0f\uff0c\u521d\u59cb\u72b6\u6001\u4e3a10KHz-800MHz\uff0c\u5728\u542f\u7528\u72ec\u7279\u7684Ultra\u6a21\u5f0f\u7684\u60c5\u51b5\u4e0b\uff0c\u53ef\u4ee5\u76d1\u6d4b\u9ad8\u8fbe12GHz\u7684\u4fe1\u53f7\u3002</li>\n\t\t<li>\u4fe1\u53f7\u53d1\u751f\u5668\u6a21\u5f0f\uff0c\u6b63\u5f26\u6ce2\u8f93\u51fa\u5728100KHz-800MHz\u4e4b\u95f4\uff0c\u5c04\u9891\u6d4b\u8bd5\u4fe1\u53f7\u7684\u65b9\u6ce2\u8f93\u51fa\u9ad8\u8fbe5.3GHz\u3002</li>\n\t\t<li>200Hz\u81f3850KHz\u7684RBW\u8bbe\u7f6e\u63d0\u4f9b\u66f4\u9ad8\u7684\u7075\u654f\u5ea6\u8303\u56f4\u3002</li>\n\t\t<li>\u5185\u7f6e 20dB \u53ef\u9009 LNA</li>\n\t\t<li>\u5f69\u8272\u663e\u793a\u5c4f\u663e\u793a\u6700\u5927 450 \u4e2a\u70b9\uff0c\u63d0\u4f9b\u957f\u8fbe\u6574\u4e2a\u9891\u7387\u8303\u56f4\u7684\u65e0\u95f4\u9699\u8986\u76d6\u3002</li>\n\t\t<li>MicroSD\u5361\u63d2\u69fd\uff0c\u7528\u4e8e\u5b58\u50a8\u6d4b\u91cf\u503c\uff0c\u8bbe\u7f6e\u548c\u5c4f\u5e55\u622a\u56fe\u3002</li>\n\t</ul>\n\t</li>\n\t<li>\u8f93\u5165\u6b65\u8fdb\u8870\u51cf\u5668\u4ece0dB\u523031dB\uff08\u4e0d\u80fd\u4e0eLNA\u7ed3\u5408\u4f7f\u7528\uff09\u3002</li>\n\t<li>\u5185\u7f6e\u6821\u51c6\u4fe1\u53f7\u53d1\u751f\u5668\uff0c\u7528\u4e8e\u81ea\u52a8\u81ea\u68c0\u548c\uff08\u4f4e\uff09\u8f93\u5165\u6821\u51c6\u3002</li>\n\t<li>\u901a\u8fc7USB\u8fde\u63a5\u5230PC\uff0c\u5b83\u6210\u4e3aPC\u63a7\u5236\u7684\u9891\u8c31\u5206\u6790\u4eea\u6216\u4fe1\u53f7\u53d1\u751f\u5668</li>\n\t<li>\u9ad8\u8fbe3000mah\u7684\u53ef\u5145\u7535\u7535\u6c60\uff0c\u53ef\u643a\u5e26\u81f3\u5c112\u5c0f\u65f6\u3002</li>\n\t<li>\u6700\u5927\u8f93\u5165\u7535\u5e73 +6dBm\u3002</li>\n\t<li>\u4fe1\u53f7\u53d1\u751f\u5668\u529f\u80fd\u4e0d\u80fd\u7528\u4f5c\u8ddf\u8e2a\u53d1\u751f\u5668\uff0c\u56e0\u4e3a\u60a8\u4e0d\u80fd\u540c\u65f6\u4f7f\u7528\u9891\u8c31\u5206\u6790\u4eea\u548c\u4fe1\u53f7\u53d1\u751f\u5668\u529f\u80fd\u3002</li>\n\t<li>\u7531\u4e8e\u4f4e\u6210\u672c\u548c\u975e\u5e38\u5c0f\u7684\u5916\u5f62\u5c3a\u5bf8\uff0c\u5b58\u5728\u67d0\u4e9b\u76f8\u5173\u7684\u5fae\u5c0fSA\u9650\u5236\u548c\u5fae\u5c0fSA\u8d85\u9650\u5236\u3002</li>\n</ul>\n\n<figure><img alt=\"\" src=\"https://tinysa.org/wiki/uploads/Main/tinySA_housing.jpg\"></figure>\n\n<figure><img alt=\"\" src=\"https://tinysa.org/wiki/uploads/Main/tinySA_ultra.jpg\"></figure>\n\n<p><strong>\u89c6\u9891\u6559\u5b66\uff1a</strong></p>\n\n<p>\u53ef\u4ee5\u5728B\u7ad9\u4e5f\u5c31\u662f\u54d4\u54e9\u54d4\u54e9_bilibili\u7f51\u7ad9\u641c\u7d22TinyRFEquip\u8d26\u53f7\u627e\u5230\u4ecb\u7ecdTinySA\u548cTinySA Ultra\u4ee5\u53ca\u5176\u4ed6TinyRFEquip\u4eea\u5668\u7684\u4e3b\u8981\u529f\u80fd\u4ecb\u7ecd\u89c6\u9891\u3002\u4f8b\u5982\uff1a</p>\n\n<p><a href=\"https://www.bilibili.com/video/BV1yt421u7Y2/?vd_source=8d60a323bdde2d574cb0a85c07cb3212\">TinySA Ultra\u5bf9\u4e8e\u65e0\u7ebf\u8bdd\u7b52\u7684\u9891\u7387\u7279\u6027\u68c0\u5b9a\u6d4b\u91cf_\u54d4\u54e9\u54d4\u54e9_bilibili</a></p>\n\n<p>https://www.bilibili.com/video/BV1yt421u7Y2/?vd_source=8d60a323bdde2d574cb0a85c07cb3212</p>\n\n<p><strong>\u6cd5\u5f8b\u5185\u5bb9</strong></p>\n\n<p>TinySA\u548cTinySA Ultra\u7684\u540d\u79f0\u4ee5\u53caTinySA\u5fbd\u6807\u662f\u6211\u4eec\u62e5\u6709\u7684\u6ce8\u518c\u5546\u6807\u3002\u672a\u7ecf\u4e66\u9762\u8bb8\u53ef\uff0c\u4e0d\u5141\u8bb8\u5176\u4ed6\u4eba\u4f7f\u7528TinySA\u8fd9\u4e2a\u540d\u5b57 \u6216 TinySA Ultra \u7528\u4e8e\u4efb\u4f55\u9891\u8c31\u5206\u6790\u4eea\u4ea7\u54c1\u3002</p>"}}]}','{"plugins": [{"pk": 1647, "creation_date": "2024-12-20T12:37:21.671Z", "position": 0, "plugin_type": "TextPlugin", "parent_id": 1646, "data": {"body": "<p>We have updated LiteVNA-64 to version 0.3.1, redesigned the power supply and IF circuit, greatly reduced noise floor and completely solved interference when it is connected to an external power supply. Below 1MHz-3GHz frequencies, effective dynamics of better than 90dB can be obtained with 20AVG. Above 3 GHz, the limited isolation is reduced. The effective dynamic reduction is reduced to 50dB at 6.3GHz. Compared to similar products, LiteVNA-64 has a wider frequency measurement range and an effective dynamic range. Furthermore, it is more light and reliable!</p>\n\n<p>Affected by the current tight chip supply, we still hope that LiteVNA series is an affordable device for hobbyists and startups. The 0.3.1 version of the LiteVNA-64 is currently in short supply, and the 2.8-inch LiteVNA-62 is still the 0.3 version, and we are working with the supplier to provide the best possible device to users!</p>"}}]}','en',1,1194,50);
INSERT INTO djangocms_history_placeholderaction VALUES(1225,'change_plugin','{"plugins": [{"pk": 1647, "creation_date": "2024-12-20T12:37:21.671Z", "position": 0, "plugin_type": "TextPlugin", "parent_id": 1646, "data": {"body": "<p>We have updated LiteVNA-64 to version 0.3.1, redesigned the power supply and IF circuit, greatly reduced noise floor and completely solved interference when it is connected to an external power supply. Below 1MHz-3GHz frequencies, effective dynamics of better than 90dB can be obtained with 20AVG. Above 3 GHz, the limited isolation is reduced. The effective dynamic reduction is reduced to 50dB at 6.3GHz. Compared to similar products, LiteVNA-64 has a wider frequency measurement range and an effective dynamic range. Furthermore, it is more light and reliable!</p>\n\n<p>Affected by the current tight chip supply, we still hope that LiteVNA series is an affordable device for hobbyists and startups. The 0.3.1 version of the LiteVNA-64 is currently in short supply, and the 2.8-inch LiteVNA-62 is still the 0.3 version, and we are working with the supplier to provide the best possible device to users!</p>"}}]}','{"plugins": [{"pk": 1647, "creation_date": "2024-12-20T12:37:21.671Z", "position": 0, "plugin_type": "TextPlugin", "parent_id": 1646, "data": {"body": "<p>We have updated LiteVNA-64 to version 0.3.1, redesigned the power supply and IF circuit, greatly reduced noise floor and completely solved interference when it is connected to an external power supply. Below 1MHz-3GHz frequencies, effective dynamics of better than 90dB can be obtained with 20AVG. Above 3 GHz, the limited isolation is reduced. The effective dynamic reduction is reduced to 50dB at 6.3GHz. Compared to similar products, LiteVNA-64 has a wider frequency measurement range and an effective dynamic range. Furthermore, it is more light and reliable!</p>\n\n<p>Because the design of LiteVNA evolved from NanoVNA, it not only has a wider measurement range, but also has faster scanning speed and more scanning points. It has an easy-to-use interface consistent with NanoVNA, and all control software compatible with NanoVNA, such as TinyRFeqipApp, Nano_Spp, and NanoVNA saver, can be perfectly matched with LiteVNA. Now, LiteVNA can be easily used as a testing tool for on-site and remote control.</p>\n\n<p>Affected by the current tight chip supply, we still hope that LiteVNA series is an affordable device for hobbyists and startups. The 0.3.1 version of the LiteVNA-64 is currently in short supply, and the 2.8-inch LiteVNA-62 is still the 0.3 version, and we are working with the supplier to provide the best possible device to users!</p>"}}]}','en',1,1195,50);
INSERT INTO djangocms_history_placeholderaction VALUES(1226,'change_plugin','{"plugins": [{"pk": 1647, "creation_date": "2024-12-20T12:37:21.671Z", "position": 0, "plugin_type": "TextPlugin", "parent_id": 1646, "data": {"body": "<p>We have updated LiteVNA-64 to version 0.3.1, redesigned the power supply and IF circuit, greatly reduced noise floor and completely solved interference when it is connected to an external power supply. Below 1MHz-3GHz frequencies, effective dynamics of better than 90dB can be obtained with 20AVG. Above 3 GHz, the limited isolation is reduced. The effective dynamic reduction is reduced to 50dB at 6.3GHz. Compared to similar products, LiteVNA-64 has a wider frequency measurement range and an effective dynamic range. Furthermore, it is more light and reliable!</p>\n\n<p>Because the design of LiteVNA evolved from NanoVNA, it not only has a wider measurement range, but also has faster scanning speed and more scanning points. It has an easy-to-use interface consistent with NanoVNA, and all control software compatible with NanoVNA, such as TinyRFeqipApp, Nano_Spp, and NanoVNA saver, can be perfectly matched with LiteVNA. Now, LiteVNA can be easily used as a testing tool for on-site and remote control.</p>\n\n<p>Affected by the current tight chip supply, we still hope that LiteVNA series is an affordable device for hobbyists and startups. The 0.3.1 version of the LiteVNA-64 is currently in short supply, and the 2.8-inch LiteVNA-62 is still the 0.3 version, and we are working with the supplier to provide the best possible device to users!</p>"}}]}','{"plugins": [{"pk": 1647, "creation_date": "2024-12-20T12:37:21.671Z", "position": 0, "plugin_type": "TextPlugin", "parent_id": 1646, "data": {"body": "<p>We have updated LiteVNA-64 to version 0.3.1, redesigned the power supply and IF circuit, greatly reduced noise floor and completely solved interference when it is connected to an external power supply. Below 1MHz-3GHz frequencies, effective dynamics of better than 90dB can be obtained with 20AVG. Above 3 GHz, the limited isolation is reduced. The effective dynamic reduction is reduced to 50dB at 6.3GHz. Compared to similar products, LiteVNA-64 has a wider frequency measurement range and an effective dynamic range. Furthermore, it is more light and reliable!</p>\n\n<p>Because the design of LiteVNA evolved from NanoVNA, it not only has a wider measurement range, but also has faster scanning speed and more scanning points. It has an easy-to-use interface consistent with NanoVNA, and all control software compatible with NanoVNA, such as TinyRFeqipApp, Nano_Spp, and NanoVNA saver, can be perfectly matched with LiteVNA. Now, LiteVNA can be easily used as a testing tool for on-site and remote control.</p>\n\n<p>Affected by the current tight chip supply, we still hope that LiteVNA series is an affordable device for hobbyists and startups. The 0.3.1 version of the LiteVNA-64 is currently in short supply, and the 2.8-inch LiteVNA-62 is still the 0.3 version, and we are working with the supplier to provide the best possible device to users!</p>\n\n<p><cms-plugin alt=\"Picture / Image - Image (15288) \" title=\"Picture / Image - Image (15288)\" id=\"15288\"></cms-plugin></p>\n\n<p><cms-plugin alt=\"Picture / Image - Image (15289) \" title=\"Picture / Image - Image (15289)\" id=\"15289\"></cms-plugin></p>"}}]}','en',1,1196,50);
INSERT INTO djangocms_history_placeholderaction VALUES(1227,'add_plugin','{"order": [], "parent_id": 1647}','{"order": [15288, 15289], "parent_id": 1647, "plugins": [{"pk": 15288, "creation_date": "2025-04-30T02:04:48.742Z", "position": 1, "plugin_type": "ImagePlugin", "parent_id": 1647, "data": {"ui_item": "Image", "tag_type": "div", "config": {"template": "default", "picture": {"model": "filer.image", "pk": 141}, "external_picture": "", "lazy_loading": false, "width": null, "height": null, "alignment": "", "link_attributes": {}, "use_automatic_scaling": false, "use_crop": false, "use_no_cropping": false, "use_upscale": false, "use_responsive_image": "inherit", "thumbnail_options": null, "picture_fluid": true, "picture_rounded": false, "picture_thumbnail": false, "attributes": {}, "external_link": "", "internal_link": "", "file_link": null, "anchor": "", "mailto": "", "phone": "", "target": "", "responsive_visibility": null, "margin_x": "", "margin_y": "", "margin_devices": null}}}, {"pk": 15289, "creation_date": "2025-04-30T02:06:50.636Z", "position": 2, "plugin_type": "ImagePlugin", "parent_id": 1647, "data": {"ui_item": "Image", "tag_type": "div", "config": {"template": "default", "picture": {"model": "filer.image", "pk": 142}, "external_picture": "", "lazy_loading": false, "width": null, "height": null, "alignment": "", "link_attributes": {}, "use_automatic_scaling": false, "use_crop": false, "use_no_cropping": false, "use_upscale": false, "use_responsive_image": "inherit", "thumbnail_options": null, "picture_fluid": true, "picture_rounded": false, "picture_thumbnail": false, "attributes": {}, "external_link": "", "internal_link": "", "file_link": null, "anchor": "", "mailto": "", "phone": "", "target": "", "responsive_visibility": null, "margin_x": "", "margin_y": "", "margin_devices": null}}}]}','en',2,1196,50);
INSERT INTO djangocms_history_placeholderaction VALUES(1228,'change_plugin','{"plugins": [{"pk": 1647, "creation_date": "2024-12-20T12:37:21.671Z", "position": 0, "plugin_type": "TextPlugin", "parent_id": 1646, "data": {"body": "<p>We have updated LiteVNA-64 to version 0.3.1, redesigned the power supply and IF circuit, greatly reduced noise floor and completely solved interference when it is connected to an external power supply. Below 1MHz-3GHz frequencies, effective dynamics of better than 90dB can be obtained with 20AVG. Above 3 GHz, the limited isolation is reduced. The effective dynamic reduction is reduced to 50dB at 6.3GHz. Compared to similar products, LiteVNA-64 has a wider frequency measurement range and an effective dynamic range. Furthermore, it is more light and reliable!</p>\n\n<p>Because the design of LiteVNA evolved from NanoVNA, it not only has a wider measurement range, but also has faster scanning speed and more scanning points. It has an easy-to-use interface consistent with NanoVNA, and all control software compatible with NanoVNA, such as TinyRFeqipApp, Nano_Spp, and NanoVNA saver, can be perfectly matched with LiteVNA. Now, LiteVNA can be easily used as a testing tool for on-site and remote control.</p>\n\n<p>Affected by the current tight chip supply, we still hope that LiteVNA series is an affordable device for hobbyists and startups. The 0.3.1 version of the LiteVNA-64 is currently in short supply, and the 2.8-inch LiteVNA-62 is still the 0.3 version, and we are working with the supplier to provide the best possible device to users!</p>\n\n<p><cms-plugin alt=\"Picture / Image - Image (15288) \" title=\"Picture / Image - Image (15288)\" id=\"15288\"></cms-plugin></p>\n\n<p><cms-plugin alt=\"Picture / Image - Image (15289) \" title=\"Picture / Image - Image (15289)\" id=\"15289\"></cms-plugin></p>"}}]}','{"plugins": [{"pk": 1647, "creation_date": "2024-12-20T12:37:21.671Z", "position": 0, "plugin_type": "TextPlugin", "parent_id": 1646, "data": {"body": "<p>We have updated LiteVNA-64 to version 0.3.1, redesigned the power supply and IF circuit, greatly reduced noise floor and completely solved interference when it is connected to an external power supply. Below 1MHz-3GHz frequencies, effective dynamics of better than 90dB can be obtained with 20AVG. Above 3 GHz, the limited isolation is reduced. The effective dynamic reduction is reduced to 50dB at 6.3GHz. Compared to similar products, LiteVNA-64 has a wider frequency measurement range and an effective dynamic range. Furthermore, it is more light and reliable!</p>\n\n<p>Because the design of LiteVNA evolved from NanoVNA, it not only has a wider measurement range, but also has faster scanning speed and more scanning points. It has an easy-to-use interface consistent with NanoVNA, and all control software compatible with NanoVNA, such as TinyRFeqipApp, Nano_Spp, and NanoVNA saver, can be perfectly matched with LiteVNA. Now, LiteVNA can be easily used as a testing tool for on-site and remote control.</p>\n\n<p>Affected by the current tight chip supply, we still hope that LiteVNA series is an affordable device for hobbyists and startups. The 0.3.1 version of the LiteVNA-64 is currently in short supply.</p>\n\n<p><cms-plugin alt=\"Picture / Image - Image (15288) \" title=\"Picture / Image - Image (15288)\" id=\"15288\"></cms-plugin></p>\n\n<p><cms-plugin alt=\"Picture / Image - Image (15289) \" title=\"Picture / Image - Image (15289)\" id=\"15289\"></cms-plugin></p>"}}]}','en',1,1197,50);
INSERT INTO djangocms_history_placeholderaction VALUES(1229,'change_plugin','{"plugins": [{"pk": 1647, "creation_date": "2024-12-20T12:37:21.671Z", "position": 0, "plugin_type": "TextPlugin", "parent_id": 1646, "data": {"body": "<p>We have updated LiteVNA-64 to version 0.3.1, redesigned the power supply and IF circuit, greatly reduced noise floor and completely solved interference when it is connected to an external power supply. Below 1MHz-3GHz frequencies, effective dynamics of better than 90dB can be obtained with 20AVG. Above 3 GHz, the limited isolation is reduced. The effective dynamic reduction is reduced to 50dB at 6.3GHz. Compared to similar products, LiteVNA-64 has a wider frequency measurement range and an effective dynamic range. Furthermore, it is more light and reliable!</p>\n\n<p>Because the design of LiteVNA evolved from NanoVNA, it not only has a wider measurement range, but also has faster scanning speed and more scanning points. It has an easy-to-use interface consistent with NanoVNA, and all control software compatible with NanoVNA, such as TinyRFeqipApp, Nano_Spp, and NanoVNA saver, can be perfectly matched with LiteVNA. Now, LiteVNA can be easily used as a testing tool for on-site and remote control.</p>\n\n<p>Affected by the current tight chip supply, we still hope that LiteVNA series is an affordable device for hobbyists and startups. The 0.3.1 version of the LiteVNA-64 is currently in short supply.</p>\n\n<p><cms-plugin alt=\"Picture / Image - Image (15288) \" title=\"Picture / Image - Image (15288)\" id=\"15288\"></cms-plugin></p>\n\n<p><cms-plugin alt=\"Picture / Image - Image (15289) \" title=\"Picture / Image - Image (15289)\" id=\"15289\"></cms-plugin></p>"}}]}','{"plugins": [{"pk": 1647, "creation_date": "2024-12-20T12:37:21.671Z", "position": 0, "plugin_type": "TextPlugin", "parent_id": 1646, "data": {"body": "<p>We have updated LiteVNA-64 to version 0.3.1, redesigned the power supply and IF circuit, greatly reduced noise floor and completely solved interference when it is connected to an external power supply. Below 1MHz-3GHz frequencies, effective dynamics of better than 90dB can be obtained with 20AVG. Above 3 GHz, the limited isolation is reduced. The effective dynamic reduction is reduced to 50dB at 6.3GHz. Compared to similar products, LiteVNA-64 has a wider frequency measurement range and an effective dynamic range. Furthermore, it is more light and reliable!</p>\n\n<p>Because the design of LiteVNA evolved from NanoVNA, it not only has a wider measurement range, but also has faster scanning speed and more scanning points. It has an easy-to-use interface consistent with NanoVNA, and all control software compatible with NanoVNA, such as TinyRFeqipApp, Nano_Spp, and NanoVNA saver, can be perfectly matched with LiteVNA. Now, LiteVNA can be easily used as a testing tool for on-site and remote control.</p>\n\n<p>Affected by the current tight chip supply, we still hope that LiteVNA series is an affordable device for hobbyists and startups. The 0.3.1 version of the LiteVNA-64 is currently in short supply.</p>\n\n<p><b>Package Included:</b><br>\n- 1 x LiteVNA-64 Main Unit (with 3.95-inch touch screen and 2000mAh battery)<br>\n- 2 x 30cm/11.8\" SMA Male to Male SS405 RF Cables<br>\n- 1 x SMA Female-to-Female Connector<br>\n- 1 x SMA Simple Calibration Kit SHORT<br>\n- 1 x SMA Simple Calibration Kit OPEN<br>\n- 1 x SMA Simple Calibration Kit LOAD<br>\n- 1 x USB Type-C Data Cable<br>\n- 1 x Pick</p>\n\n<p><cms-plugin alt=\"Picture / Image - Image (15288) \" title=\"Picture / Image - Image (15288)\" id=\"15288\"></cms-plugin></p>\n\n<p><cms-plugin alt=\"Picture / Image - Image (15289) \" title=\"Picture / Image - Image (15289)\" id=\"15289\"></cms-plugin></p>"}}]}','en',1,1198,50);
INSERT INTO djangocms_history_placeholderaction VALUES(1230,'change_plugin','{"plugins": [{"pk": 1040, "creation_date": "2024-12-20T11:50:21.552Z", "position": 0, "plugin_type": "TextPlugin", "parent_id": 1039, "data": {"body": "<p>Welcome to the website of Tiny RF Equipment, which covers and introduces many miniature and efficient RF microwave testing equipment, components, and related RF modules. These products are mainly used to meet the basic needs of wireless product testing, amateur radio testing enthusiasts, and students'' learning needs. This is a free and open website, hoping to communicate with everyone more professionally and quickly about RF professional issues. The products here strive to achieve the maximum economic input-output ratio for customers.</p>\n\n<p>At the same time, our studio engineers are proficient in RF instruments related to Shide, Rod, and Anli, providing online and on-site training and consultation. For more information, please contact us directly on Taobao or email</p>\n\n<p><span style=\"color: #999999;\"><strong>Currently, there are products included\uff1aTinySA, TinySA Ultra, NanoVNA\uff0cNanoVNA-H2, NanoVNA-H4, \u00a0NanoVNA SAA2, LiteVNA, LibreVNA\u00a0</strong></span></p>"}}]}','{"plugins": [{"pk": 1040, "creation_date": "2024-12-20T11:50:21.552Z", "position": 0, "plugin_type": "TextPlugin", "parent_id": 1039, "data": {"body": "<p>Welcome to the website of Tiny RF Equipment, which covers and introduces many miniature and efficient RF microwave testing equipment, components, and related RF modules. These products are mainly used to meet the basic needs of wireless product testing, amateur radio testing enthusiasts, and students'' learning needs. This is a free and open website, hoping to communicate with everyone more professionally and quickly about RF professional issues. The products here strive to achieve the maximum economic input-output ratio for customers.</p>\n\n<p>At the same time, our studio engineers are proficient in RF instruments related to Shide, Rod, and Anli, providing online and on-site training and consultation. For more information, please contact us directly on Taobao or email.The most important thing in purchasing equipment is the performance and technical support of the equipment itself. as an old engineer of RF, I hope to provide customers with professional consulting services.</p>\n\n<p><span style=\"color: #999999;\"><strong>Currently, there are products included\uff1aTinySA, TinySA Ultra, NanoVNA\uff0cNanoVNA-H2, NanoVNA-H4, \u00a0NanoVNA SAA2, LiteVNA, LibreVNA\u00a0</strong></span></p>"}}]}','en',1,1199,12);
INSERT INTO djangocms_history_placeholderaction VALUES(1231,'change_plugin','{"plugins": [{"pk": 10868, "creation_date": "2024-12-20T12:37:21.671Z", "position": 0, "plugin_type": "TextPlugin", "parent_id": 10867, "data": {"body": "<p><strong>TinySA\u662f\u4e00\u79cd\u5c0f\u578b\u9891\u8c31\u5206\u6790\u4eea\u548c\u4fe1\u53f7\u53d1\u751f\u5668\uff0c\u5177\u6709\u4e00\u4e9b\u4e0d\u9519\u7684\u529f\u80fd\uff1a</strong></p>\n\n<ul>\n\t<li><strong>TinySA\u57fa\u672c\u7279\u70b9:</strong>\n\n\t<ul>\n\t\t<li>\u5c4f\u5e55\u5c3a\u5bf8 2.8\u82f1\u5bf8</li>\n\t\t<li>\u5e26\u4e24\u4e2a\u8f93\u5165\u7aef\u53e3\u7684\u9891\u8c31\u5206\u6790\u4eea\uff0cLow\u7aef\u53e3\u7528\u4e8e 10KHz-350MHz \u7684\u9ad8\u8d28\u91cf MF/HF/VHF \u8f93\u5165\uff0cHigh\u7aef\u53e3\u7528\u4e8e 240MHz-960MHz \u7684 UHF \u8f93\u5165\u3002</li>\n\t\t<li>\u4fe1\u53f7\u53d1\u751f\u5668\u5177\u6709\u4e24\u4e2a\u8f93\u51fa\uff0c\u6b63\u5f26\u6ce2\u8f93\u51fa\u4e3a100KHz - 350MHz\uff0c\u65b9\u6ce2\u8f93\u51fa\u4e3a 240MHz-960MHz\uff0c\u4fe1\u53f7\u53d1\u751f\u5668\u548c\u9891\u8c31\u5206\u6790\u4eea\u540c\u4e00\u65f6\u523b\u53ea\u80fd\u9009\u62e9\u5176\u4e2d\u7684\u4e00\u4e2a\u529f\u80fd\u3002</li>\n\t\t<li>\u5f69\u8272\u663e\u793a\u5c4f\u663e\u793a\u6700\u591a 290\u4e2a\u626b\u63cf\u70b9\uff0c\u63d0\u4f9b\u957f\u8fbe\u6574\u4e2a\u4f4e\u9891\u6216\u9ad8\u9891\u8303\u56f4\u7684\u65e0\u95f4\u9699\u8986\u76d6\u3002</li>\n\t</ul>\n\t</li>\n\t<li><strong>TinySA</strong>\u00a0<strong>Ultra\u57fa\u672c\u7279\u70b9:</strong>\n\t<ul>\n\t\t<li>\u5c4f\u5e55\u5c3a\u5bf8 4\u82f1\u5bf8</li>\n\t\t<li>\u9891\u8c31\u5206\u6790\u4eea\u6a21\u5f0f\uff0c\u521d\u59cb\u72b6\u6001\u4e3a10KHz-800MHz\uff0c\u5728\u542f\u7528\u72ec\u7279\u7684Ultra\u6a21\u5f0f\u7684\u60c5\u51b5\u4e0b\uff0c\u53ef\u4ee5\u76d1\u6d4b\u9ad8\u8fbe12GHz\u7684\u4fe1\u53f7\u3002</li>\n\t\t<li>\u4fe1\u53f7\u53d1\u751f\u5668\u6a21\u5f0f\uff0c\u6b63\u5f26\u6ce2\u8f93\u51fa\u5728100KHz-800MHz\u4e4b\u95f4\uff0c\u5c04\u9891\u6d4b\u8bd5\u4fe1\u53f7\u7684\u65b9\u6ce2\u8f93\u51fa\u9ad8\u8fbe5.3GHz\u3002</li>\n\t\t<li>200Hz\u81f3850KHz\u7684RBW\u8bbe\u7f6e\u63d0\u4f9b\u66f4\u9ad8\u7684\u7075\u654f\u5ea6\u8303\u56f4\u3002</li>\n\t\t<li>\u5185\u7f6e 20dB \u53ef\u9009 LNA</li>\n\t\t<li>\u5f69\u8272\u663e\u793a\u5c4f\u663e\u793a\u6700\u5927 450 \u4e2a\u70b9\uff0c\u63d0\u4f9b\u957f\u8fbe\u6574\u4e2a\u9891\u7387\u8303\u56f4\u7684\u65e0\u95f4\u9699\u8986\u76d6\u3002</li>\n\t\t<li>MicroSD\u5361\u63d2\u69fd\uff0c\u7528\u4e8e\u5b58\u50a8\u6d4b\u91cf\u503c\uff0c\u8bbe\u7f6e\u548c\u5c4f\u5e55\u622a\u56fe\u3002</li>\n\t</ul>\n\t</li>\n\t<li>\u8f93\u5165\u6b65\u8fdb\u8870\u51cf\u5668\u4ece0dB\u523031dB\uff08\u4e0d\u80fd\u4e0eLNA\u7ed3\u5408\u4f7f\u7528\uff09\u3002</li>\n\t<li>\u5185\u7f6e\u6821\u51c6\u4fe1\u53f7\u53d1\u751f\u5668\uff0c\u7528\u4e8e\u81ea\u52a8\u81ea\u68c0\u548c\uff08\u4f4e\uff09\u8f93\u5165\u6821\u51c6\u3002</li>\n\t<li>\u901a\u8fc7USB\u8fde\u63a5\u5230PC\uff0c\u5b83\u6210\u4e3aPC\u63a7\u5236\u7684\u9891\u8c31\u5206\u6790\u4eea\u6216\u4fe1\u53f7\u53d1\u751f\u5668</li>\n\t<li>\u9ad8\u8fbe3000mah\u7684\u53ef\u5145\u7535\u7535\u6c60\uff0c\u53ef\u643a\u5e26\u81f3\u5c112\u5c0f\u65f6\u3002</li>\n\t<li>\u6700\u5927\u8f93\u5165\u7535\u5e73 +6dBm\u3002</li>\n\t<li>\u4fe1\u53f7\u53d1\u751f\u5668\u529f\u80fd\u4e0d\u80fd\u7528\u4f5c\u8ddf\u8e2a\u53d1\u751f\u5668\uff0c\u56e0\u4e3a\u60a8\u4e0d\u80fd\u540c\u65f6\u4f7f\u7528\u9891\u8c31\u5206\u6790\u4eea\u548c\u4fe1\u53f7\u53d1\u751f\u5668\u529f\u80fd\u3002</li>\n\t<li>\u7531\u4e8e\u4f4e\u6210\u672c\u548c\u975e\u5e38\u5c0f\u7684\u5916\u5f62\u5c3a\u5bf8\uff0c\u5b58\u5728\u67d0\u4e9b\u76f8\u5173\u7684\u5fae\u5c0fSA\u9650\u5236\u548c\u5fae\u5c0fSA\u8d85\u9650\u5236\u3002</li>\n</ul>\n\n<figure><img alt=\"\" src=\"https://tinysa.org/wiki/uploads/Main/tinySA_housing.jpg\"></figure>\n\n<figure><img alt=\"\" src=\"https://tinysa.org/wiki/uploads/Main/tinySA_ultra.jpg\"></figure>\n\n<p><strong>\u89c6\u9891\u6559\u5b66\uff1a</strong></p>\n\n<p>\u53ef\u4ee5\u5728B\u7ad9\u4e5f\u5c31\u662f\u54d4\u54e9\u54d4\u54e9_bilibili\u7f51\u7ad9\u641c\u7d22TinyRFEquip\u8d26\u53f7\u627e\u5230\u4ecb\u7ecdTinySA\u548cTinySA Ultra\u4ee5\u53ca\u5176\u4ed6TinyRFEquip\u4eea\u5668\u7684\u4e3b\u8981\u529f\u80fd\u4ecb\u7ecd\u89c6\u9891\u3002\u4f8b\u5982\uff1a</p>\n\n<p><a href=\"https://www.bilibili.com/video/BV1yt421u7Y2/?vd_source=8d60a323bdde2d574cb0a85c07cb3212\">TinySA Ultra\u5bf9\u4e8e\u65e0\u7ebf\u8bdd\u7b52\u7684\u9891\u7387\u7279\u6027\u68c0\u5b9a\u6d4b\u91cf_\u54d4\u54e9\u54d4\u54e9_bilibili</a></p>\n\n<p>https://www.bilibili.com/video/BV1yt421u7Y2/?vd_source=8d60a323bdde2d574cb0a85c07cb3212</p>\n\n<p><strong>\u6cd5\u5f8b\u5185\u5bb9</strong></p>\n\n<p>TinySA\u548cTinySA Ultra\u7684\u540d\u79f0\u4ee5\u53caTinySA\u5fbd\u6807\u662f\u6211\u4eec\u62e5\u6709\u7684\u6ce8\u518c\u5546\u6807\u3002\u672a\u7ecf\u4e66\u9762\u8bb8\u53ef\uff0c\u4e0d\u5141\u8bb8\u5176\u4ed6\u4eba\u4f7f\u7528TinySA\u8fd9\u4e2a\u540d\u5b57 \u6216 TinySA Ultra \u7528\u4e8e\u4efb\u4f55\u9891\u8c31\u5206\u6790\u4eea\u4ea7\u54c1\u3002</p>"}}]}','{"plugins": [{"pk": 10868, "creation_date": "2024-12-20T12:37:21.671Z", "position": 0, "plugin_type": "TextPlugin", "parent_id": 10867, "data": {"body": "<p>The TinyRFSG, which is completely independently developed by our store, is the world''s first. Before designing this product, the owner had already purchased various portable signal sources and small desktop signal sources on Taobao. However, they found that these signal sources had inaccurate first power (i.e. without real calibration), second input power amplitude that did not meet the standards stated in the instructions, poor third frequency step accuracy, often ranging from 1KHz to 10KHz, and too many harmonics. The second and third harmonics were basically not suppressed by filters, so square waves were used for counting.</p>\n\n<p>\u00a0</p>\n\n<p>As an engineer, I also need an excellent portable, pocket signal source. My requirement for my own signal source is accurate power: it can easily calibrate other spectrometers; Good harmonic suppression: pure signal; Strong output capability: Try to achieve a maximum output of 15dBm. Of course, as the frequency increases, the output power will decrease, but I will also tell the customer where my limit is; Portable: compact, strong anti-interference ability, suitable for pocket use.</p>\n\n<p>\u00a0</p>\n\n<p>At the same time, as it is our own research and development, we accept customized hardware and upper computer requirements from customers. Specific issues can be discussed in detail. At present, it only supports power supply on the computer side, and the computer software is controlled through the VISA interface.</p>"}}]}','en',1,1200,81);
INSERT INTO djangocms_history_placeholderaction VALUES(1232,'change_plugin','{"plugins": [{"pk": 10868, "creation_date": "2024-12-20T12:37:21.671Z", "position": 0, "plugin_type": "TextPlugin", "parent_id": 10867, "data": {"body": "<p>The TinyRFSG, which is completely independently developed by our store, is the world''s first. Before designing this product, the owner had already purchased various portable signal sources and small desktop signal sources on Taobao. However, they found that these signal sources had inaccurate first power (i.e. without real calibration), second input power amplitude that did not meet the standards stated in the instructions, poor third frequency step accuracy, often ranging from 1KHz to 10KHz, and too many harmonics. The second and third harmonics were basically not suppressed by filters, so square waves were used for counting.</p>\n\n<p>\u00a0</p>\n\n<p>As an engineer, I also need an excellent portable, pocket signal source. My requirement for my own signal source is accurate power: it can easily calibrate other spectrometers; Good harmonic suppression: pure signal; Strong output capability: Try to achieve a maximum output of 15dBm. Of course, as the frequency increases, the output power will decrease, but I will also tell the customer where my limit is; Portable: compact, strong anti-interference ability, suitable for pocket use.</p>\n\n<p>\u00a0</p>\n\n<p>At the same time, as it is our own research and development, we accept customized hardware and upper computer requirements from customers. Specific issues can be discussed in detail. At present, it only supports power supply on the computer side, and the computer software is controlled through the VISA interface.</p>"}}]}','{"plugins": [{"pk": 10868, "creation_date": "2024-12-20T12:37:21.671Z", "position": 0, "plugin_type": "TextPlugin", "parent_id": 10867, "data": {"body": "<p>The TinyRFSG, which is completely independently developed by our store, is the world''s first. Before designing this product, the owner had already purchased various portable signal sources and small desktop signal sources on Taobao. However, they found that these signal sources had inaccurate first power (i.e. without real calibration), second input power amplitude that did not meet the standards stated in the instructions, poor third frequency step accuracy, often ranging from 1KHz to 10KHz, and too many harmonics. The second and third harmonics were basically not suppressed by filters, so square waves were used for counting.</p>\n\n<p>As an engineer, I also need an excellent portable, pocket signal source. My requirement for my own signal source is accurate power: it can easily calibrate other spectrometers; Good harmonic suppression: pure signal; Strong output capability: Try to achieve a maximum output of 15dBm. Of course, as the frequency increases, the output power will decrease, but I will also tell the customer where my limit is; Portable: compact, strong anti-interference ability, suitable for pocket use.</p>\n\n<p>At the same time, as it is our own research and development, we accept customized hardware and upper computer requirements from customers. Specific issues can be discussed in detail. At present, it only supports power supply on the computer side, and the computer software is controlled through the VISA interface.</p>"}}]}','en',1,1201,81);
INSERT INTO djangocms_history_placeholderaction VALUES(1233,'change_plugin','{"plugins": [{"pk": 10862, "creation_date": "2024-12-20T12:31:27.640Z", "position": 2, "plugin_type": "TextPlugin", "parent_id": 10859, "data": {"body": "<p><strong>litevnalitevnalitevnalitevnalitevnalitevnalitevnalit</strong></p>"}}]}','{"plugins": [{"pk": 10862, "creation_date": "2024-12-20T12:31:27.640Z", "position": 2, "plugin_type": "TextPlugin", "parent_id": 10859, "data": {"body": "<p>TinyRFSG is a signal generator independently developed by our store, which supports a transmission frequency range of 20MHz~6GHz and can transmit a minimum signal of -60dBm; The maximum transmission amplitude reaches+15dBm (frequency range 20MHz~3GHz). And the power accuracy of this signal source is good, basically stable within 2dB.</p>"}}]}','en',1,1202,81);
INSERT INTO djangocms_history_placeholderaction VALUES(1234,'change_plugin','{"plugins": [{"pk": 10862, "creation_date": "2024-12-20T12:31:27.640Z", "position": 2, "plugin_type": "TextPlugin", "parent_id": 10859, "data": {"body": "<p>TinyRFSG is a signal generator independently developed by our store, which supports a transmission frequency range of 20MHz~6GHz and can transmit a minimum signal of -60dBm; The maximum transmission amplitude reaches+15dBm (frequency range 20MHz~3GHz). And the power accuracy of this signal source is good, basically stable within 2dB.</p>"}}]}','{"plugins": [{"pk": 10862, "creation_date": "2024-12-20T12:31:27.640Z", "position": 2, "plugin_type": "TextPlugin", "parent_id": 10859, "data": {"body": "<p>TinyRFSG is a signal generator independently developed by our store, which supports a transmission frequency range of 20MHz~6GHz and can transmit a minimum signal of -60dBm; The maximum transmission amplitude reaches+15dBm (frequency range 20MHz~3GHz). And the power accuracy of this signal source is good, basically stable within 2dB.</p>\n\n<p>This signal source is compact in size and can be carried around. Control the launch settings with the upper computer software, and also support pre configuration of all functions, which can run independently without the upper computer. And it is far superior to similar products on the market in various parameters, and can be used as a calibration source.</p>"}}]}','en',1,1203,81);
