INSERT INTO djangocms_history_placeholderaction VALUES(1246,'change_plugin','{"plugins": [{"pk": 10925, "creation_date": "2024-12-20T12:31:27.640Z", "position": 2, "plugin_type": "TextPlugin", "parent_id": 10922, "data": {"body": "<p><strong>Operating frequency: 9K-3G;</strong></p>\n\n<p><strong>Size: 73mm X 24mm (excluding connectors)</strong></p>\n\n<p><strong>Weight: 3.4 grams</strong></p>\n\n<p><strong>Connector: SMA Female Head</strong></p>"}}]}','{"plugins": [{"pk": 10925, "creation_date": "2024-12-20T12:31:27.640Z", "position": 2, "plugin_type": "TextPlugin", "parent_id": 10922, "data": {"body": "<p>Operating frequency: 9K-3G;</p>\n\n<p>Size: 73mm X 24mm (excluding connectors)</p>\n\n<p>Weight: 3.4 grams</p>\n\n<p>Connector: SMA Female Head</p>"}}]}','en',1,1214,82);
INSERT INTO djangocms_history_placeholderaction VALUES(1247,'change_plugin','{"plugins": [{"pk": 11057, "creation_date": "2024-12-20T12:37:21.671Z", "position": 0, "plugin_type": "TextPlugin", "parent_id": 11056, "data": {"body": "<p><strong>TinySA\u662f\u4e00\u79cd\u5c0f\u578b\u9891\u8c31\u5206\u6790\u4eea\u548c\u4fe1\u53f7\u53d1\u751f\u5668\uff0c\u5177\u6709\u4e00\u4e9b\u4e0d\u9519\u7684\u529f\u80fd\uff1a</strong></p>\n\n<ul>\n\t<li><strong>TinySA\u57fa\u672c\u7279\u70b9:</strong>\n\n\t<ul>\n\t\t<li>\u5c4f\u5e55\u5c3a\u5bf8 2.8\u82f1\u5bf8</li>\n\t\t<li>\u5e26\u4e24\u4e2a\u8f93\u5165\u7aef\u53e3\u7684\u9891\u8c31\u5206\u6790\u4eea\uff0cLow\u7aef\u53e3\u7528\u4e8e 10KHz-350MHz \u7684\u9ad8\u8d28\u91cf MF/HF/VHF \u8f93\u5165\uff0cHigh\u7aef\u53e3\u7528\u4e8e 240MHz-960MHz \u7684 UHF \u8f93\u5165\u3002</li>\n\t\t<li>\u4fe1\u53f7\u53d1\u751f\u5668\u5177\u6709\u4e24\u4e2a\u8f93\u51fa\uff0c\u6b63\u5f26\u6ce2\u8f93\u51fa\u4e3a100KHz - 350MHz\uff0c\u65b9\u6ce2\u8f93\u51fa\u4e3a 240MHz-960MHz\uff0c\u4fe1\u53f7\u53d1\u751f\u5668\u548c\u9891\u8c31\u5206\u6790\u4eea\u540c\u4e00\u65f6\u523b\u53ea\u80fd\u9009\u62e9\u5176\u4e2d\u7684\u4e00\u4e2a\u529f\u80fd\u3002</li>\n\t\t<li>\u5f69\u8272\u663e\u793a\u5c4f\u663e\u793a\u6700\u591a 290\u4e2a\u626b\u63cf\u70b9\uff0c\u63d0\u4f9b\u957f\u8fbe\u6574\u4e2a\u4f4e\u9891\u6216\u9ad8\u9891\u8303\u56f4\u7684\u65e0\u95f4\u9699\u8986\u76d6\u3002</li>\n\t</ul>\n\t</li>\n\t<li><strong>TinySA</strong>\u00a0<strong>Ultra\u57fa\u672c\u7279\u70b9:</strong>\n\t<ul>\n\t\t<li>\u5c4f\u5e55\u5c3a\u5bf8 4\u82f1\u5bf8</li>\n\t\t<li>\u9891\u8c31\u5206\u6790\u4eea\u6a21\u5f0f\uff0c\u521d\u59cb\u72b6\u6001\u4e3a10KHz-800MHz\uff0c\u5728\u542f\u7528\u72ec\u7279\u7684Ultra\u6a21\u5f0f\u7684\u60c5\u51b5\u4e0b\uff0c\u53ef\u4ee5\u76d1\u6d4b\u9ad8\u8fbe12GHz\u7684\u4fe1\u53f7\u3002</li>\n\t\t<li>\u4fe1\u53f7\u53d1\u751f\u5668\u6a21\u5f0f\uff0c\u6b63\u5f26\u6ce2\u8f93\u51fa\u5728100KHz-800MHz\u4e4b\u95f4\uff0c\u5c04\u9891\u6d4b\u8bd5\u4fe1\u53f7\u7684\u65b9\u6ce2\u8f93\u51fa\u9ad8\u8fbe5.3GHz\u3002</li>\n\t\t<li>200Hz\u81f3850KHz\u7684RBW\u8bbe\u7f6e\u63d0\u4f9b\u66f4\u9ad8\u7684\u7075\u654f\u5ea6\u8303\u56f4\u3002</li>\n\t\t<li>\u5185\u7f6e 20dB \u53ef\u9009 LNA</li>\n\t\t<li>\u5f69\u8272\u663e\u793a\u5c4f\u663e\u793a\u6700\u5927 450 \u4e2a\u70b9\uff0c\u63d0\u4f9b\u957f\u8fbe\u6574\u4e2a\u9891\u7387\u8303\u56f4\u7684\u65e0\u95f4\u9699\u8986\u76d6\u3002</li>\n\t\t<li>MicroSD\u5361\u63d2\u69fd\uff0c\u7528\u4e8e\u5b58\u50a8\u6d4b\u91cf\u503c\uff0c\u8bbe\u7f6e\u548c\u5c4f\u5e55\u622a\u56fe\u3002</li>\n\t</ul>\n\t</li>\n\t<li>\u8f93\u5165\u6b65\u8fdb\u8870\u51cf\u5668\u4ece0dB\u523031dB\uff08\u4e0d\u80fd\u4e0eLNA\u7ed3\u5408\u4f7f\u7528\uff09\u3002</li>\n\t<li>\u5185\u7f6e\u6821\u51c6\u4fe1\u53f7\u53d1\u751f\u5668\uff0c\u7528\u4e8e\u81ea\u52a8\u81ea\u68c0\u548c\uff08\u4f4e\uff09\u8f93\u5165\u6821\u51c6\u3002</li>\n\t<li>\u901a\u8fc7USB\u8fde\u63a5\u5230PC\uff0c\u5b83\u6210\u4e3aPC\u63a7\u5236\u7684\u9891\u8c31\u5206\u6790\u4eea\u6216\u4fe1\u53f7\u53d1\u751f\u5668</li>\n\t<li>\u9ad8\u8fbe3000mah\u7684\u53ef\u5145\u7535\u7535\u6c60\uff0c\u53ef\u643a\u5e26\u81f3\u5c112\u5c0f\u65f6\u3002</li>\n\t<li>\u6700\u5927\u8f93\u5165\u7535\u5e73 +6dBm\u3002</li>\n\t<li>\u4fe1\u53f7\u53d1\u751f\u5668\u529f\u80fd\u4e0d\u80fd\u7528\u4f5c\u8ddf\u8e2a\u53d1\u751f\u5668\uff0c\u56e0\u4e3a\u60a8\u4e0d\u80fd\u540c\u65f6\u4f7f\u7528\u9891\u8c31\u5206\u6790\u4eea\u548c\u4fe1\u53f7\u53d1\u751f\u5668\u529f\u80fd\u3002</li>\n\t<li>\u7531\u4e8e\u4f4e\u6210\u672c\u548c\u975e\u5e38\u5c0f\u7684\u5916\u5f62\u5c3a\u5bf8\uff0c\u5b58\u5728\u67d0\u4e9b\u76f8\u5173\u7684\u5fae\u5c0fSA\u9650\u5236\u548c\u5fae\u5c0fSA\u8d85\u9650\u5236\u3002</li>\n</ul>\n\n<figure><img alt=\"\" src=\"https://tinysa.org/wiki/uploads/Main/tinySA_housing.jpg\"></figure>\n\n<figure><img alt=\"\" src=\"https://tinysa.org/wiki/uploads/Main/tinySA_ultra.jpg\"></figure>\n\n<p><strong>\u89c6\u9891\u6559\u5b66\uff1a</strong></p>\n\n<p>\u53ef\u4ee5\u5728B\u7ad9\u4e5f\u5c31\u662f\u54d4\u54e9\u54d4\u54e9_bilibili\u7f51\u7ad9\u641c\u7d22TinyRFEquip\u8d26\u53f7\u627e\u5230\u4ecb\u7ecdTinySA\u548cTinySA Ultra\u4ee5\u53ca\u5176\u4ed6TinyRFEquip\u4eea\u5668\u7684\u4e3b\u8981\u529f\u80fd\u4ecb\u7ecd\u89c6\u9891\u3002\u4f8b\u5982\uff1a</p>\n\n<p><a href=\"https://www.bilibili.com/video/BV1yt421u7Y2/?vd_source=8d60a323bdde2d574cb0a85c07cb3212\">TinySA Ultra\u5bf9\u4e8e\u65e0\u7ebf\u8bdd\u7b52\u7684\u9891\u7387\u7279\u6027\u68c0\u5b9a\u6d4b\u91cf_\u54d4\u54e9\u54d4\u54e9_bilibili</a></p>\n\n<p>https://www.bilibili.com/video/BV1yt421u7Y2/?vd_source=8d60a323bdde2d574cb0a85c07cb3212</p>\n\n<p><strong>\u6cd5\u5f8b\u5185\u5bb9</strong></p>\n\n<p>TinySA\u548cTinySA Ultra\u7684\u540d\u79f0\u4ee5\u53caTinySA\u5fbd\u6807\u662f\u6211\u4eec\u62e5\u6709\u7684\u6ce8\u518c\u5546\u6807\u3002\u672a\u7ecf\u4e66\u9762\u8bb8\u53ef\uff0c\u4e0d\u5141\u8bb8\u5176\u4ed6\u4eba\u4f7f\u7528TinySA\u8fd9\u4e2a\u540d\u5b57 \u6216 TinySA Ultra \u7528\u4e8e\u4efb\u4f55\u9891\u8c31\u5206\u6790\u4eea\u4ea7\u54c1\u3002</p>"}}]}','{"plugins": [{"pk": 11057, "creation_date": "2024-12-20T12:37:21.671Z", "position": 0, "plugin_type": "TextPlugin", "parent_id": 11056, "data": {"body": "<p>There are a wide variety of RF connectors, making them extremely difficult to carry. RF enthusiasts and engineers often lose them due to poor storage. As a senior RF engineer, the shop owner shares the same feeling, so he designed this RF ToolKit. The ToolKit is exquisite, compact, and very easy to carry. On the basis of ensuring the 0-6G frequency coverage of all adapters, the carefully selected connector materials ensure the durability of the connectors. At the same time, advanced industrial plastics are used to make a sealed and waterproof storage box, which is very durable. It can be used as a gift for other RF engineers, please feel free to use it.</p>"}}]}','en',1,1215,84);
INSERT INTO djangocms_history_placeholderaction VALUES(1248,'change_plugin','{"plugins": [{"pk": 11049, "creation_date": "2024-12-20T12:30:45.026Z", "position": 0, "plugin_type": "HeadingPlugin", "parent_id": 11048, "data": {"ui_item": "Heading", "tag_type": "div", "config": {"heading_level": "h2", "heading": "LiteVNA", "heading_id": "", "heading_context": "dark", "heading_alignment": "", "attributes": {}, "margin_x": "", "margin_y": "", "margin_devices": null, "padding_x": "", "padding_y": "", "padding_devices": null}}}]}','{"plugins": [{"pk": 11049, "creation_date": "2024-12-20T12:30:45.026Z", "position": 0, "plugin_type": "HeadingPlugin", "parent_id": 11048, "data": {"ui_item": "Heading", "tag_type": "div", "config": {"heading_level": "h2", "heading": "Toolkit-Connector", "heading_id": "", "heading_context": "dark", "heading_alignment": "", "attributes": {}, "margin_x": "", "margin_y": "", "margin_devices": null, "padding_x": "", "padding_y": "", "padding_devices": null}}}]}','en',1,1216,84);
INSERT INTO djangocms_history_placeholderaction VALUES(1249,'change_plugin','{"plugins": [{"pk": 11057, "creation_date": "2024-12-20T12:37:21.671Z", "position": 0, "plugin_type": "TextPlugin", "parent_id": 11056, "data": {"body": "<p>There are a wide variety of RF connectors, making them extremely difficult to carry. RF enthusiasts and engineers often lose them due to poor storage. As a senior RF engineer, the shop owner shares the same feeling, so he designed this RF ToolKit. The ToolKit is exquisite, compact, and very easy to carry. On the basis of ensuring the 0-6G frequency coverage of all adapters, the carefully selected connector materials ensure the durability of the connectors. At the same time, advanced industrial plastics are used to make a sealed and waterproof storage box, which is very durable. It can be used as a gift for other RF engineers, please feel free to use it.</p>"}}]}','{"plugins": [{"pk": 11057, "creation_date": "2024-12-20T12:37:21.671Z", "position": 0, "plugin_type": "TextPlugin", "parent_id": 11056, "data": {"body": "<p>There are a wide variety of RF connectors, making them extremely difficult to carry. RF enthusiasts and engineers often lose them due to poor storage. As a senior RF engineer, the shop owner shares the same feeling, so he designed this RF ToolKit. The ToolKit is exquisite, compact, and very easy to carry. On the basis of ensuring the 0-6G frequency coverage of all adapters, the carefully selected connector materials ensure the durability of the connectors. At the same time, advanced industrial plastics are used to make a sealed and waterproof storage box, which is very durable. It can be used as a gift for other RF engineers, please feel free to use it.</p>\n\n<p>RF adapter ToolKit product list (no network calibration part version)<br>\nThe size of KX-01 ToolKit toolbox is 223 \u00d7 158 \u00d7 42mm<br>\nN female head straight through x 1<br>\nN-head straight through x 1<br>\nN male head to female head x 1<br>\nSMA male head straight through x 1<br>\nSMA female head straight through x 1<br>\nSMA male head to female head x 1<br>\nSMA male head to N female head x 1<br>\nSMA male head to N male head x 1<br>\nSMA female head to N female head x 1<br>\nSMA female head to N male head x 1<br>\nBNC male head to SMA female head x 1<br>\nBNC female head to SMA male head x 1<br>\nSMA isolated by 1</p>\n\n<p>\u00a0</p>\n\n<p>RF Adapter ToolKit Product List (Upgraded Version)<br>\nThe size of KX-01 ToolKit toolbox is 22315842 mm</p>\n\n<p>N female head straight through 1<br>\nN-head straight through 1<br>\nN male head to female head 1<br>\nSMA male head straight through 1<br>\nSMA female head straight through 1<br>\nSMA male head to female head 1<br>\nSMA male head to N female head 1<br>\nSMA male head to N male head 1<br>\nSMA female head to N female head 1<br>\nSMA female head to N male head 1<br>\nBNC male head to SMA female head 1<br>\nBNC female head to SMA male head 1<br>\nSMA Straight 1<br>\nSMA Head Vector Network Analyzer Calibration Parts: (Supports up to 6G)\u00a0 \u00a0open1, short1, load1<br>\nCalibration parts for N-head vector network analyzer: (Upgraded version can support up to 8.5G, suitable for R&amp;S and related products from KeySight)\u00a0 open1\u3001short1\u3001load1</p>"}}]}','en',1,1217,84);
INSERT INTO djangocms_history_placeholderaction VALUES(1250,'change_plugin','{"plugins": [{"pk": 11183, "creation_date": "2024-12-20T12:37:21.671Z", "position": 0, "plugin_type": "TextPlugin", "parent_id": 11182, "data": {"body": "<p><strong>TinySA\u662f\u4e00\u79cd\u5c0f\u578b\u9891\u8c31\u5206\u6790\u4eea\u548c\u4fe1\u53f7\u53d1\u751f\u5668\uff0c\u5177\u6709\u4e00\u4e9b\u4e0d\u9519\u7684\u529f\u80fd\uff1a</strong></p>\n\n<ul>\n\t<li><strong>TinySA\u57fa\u672c\u7279\u70b9:</strong>\n\n\t<ul>\n\t\t<li>\u5c4f\u5e55\u5c3a\u5bf8 2.8\u82f1\u5bf8</li>\n\t\t<li>\u5e26\u4e24\u4e2a\u8f93\u5165\u7aef\u53e3\u7684\u9891\u8c31\u5206\u6790\u4eea\uff0cLow\u7aef\u53e3\u7528\u4e8e 10KHz-350MHz \u7684\u9ad8\u8d28\u91cf MF/HF/VHF \u8f93\u5165\uff0cHigh\u7aef\u53e3\u7528\u4e8e 240MHz-960MHz \u7684 UHF \u8f93\u5165\u3002</li>\n\t\t<li>\u4fe1\u53f7\u53d1\u751f\u5668\u5177\u6709\u4e24\u4e2a\u8f93\u51fa\uff0c\u6b63\u5f26\u6ce2\u8f93\u51fa\u4e3a100KHz - 350MHz\uff0c\u65b9\u6ce2\u8f93\u51fa\u4e3a 240MHz-960MHz\uff0c\u4fe1\u53f7\u53d1\u751f\u5668\u548c\u9891\u8c31\u5206\u6790\u4eea\u540c\u4e00\u65f6\u523b\u53ea\u80fd\u9009\u62e9\u5176\u4e2d\u7684\u4e00\u4e2a\u529f\u80fd\u3002</li>\n\t\t<li>\u5f69\u8272\u663e\u793a\u5c4f\u663e\u793a\u6700\u591a 290\u4e2a\u626b\u63cf\u70b9\uff0c\u63d0\u4f9b\u957f\u8fbe\u6574\u4e2a\u4f4e\u9891\u6216\u9ad8\u9891\u8303\u56f4\u7684\u65e0\u95f4\u9699\u8986\u76d6\u3002</li>\n\t</ul>\n\t</li>\n\t<li><strong>TinySA</strong>\u00a0<strong>Ultra\u57fa\u672c\u7279\u70b9:</strong>\n\t<ul>\n\t\t<li>\u5c4f\u5e55\u5c3a\u5bf8 4\u82f1\u5bf8</li>\n\t\t<li>\u9891\u8c31\u5206\u6790\u4eea\u6a21\u5f0f\uff0c\u521d\u59cb\u72b6\u6001\u4e3a10KHz-800MHz\uff0c\u5728\u542f\u7528\u72ec\u7279\u7684Ultra\u6a21\u5f0f\u7684\u60c5\u51b5\u4e0b\uff0c\u53ef\u4ee5\u76d1\u6d4b\u9ad8\u8fbe12GHz\u7684\u4fe1\u53f7\u3002</li>\n\t\t<li>\u4fe1\u53f7\u53d1\u751f\u5668\u6a21\u5f0f\uff0c\u6b63\u5f26\u6ce2\u8f93\u51fa\u5728100KHz-800MHz\u4e4b\u95f4\uff0c\u5c04\u9891\u6d4b\u8bd5\u4fe1\u53f7\u7684\u65b9\u6ce2\u8f93\u51fa\u9ad8\u8fbe5.3GHz\u3002</li>\n\t\t<li>200Hz\u81f3850KHz\u7684RBW\u8bbe\u7f6e\u63d0\u4f9b\u66f4\u9ad8\u7684\u7075\u654f\u5ea6\u8303\u56f4\u3002</li>\n\t\t<li>\u5185\u7f6e 20dB \u53ef\u9009 LNA</li>\n\t\t<li>\u5f69\u8272\u663e\u793a\u5c4f\u663e\u793a\u6700\u5927 450 \u4e2a\u70b9\uff0c\u63d0\u4f9b\u957f\u8fbe\u6574\u4e2a\u9891\u7387\u8303\u56f4\u7684\u65e0\u95f4\u9699\u8986\u76d6\u3002</li>\n\t\t<li>MicroSD\u5361\u63d2\u69fd\uff0c\u7528\u4e8e\u5b58\u50a8\u6d4b\u91cf\u503c\uff0c\u8bbe\u7f6e\u548c\u5c4f\u5e55\u622a\u56fe\u3002</li>\n\t</ul>\n\t</li>\n\t<li>\u8f93\u5165\u6b65\u8fdb\u8870\u51cf\u5668\u4ece0dB\u523031dB\uff08\u4e0d\u80fd\u4e0eLNA\u7ed3\u5408\u4f7f\u7528\uff09\u3002</li>\n\t<li>\u5185\u7f6e\u6821\u51c6\u4fe1\u53f7\u53d1\u751f\u5668\uff0c\u7528\u4e8e\u81ea\u52a8\u81ea\u68c0\u548c\uff08\u4f4e\uff09\u8f93\u5165\u6821\u51c6\u3002</li>\n\t<li>\u901a\u8fc7USB\u8fde\u63a5\u5230PC\uff0c\u5b83\u6210\u4e3aPC\u63a7\u5236\u7684\u9891\u8c31\u5206\u6790\u4eea\u6216\u4fe1\u53f7\u53d1\u751f\u5668</li>\n\t<li>\u9ad8\u8fbe3000mah\u7684\u53ef\u5145\u7535\u7535\u6c60\uff0c\u53ef\u643a\u5e26\u81f3\u5c112\u5c0f\u65f6\u3002</li>\n\t<li>\u6700\u5927\u8f93\u5165\u7535\u5e73 +6dBm\u3002</li>\n\t<li>\u4fe1\u53f7\u53d1\u751f\u5668\u529f\u80fd\u4e0d\u80fd\u7528\u4f5c\u8ddf\u8e2a\u53d1\u751f\u5668\uff0c\u56e0\u4e3a\u60a8\u4e0d\u80fd\u540c\u65f6\u4f7f\u7528\u9891\u8c31\u5206\u6790\u4eea\u548c\u4fe1\u53f7\u53d1\u751f\u5668\u529f\u80fd\u3002</li>\n\t<li>\u7531\u4e8e\u4f4e\u6210\u672c\u548c\u975e\u5e38\u5c0f\u7684\u5916\u5f62\u5c3a\u5bf8\uff0c\u5b58\u5728\u67d0\u4e9b\u76f8\u5173\u7684\u5fae\u5c0fSA\u9650\u5236\u548c\u5fae\u5c0fSA\u8d85\u9650\u5236\u3002</li>\n</ul>\n\n<figure><img alt=\"\" src=\"https://tinysa.org/wiki/uploads/Main/tinySA_housing.jpg\"></figure>\n\n<figure><img alt=\"\" src=\"https://tinysa.org/wiki/uploads/Main/tinySA_ultra.jpg\"></figure>\n\n<p><strong>\u89c6\u9891\u6559\u5b66\uff1a</strong></p>\n\n<p>\u53ef\u4ee5\u5728B\u7ad9\u4e5f\u5c31\u662f\u54d4\u54e9\u54d4\u54e9_bilibili\u7f51\u7ad9\u641c\u7d22TinyRFEquip\u8d26\u53f7\u627e\u5230\u4ecb\u7ecdTinySA\u548cTinySA Ultra\u4ee5\u53ca\u5176\u4ed6TinyRFEquip\u4eea\u5668\u7684\u4e3b\u8981\u529f\u80fd\u4ecb\u7ecd\u89c6\u9891\u3002\u4f8b\u5982\uff1a</p>\n\n<p><a href=\"https://www.bilibili.com/video/BV1yt421u7Y2/?vd_source=8d60a323bdde2d574cb0a85c07cb3212\">TinySA Ultra\u5bf9\u4e8e\u65e0\u7ebf\u8bdd\u7b52\u7684\u9891\u7387\u7279\u6027\u68c0\u5b9a\u6d4b\u91cf_\u54d4\u54e9\u54d4\u54e9_bilibili</a></p>\n\n<p>https://www.bilibili.com/video/BV1yt421u7Y2/?vd_source=8d60a323bdde2d574cb0a85c07cb3212</p>\n\n<p><strong>\u6cd5\u5f8b\u5185\u5bb9</strong></p>\n\n<p>TinySA\u548cTinySA Ultra\u7684\u540d\u79f0\u4ee5\u53caTinySA\u5fbd\u6807\u662f\u6211\u4eec\u62e5\u6709\u7684\u6ce8\u518c\u5546\u6807\u3002\u672a\u7ecf\u4e66\u9762\u8bb8\u53ef\uff0c\u4e0d\u5141\u8bb8\u5176\u4ed6\u4eba\u4f7f\u7528TinySA\u8fd9\u4e2a\u540d\u5b57 \u6216 TinySA Ultra \u7528\u4e8e\u4efb\u4f55\u9891\u8c31\u5206\u6790\u4eea\u4ea7\u54c1\u3002</p>"}}]}','{"plugins": [{"pk": 11183, "creation_date": "2024-12-20T12:37:21.671Z", "position": 0, "plugin_type": "TextPlugin", "parent_id": 11182, "data": {"body": "<p>All antennas sold in our store have been personally selected and tested by the store owner to be suitable for the frequency band required by the customer, and relevant test lines have been provided. Antennas that meet S11 and VSWR performance requirements can be purchased with confidence. If you have any other needs, please contact customer service to provide professional technical knowledge answers.</p>"}}]}','en',1,1218,86);
