INSERT INTO djangocms_history_placeholderaction VALUES(1253,'change_plugin','{"plugins": [{"pk": 10925, "creation_date": "2024-12-20T12:31:27.640Z", "position": 2, "plugin_type": "TextPlugin", "parent_id": 10922, "data": {"body": "<p>Operating frequency: 9K-3G;</p>\n\n<p>Size: 73mm X 24mm (excluding connectors)</p>\n\n<p>Weight: 3.4 grams</p>\n\n<p>Connector: SMA Female Head</p>"}}]}','{"plugins": [{"pk": 10925, "creation_date": "2024-12-20T12:31:27.640Z", "position": 2, "plugin_type": "TextPlugin", "parent_id": 10922, "data": {"body": "<p>Operating frequency: 9K-3G;</p>\n\n<p>Size: 73mm X 24mm (excluding connectors)</p>\n\n<p>Weight: 3.4 g</p>\n\n<p>Connector: SMA Female Head</p>"}}]}','en',1,1221,82);
INSERT INTO djangocms_history_placeholderaction VALUES(1254,'change_plugin','{"plugins": [{"pk": 10931, "creation_date": "2024-12-20T12:37:21.671Z", "position": 0, "plugin_type": "TextPlugin", "parent_id": 10930, "data": {"body": "<p>This product set includes 4 H-Field probes, which are magnetic field probes. The main function of the magnetic field probes is to detect changes in voltage and radiation.</p>\n\n<p>One E-field, also known as an electric field probe, mainly detects changes in current and radiation.</p>\n\n<p>This product is widely used for EMC and EMI testing, and of course, it can also measure wireless signals near the emission source. The video shows monitoring the key signal of a Honda CRV.</p>"}}]}','{"plugins": [{"pk": 10931, "creation_date": "2024-12-20T12:37:21.671Z", "position": 0, "plugin_type": "TextPlugin", "parent_id": 10930, "data": {"body": "<p>This product set includes 4 H-Field probes, which are magnetic field probes. The main function of the magnetic field probes is to detect changes in voltage and radiation.</p>\n\n<p>One E-field, also known as an electric field probe, mainly detects changes in current and radiation.</p>\n\n<p>This product is widely used for EMC and EMI testing, and of course, it can also measure wireless signals near the emission source. The video shows monitoring the key signal of a Honda CRV.</p>\n\n<p>When using, do not touch the PCB board with your hands\uff01\uff01\uff01</p>\n\n<p>\u00a0</p>"}}]}','en',1,1222,82);
INSERT INTO djangocms_history_placeholderaction VALUES(1255,'change_plugin','{"plugins": [{"pk": 10925, "creation_date": "2024-12-20T12:31:27.640Z", "position": 2, "plugin_type": "TextPlugin", "parent_id": 10922, "data": {"body": "<p>Operating frequency: 9K-3G;</p>\n\n<p>Size: 73mm X 24mm (excluding connectors)</p>\n\n<p>Weight: 3.4 g</p>\n\n<p>Connector: SMA Female Head</p>"}}]}','{"plugins": [{"pk": 10925, "creation_date": "2024-12-20T12:31:27.640Z", "position": 2, "plugin_type": "TextPlugin", "parent_id": 10922, "data": {"body": "<p>H-Field E-Field PROBE EMC EMI Near Field Probe Conducted Radiation Rectification Simple Magnetic Field Probe</p>\n\n<p>Operating frequency: 9K-3G;</p>\n\n<p>Size: 73mm X 24mm (excluding connectors)</p>\n\n<p>Weight: 3.4 g</p>\n\n<p>Connector: SMA Female Head</p>"}}]}','en',1,1223,82);
INSERT INTO djangocms_history_placeholderaction VALUES(1256,'change_plugin','{"plugins": [{"pk": 10931, "creation_date": "2024-12-20T12:37:21.671Z", "position": 0, "plugin_type": "TextPlugin", "parent_id": 10930, "data": {"body": "<p>This product set includes 4 H-Field probes, which are magnetic field probes. The main function of the magnetic field probes is to detect changes in voltage and radiation.</p>\n\n<p>One E-field, also known as an electric field probe, mainly detects changes in current and radiation.</p>\n\n<p>This product is widely used for EMC and EMI testing, and of course, it can also measure wireless signals near the emission source. The video shows monitoring the key signal of a Honda CRV.</p>\n\n<p>When using, do not touch the PCB board with your hands\uff01\uff01\uff01</p>\n\n<p>\u00a0</p>"}}]}','{"plugins": [{"pk": 10931, "creation_date": "2024-12-20T12:37:21.671Z", "position": 0, "plugin_type": "TextPlugin", "parent_id": 10930, "data": {"body": "<p>This product set includes 4 H-Field probes, which are magnetic field probes. The main function of the magnetic field probes is to detect changes in voltage and radiation.</p>\n\n<p>One E-field, also known as an electric field probe, mainly detects changes in current and radiation.</p>\n\n<p>This product is widely used for EMC and EMI testing, and of course, it can also measure wireless signals near the emission source. The video shows monitoring the key signal of a Honda CRV.</p>\n\n<p>When using, do not touch the PCB board with your hands\uff01\uff01\uff01</p>\n\n<p>Magnetic field probe 1-4</p>\n\n<p><cms-plugin alt=\"Picture / Image - Image (15501) \" title=\"Picture / Image - Image (15501)\" id=\"15501\"></cms-plugin></p>\n\n<p><cms-plugin alt=\"Picture / Image - Image (15502) \" title=\"Picture / Image - Image (15502)\" id=\"15502\"></cms-plugin></p>\n\n<p><cms-plugin alt=\"Picture / Image - Image (15503) \" title=\"Picture / Image - Image (15503)\" id=\"15503\"></cms-plugin></p>\n\n<p><cms-plugin alt=\"Picture / Image - Image (15504) \" title=\"Picture / Image - Image (15504)\" id=\"15504\"></cms-plugin></p>\n\n<p>Electric field probe</p>\n\n<p><cms-plugin alt=\"Picture / Image - Image (15505) \" title=\"Picture / Image - Image (15505)\" id=\"15505\"></cms-plugin></p>"}}]}','en',1,1224,82);
