INSERT INTO djangocms_history_placeholderaction VALUES(1349,'change_plugin','{"plugins": [{"pk": 1581, "creation_date": "2024-12-20T12:37:21.671Z", "position": 0, "plugin_type": "TextPlugin", "parent_id": 1580, "data": {"body": "<p>Material: Aluminum Alloy(Case)</p>\n\n<p>Size : 140 * 73 * 20mm\u00a0</p>\n\n<p>Measurement Frequency: 50kHz-4.4GHz</p>\n\n<p>Port SWR: &lt; 1</p>\n\n<p>Display: 4.3 inch IPS(800 x 480)</p>\n\n<p>Power: USB 5V/1A,built in 5000mAh lithium battery</p>\n\n<p>USB interface: USB type-C communication mode: CDC (serial)</p>\n\n<p>RF output : -9dBm (\u00b11dB)</p>\n\n<p>Frequency accuracy: &lt;0.5ppm</p>\n\n<p>S21 dynamic ranges: 70dB (1.5GHz), 60dB (3GHz); S11 dynamic ranges: 50dB (1.5GHz), 40dB (3GHz)</p>\n\n<p>Calibration points: 101-301 points</p>\n\n<p>Scanning points: 101-301 points</p>\n\n<p>Display Tracking: 4;Marking: 4 ;Setting save: 5</p>\n\n<p>Scan time: about 200points/per second</p>"}}]}','{"plugins": [{"pk": 1581, "creation_date": "2024-12-20T12:37:21.671Z", "position": 0, "plugin_type": "TextPlugin", "parent_id": 1580, "data": {"body": ""}}]}','en',1,1302,49);
