INSERT INTO djangocms_history_placeholderaction VALUES(1382,'change_plugin','{"plugins": [{"pk": 1340, "creation_date": "2024-12-20T12:31:27.640Z", "position": 2, "plugin_type": "TextPlugin", "parent_id": 1337, "data": {"body": "<ul>\n\t<li>Tinysa ULTRA+ ZS406 owns high performance frequency in 100khz to 900MHz, and when in ultra mode, the analyzer can reach 5.4GHz. With new 4'''' touchscreen display and installed with the latest hardware system V0.4.6. Built-in 32Gb micro TF\u00a0card for data transfer and storage</li>\n\t<li>[Frequency Range] Tinysa ultra measures from 100KHz-5.4GHz: Spectrum Analyzer for 0.1MHz-900MHz, with Ultra mode enabled, level calibrated up to 6GHz, can observe signals up to 12GHz. RBW from 200Hz-850kHz, you can fast and accurate execute measurement tests. Color display showing max 450 points providing gapless covering up to the full frequency range</li>\n\t<li><a href=\"https://item.taobao.com/item.htm?id=849801646126&amp;pisk=gX4tqf4J49XM3Satt5SHm0DDW8C3BMVN9RPWoxDMcJeLGRMinfTsAvGoNdG_Gx0YH-exIm6ZSreLh-L0jP0icZMLCEmgkS8xGSwV_xfNx5PZuq6lETbu_5Pmp0JbWFGIOWl2cdsnfQ9nXxWlEablfBgABT2c67FGRbhSlfijCD1KZbvslmgXO6hjidtX5-1d9jcXCCMjl2tINv9XlhTbO2G-NnGscj1LOvlxhqgbh21Kgbcfvx-sEEEPYctfdgRKPqaK6cH79g8XkOGeExN6YELbJkUIFaDplEaK6ShpA5YRmYZrI0D0dwYtkWGYIv25Pe3I2uPmMRQ95VqQYPug-TpmX2ksVoid1NNKWAn85cQACVEbQrnaXI5zOVwU4Yo1Y9lLSzmxUDpCCWVKC0EYI98jIuFQp04HKU04LowjMJ9O43zuykmBEYhDf6Cp0nosT0l3hX6Trmvj9Yfnsn-qvMlKE6Cp0nosTXHltKx20DIF.&amp;skuId=5757350816604&amp;spm=a21xtw.29978516.0.0\">Purchase link:TinySA ULTRA Spectrum Analyzer 10K-12GHz Bluetooth Ham RF</a></li>\n</ul>"}}]}','{"plugins": [{"pk": 1340, "creation_date": "2024-12-20T12:31:27.640Z", "position": 2, "plugin_type": "TextPlugin", "parent_id": 1337, "data": {"body": "<ul>\n\t<li>Tinysa ULTRA+ ZS406 owns high performance frequency in 100khz to 900MHz, and when in ultra mode, the analyzer can reach 5.4GHz. With new 4'''' touchscreen display and installed with the latest hardware system V0.4.6. Built-in 32Gb micro TF\u00a0card for data transfer and storage</li>\n\t<li>[Frequency Range] Tinysa ultra measures from 100KHz-5.4GHz: Spectrum Analyzer for 0.1MHz-900MHz, with Ultra mode enabled, level calibrated up to 6GHz, can observe signals up to 12GHz. RBW from 200Hz-850kHz, you can fast and accurate execute measurement tests. Color display showing max 450 points providing gapless covering up to the full frequency range</li>\n\t<li><a href=\"https://item.taobao.com/item.htm?id=849801646126&amp;pisk=gX4tqf4J49XM3Satt5SHm0DDW8C3BMVN9RPWoxDMcJeLGRMinfTsAvGoNdG_Gx0YH-exIm6ZSreLh-L0jP0icZMLCEmgkS8xGSwV_xfNx5PZuq6lETbu_5Pmp0JbWFGIOWl2cdsnfQ9nXxWlEablfBgABT2c67FGRbhSlfijCD1KZbvslmgXO6hjidtX5-1d9jcXCCMjl2tINv9XlhTbO2G-NnGscj1LOvlxhqgbh21Kgbcfvx-sEEEPYctfdgRKPqaK6cH79g8XkOGeExN6YELbJkUIFaDplEaK6ShpA5YRmYZrI0D0dwYtkWGYIv25Pe3I2uPmMRQ95VqQYPug-TpmX2ksVoid1NNKWAn85cQACVEbQrnaXI5zOVwU4Yo1Y9lLSzmxUDpCCWVKC0EYI98jIuFQp04HKU04LowjMJ9O43zuykmBEYhDf6Cp0nosT0l3hX6Trmvj9Yfnsn-qvMlKE6Cp0nosTXHltKx20DIF.&amp;skuId=5757350816604&amp;spm=a21xtw.29978516.0.0\">Purchase link:TinySA ULTRA Spectrum Analyzer 10K-12GHz Bluetooth Ham RF</a></li>\n</ul>\n\n<p>Price: 752 RMB (excluding tax)</p>"}}]}','en',1,1335,47);
INSERT INTO djangocms_history_placeholderaction VALUES(1383,'change_plugin','{"plugins": [{"pk": 13908, "creation_date": "2024-12-20T12:31:27.640Z", "position": 2, "plugin_type": "TextPlugin", "parent_id": 13905, "data": {"body": "<ul>\n\t<li>\n\t<p id=\"title\">Tinysa Ultra+ ZS407 spectrum analyzer: With ultra-wide frequency range of 100kHz-7.3GHz, enabling you to capture and analyze a broader spectrum of signals precisely. With 4\u201d IPS-TFT LCD (480\u00d7320) display can show a maximum of 450 points per scan, clearly presenting signal details and measurement results. Supports PC control, enabling easy data transfer and analysis</p>\n\t</li>\n\t<li>Ultra-Wide Frequency Range: The TinySA Ultra+ ZS407 Spectrum Analyzer covers a frequency range of 0.1 - 900MHz, with Ultra mode enabled up to 7.3 GHz, level calibrated up to 7.3GHz. Can observe signals up to 12GHz, which represents a significant improvement over previous models. It can accurately capture and analyze a broader range of signals, making it suitable for a variety of complex RF testing scenarios</li>\n\t<li>Signal Generation Capability: ZS407 have the SG function, but the SG function is not calibrated and the max output power is -18.5dbm, sine wave output between 0.1 MHz and 900 MHz, square wave output up to 6.3 GHz, or RF test signal output up to 7.3 GHz. It has a rich variety of signal generation types and a wide frequency range</li>\n\t<li><a href=\"https://item.taobao.com/item.htm?id=849801646126&amp;pisk=gX4tqf4J49XM3Satt5SHm0DDW8C3BMVN9RPWoxDMcJeLGRMinfTsAvGoNdG_Gx0YH-exIm6ZSreLh-L0jP0icZMLCEmgkS8xGSwV_xfNx5PZuq6lETbu_5Pmp0JbWFGIOWl2cdsnfQ9nXxWlEablfBgABT2c67FGRbhSlfijCD1KZbvslmgXO6hjidtX5-1d9jcXCCMjl2tINv9XlhTbO2G-NnGscj1LOvlxhqgbh21Kgbcfvx-sEEEPYctfdgRKPqaK6cH79g8XkOGeExN6YELbJkUIFaDplEaK6ShpA5YRmYZrI0D0dwYtkWGYIv25Pe3I2uPmMRQ95VqQYPug-TpmX2ksVoid1NNKWAn85cQACVEbQrnaXI5zOVwU4Yo1Y9lLSzmxUDpCCWVKC0EYI98jIuFQp04HKU04LowjMJ9O43zuykmBEYhDf6Cp0nosT0l3hX6Trmvj9Yfnsn-qvMlKE6Cp0nosTXHltKx20DIF.&amp;skuId=5757350816604&amp;spm=a21xtw.29978516.0.0\">Purchase link\uff1aTinySA ULTRA Spectrum Analyzer 10K-12GHz Bluetooth Ham RF</a></li>\n</ul>"}}]}','{"plugins": [{"pk": 13908, "creation_date": "2024-12-20T12:31:27.640Z", "position": 2, "plugin_type": "TextPlugin", "parent_id": 13905, "data": {"body": "<ul>\n\t<li>\n\t<p id=\"title\">Tinysa Ultra+ ZS407 spectrum analyzer: With ultra-wide frequency range of 100kHz-7.3GHz, enabling you to capture and analyze a broader spectrum of signals precisely. With 4\u201d IPS-TFT LCD (480\u00d7320) display can show a maximum of 450 points per scan, clearly presenting signal details and measurement results. Supports PC control, enabling easy data transfer and analysis</p>\n\t</li>\n\t<li>Ultra-Wide Frequency Range: The TinySA Ultra+ ZS407 Spectrum Analyzer covers a frequency range of 0.1 - 900MHz, with Ultra mode enabled up to 7.3 GHz, level calibrated up to 7.3GHz. Can observe signals up to 12GHz, which represents a significant improvement over previous models. It can accurately capture and analyze a broader range of signals, making it suitable for a variety of complex RF testing scenarios</li>\n\t<li>Signal Generation Capability: ZS407 have the SG function, but the SG function is not calibrated and the max output power is -18.5dbm, sine wave output between 0.1 MHz and 900 MHz, square wave output up to 6.3 GHz, or RF test signal output up to 7.3 GHz. It has a rich variety of signal generation types and a wide frequency range</li>\n\t<li><a href=\"https://item.taobao.com/item.htm?id=849801646126&amp;pisk=gX4tqf4J49XM3Satt5SHm0DDW8C3BMVN9RPWoxDMcJeLGRMinfTsAvGoNdG_Gx0YH-exIm6ZSreLh-L0jP0icZMLCEmgkS8xGSwV_xfNx5PZuq6lETbu_5Pmp0JbWFGIOWl2cdsnfQ9nXxWlEablfBgABT2c67FGRbhSlfijCD1KZbvslmgXO6hjidtX5-1d9jcXCCMjl2tINv9XlhTbO2G-NnGscj1LOvlxhqgbh21Kgbcfvx-sEEEPYctfdgRKPqaK6cH79g8XkOGeExN6YELbJkUIFaDplEaK6ShpA5YRmYZrI0D0dwYtkWGYIv25Pe3I2uPmMRQ95VqQYPug-TpmX2ksVoid1NNKWAn85cQACVEbQrnaXI5zOVwU4Yo1Y9lLSzmxUDpCCWVKC0EYI98jIuFQp04HKU04LowjMJ9O43zuykmBEYhDf