INSERT INTO djangocms_history_placeholderaction VALUES(1437,'change_plugin','{"plugins": [{"pk": 17696, "creation_date": "2025-06-09T09:23:23.174Z", "position": 1, "plugin_type": "TextPlugin", "parent_id": 14669, "data": {"body": "<p>Here are all the documents you need about the device, including user manuals, programming guides, etc. If you have any other questions or interests, please send me a private message and I will answer them for you.</p>"}}]}','{"plugins": [{"pk": 17696, "creation_date": "2025-06-09T09:23:23.174Z", "position": 1, "plugin_type": "TextPlugin", "parent_id": 14669, "data": {"body": "<p>Here are all the documents you need about the device, including user manuals, programming guides, etc. If you have any other questions or interests, please send me a private message and I will answer them for you.</p>\n\n<p><cms-plugin alt=\"File - TinySA and Ultra_UserManualAndProgrammingGuide_V1.6.pdf \" title=\"File - TinySA and Ultra_UserManualAndProgrammingGuide_V1.6.pdf\" id=\"18279\"></cms-plugin></p>\n\n<p>\u00a0</p>\n\n<p><cms-plugin alt=\"File - NanoVNA-F V2_UserManualAndProgrammingGuide.pdf \" title=\"File - NanoVNA-F V2_UserManualAndProgrammingGuide.pdf\" id=\"18280\"></cms-plugin></p>\n\n<p>\u00a0</p>\n\n<p><cms-plugin alt=\"File - NanoVNA-F V3_UserManualAndProgrammingGuide.pdf \" title=\"File - NanoVNA-F V3_UserManualAndProgrammingGuide.pdf\" id=\"18281\"></cms-plugin></p>\n\n<p>\u00a0</p>\n\n<p><cms-plugin alt=\"File - LiteVNA_User-Guide.pdf \" title=\"File - LiteVNA_User-Guide.pdf\" id=\"18282\"></cms-plugin></p>"}}]}','en',1,1389,104);
