INSERT INTO djangocms_history_placeholderaction VALUES(1443,'change_plugin','{"plugins": [{"pk": 17690, "creation_date": "2025-06-09T08:15:06.699Z", "position": 1, "plugin_type": "TextPlugin", "parent_id": 9691, "data": {"body": "<p>111</p>"}}]}','{"plugins": [{"pk": 17690, "creation_date": "2025-06-09T08:15:06.699Z", "position": 1, "plugin_type": "TextPlugin", "parent_id": 9691, "data": {"body": "<p>TinyRFSG:\u00a0</p>\n\n<p>1.Basic introduction of signal source and display of the whole family bucket:\u00a0<a href=\"https://www.bilibili.com/video/BV1FuMMzZEkQ/?spm_id_from=333.1387.homepage.video_card.click\">\u9996\u53d1\uff01\uff01\u9ad8\u7cbe\u5ea6\u5927\u529f\u7387\u8d85\u4fbf\u643a\u53ef\u7f16\u7a0b\u5c04\u9891\u4fe1\u53f7\u6e90TinyRFSG_\u54d4\u54e9\u54d4\u54e9_bilibili</a></p>"}}]}','en',1,1394,71);
INSERT INTO djangocms_history_placeholderaction VALUES(1444,'change_plugin','{"plugins": [{"pk": 17690, "creation_date": "2025-06-09T08:15:06.699Z", "position": 1, "plugin_type": "TextPlugin", "parent_id": 9691, "data": {"body": "<p>TinyRFSG:\u00a0</p>\n\n<p>1.Basic introduction of signal source and display of the whole family bucket:\u00a0<a href=\"https://www.bilibili.com/video/BV1FuMMzZEkQ/?spm_id_from=333.1387.homepage.video_card.click\">\u9996\u53d1\uff01\uff01\u9ad8\u7cbe\u5ea6\u5927\u529f\u7387\u8d85\u4fbf\u643a\u53ef\u7f16\u7a0b\u5c04\u9891\u4fe1\u53f7\u6e90TinyRFSG_\u54d4\u54e9\u54d4\u54e9_bilibili</a></p>"}}]}','{"plugins": [{"pk": 17690, "creation_date": "2025-06-09T08:15:06.699Z", "position": 1, "plugin_type": "TextPlugin", "parent_id": 9691, "data": {"body": "<p>TinyRFSG:\u00a0</p>\n\n<p>1.Basic introduction of signal source and display of the whole family bucket:\u00a0</p>\n\n<p><a href=\"https://www.youtube.com/watch?v=7wull02SPAY\">Debut!! high precision and power, ultra portable programmable RF signal generator TinyRFSG</a></p>"}}]}','en',1,1395,71);
INSERT INTO djangocms_history_placeholderaction VALUES(1445,'add_plugin','{"parent_id": null, "order": [1566, 2378, 2408, 9262, 18311]}','{"parent_id": null, "plugins": [{"pk": 18311, "creation_date": "2025-06-16T04:00:08.472Z", "position": 2, "plugin_type": "TextPlugin", "parent_id": null, "data": {"body": "<p>The NanoVNA-F_V2 portable vector network analyzer is a new generation product developed on the basis of the NanoVNA-F. It features a 4.3-inch PS LCD display and an aluminum alloy casing, a 5000mAh large capacity lithium battery, and a battery life of up to 7 hours. It supports touch screen and side button operations, and supports both Chinese and English interfaces. This product has undergone deep software optimization based on the previous generation product NanoVNA-F, with a compatible operating interface and a measurement range extended to 4.4GHz. The dynamic range is larger, the measurement is more accurate, and the operation is more convenient.<br>\nThe hardware features of NanoVNA-F_V2 include but are not limited to the following improvements:<br>\n1. 4.3-inch IPS LCD display screen, resolution 800x480, ultra wide viewing angle, long-term use does not harm the eyes;<br>\n2. All aluminum alloy casing, sturdy and durable, effectively shields electromagnetic interference, ensuring measurement accuracy;<br>\n3. The body size is 125mm * 75mm * 20mm, compact and portable;<br>\n4. The RF interface is SMA, which facilitates the connection of various tested components;<br>\n5. 5000mAh high-capacity lithium battery, with a battery life of up to 7 hours;<br>\n6. Full touch screen design, with 3 side buttons for flexible and convenient operation;<br>\n7. Supports both Chinese and English interfaces;<br>\n8. Optimized UI design, convenient for users to perform measurement operations;<br>\n9. Support screen brightness adjustment;<br>\n10. Firmware can be upgraded through virtual USB flash drive without the need for a programmer, and can be upgraded through the included USB Type-C data cable;<br>\n11. Equipped with high-quality calibration components and RG405 stable phase cables as standard to ensure calibration accuracy;<br>\n12. Designed with a USB power output interface that supports 5V/1A power output;<br>\n13. Using 2A high current charging IC, the charging time is shorter;<br>\n14. Supporting upper computer software, the upper computer supports both Chinese and English interfaces;<br>\n15. The screen image of the device can be obtained by taking screenshots from the upper computer;</p>"}}], "order": [1566, 2378, 2408, 9262, 18311]}','en',1,1396,49);
