INSERT INTO djangocms_text_ckeditor_text VALUES('<p style="text-align: center;"><span style="color: #ffffff;">电子技术是欧洲美国等西方国家在十九世纪末、二十世纪初开始发展起来的新兴技术，最早由美国人莫尔斯1837年发明电报开始，1875年美国人亚历山大贝尔发明...</span></p>',178);
