INSERT INTO djangocms_text_ckeditor_text VALUES(replace('<p><span style="color: #999999;">欢迎来到微型射频设备Tiny RF Equip的网站，这里涵盖和介绍了很多微型，高效的射频微波测试设备，器件，以及相关射频模块。这些产品主要用来满足基本的无线产品测试需要，业余无线电测试爱好者以及学生学习的需求。这是一个自由开放的网站，希望能在这里可以和大家更专业，更快捷地交流射频的专业问题，这里的产品力争为客户获得最大的的经济投入产出比。</span></p>\n\n<p><span style="color: #999999;">同时本工作室工程师精通是德，罗德，安立的相关射频仪表，提供在线和现场培训咨询，更多信息请直接淘宝或者email联系。</span></p>\n\n<p><span style="color: #999999;"><strong>目前包含产品有：TinySA, TinySA Ultra, NanoVNA，NanoVNA-H2, NanoVNA-H4,  NanoVNA SAA2, LiteVNA, LibreVNA </strong></span></p>','\n',char(10)),3038);
