INSERT INTO djangocms_text_ckeditor_text VALUES(replace('<p>H-Field E-Field PROBE EMC EMI Near Field Probe Conducted Radiation Rectification Simple Magnetic Field Probe</p>\n\n<p>Operating frequency: 9K-3G;</p>\n\n<p>Size: 73mm X 24mm (excluding connectors)</p>\n\n<p>Weight: 3.4 g</p>\n\n<p>Connector: SMA Female Head</p>\n\n<p><a href="https://item.taobao.com/item.htm?id=777091447381&amp;pisk=g7Uoq6ACXuo7ZMBxDrg5jHCuGPjYw4gI3JLKp2HF0xkXyJ3-JEJqtXty8UozmXyLh61SyWk3K-Hby_MdNp23t7mUpvFJNowT_UURV2LnP2gFBOQOWbNSR2l-45TeNqlns37KUYkqPXCyFBXlW7NSRQvF6o79tEj1Tp-ELJuq0XlK83lezsmqTf0ezD8y0Kkj32lr8U7qgXGHYLyezKJqObcy8v8r3IlK3vuEUJPViXHqLbV6gYeUFrWXPVfhIj5pKjooQ7kDSSama3MP5A8eErlui1VonjhYobmoQDlaQXazHWz8PmsJV2NYjJqUdGKjrWrrzfF5rE0aaoUnMyCpxYPYoDUomL-rs4Dobzo2TFuqYo4myzWBfSFmUc0YDi6-v42ufAiPctw3iYeUrmJlHvETMzo0QtL0dDq_9X2lrUyN4q-2bRbwRj5LuHtI4jGmBG_jMsZYyfOlisxaf0ljaNCciHtI4jGmBsfDbsirGb7O.&amp;spm=a21xtw.29978516.0.0">Purchase link：H-FIELD E-FIELD PROBE EMC EMI Near field probe conducts radiation magnetic field electric field probe</a></p>\n\n<p>Price: Five per set, 60 RMB (excluding tax)</p>','\n',char(10)),10925);
INSERT INTO djangocms_text_ckeditor_text VALUES(replace('<p>This product set includes 4 H-Field probes, which are magnetic field probes. The main function of the magnetic field probes is to detect changes in voltage and radiation.</p>\n\n<p>One E-field, also known as an electric field probe, mainly detects changes in current and radiation.</p>\n\n<p>This product is widely used for EMC and EMI testing, and of course, it can also measure wireless signals near the emission source. The video shows monitoring the key signal of a Honda CRV.</p>\n\n<p>When using, do not touch the PCB board with your hands！！！</p>\n\n<p>Magnetic field probe 1-4</p>\n\n<p><cms-plugin alt="Picture / Image - Image (15501) " title="Picture / Image - Image (15501)" id="15501"></cms-plugin></p>\n\n<p><cms-plugin alt="Picture / Image - Image (15502) " title="Picture / Image - Image (15502)" id="15502"></cms-plugin></p>\n\n<p><cms-plugin alt="Picture / Image - Image (15503) " title="Picture / Image - Image (15503)" id="15503"></cms-plugin></p>\n\n<p><cms-plugin alt="Picture / Image - Image (15504) " title="Picture / Image - Image (15504)" id="15504"></cms-plugin></p>\n\n<p>Electric field probe</p>\n\n<p><cms-plugin alt="Picture / Image - Image (15505) " title="Picture / Image - Image (15505)" id="15505"></cms-plugin></p>','\n',char(10)),10931);
