INSERT INTO djangocms_text_ckeditor_text VALUES(replace('<p>Six types of antennas, capable of covering 430M to 6.4G</p>\n\n<p>Accept customized antennas for other frequency bands</p>\n\n<p><a href="https://item.taobao.com/item.htm?id=831909852616&amp;pisk=gJ8sqb97ZR2_Ru_YGGcFNgbIrVbfGXuyHS1vZIUaMNQOHS9pMleODOUd9_CfDroG7i_Xp98NQC7OhZOkFdWN0l-QGQvBhicG3tBX3IKZT4uysCbckEMrz47vRy19ClQADjBdgscF6zUib9_ckYkzYrIiPZv9XJ_TXkCdKs1YWipYJkCRpsUAMKBdv_CzBZpvHwddw1aAHGCYpX1Gi1FOklFLJs1P6opAkXsdM9BAkGpv9bA456l1KCGG0s0-G7DiIOUYke11vDROpTBsgsS6mC6IeNTd18XJ69aYkT6xOIAB_AakTNYDF_JZJP9WZevC9L3jdZvHDKCXp42VS3JMrM9Z2xRd5ssRkMNYkB_OCiC1y4eCtHdwDFv_GrCM7USfEMGYoi7pzgKJCSck9NCvngYqEPX9MQYk4agUXadBDLtf4kaPFrdgcWsul66rOXZ0msWuHCPi8J1AX6fE3XGQ4IjOt66rOXZ0mGChTClIOuRc.&amp;spm=a21xtw.29978516.0.0">Purchase link：multi band 433MHz/915MHz/2.4GHz/5.8GHz/RFID Antenna</a></p>','\n',char(10)),11177);
INSERT INTO djangocms_text_ckeditor_text VALUES(replace('<p>All antennas sold in our store have been personally selected and tested by the store owner to be suitable for the frequency band required by the customer, and relevant test lines have been provided. Antennas that meet S11 and VSWR performance requirements can be purchased with confidence. If you have any other needs, please contact customer service to provide professional technical knowledge answers.</p>\n\n<p> </p>\n\n<p><strong>Large round head rubber rod antenna</strong></p>\n\n<p><cms-plugin alt="Picture / Image - Image (16222) " title="Picture / Image - Image (16222)" id="16222"></cms-plugin><cms-plugin alt="Picture / Image - Image (16224) " title="Picture / Image - Image (16224)" id="16224"></cms-plugin><cms-plugin alt="Picture / Image - Image (16223) " title="Picture / Image - Image (16223)" id="16223"></cms-plugin></p>\n\n<p><strong>Short flat adhesive rod antenna</strong></p>\n\n<p><cms-plugin alt="Picture / Image - Image (16229) " title="Picture / Image - Image (16229)" id="16229"></cms-plugin><cms-plugin alt="Picture / Image - Image (16230) " title="Picture / Image - Image (16230)" id="16230"></cms-plugin><cms-plugin alt="Picture / Image - Image (16231) " title="Picture / Image - Image (16231)" id="16231"></cms-plugin></p>\n\n<p><strong>915 small folding antenna</strong></p>\n\n<p><cms-plugin alt="Picture / Image - Image (16255) " title="Picture / Image - Image (16255)" id="16255"></cms-plugin><cms-plugin alt="Picture / Image - Image (16256) " title="Picture / Image - Image (16256)" id="16256"></cms-plugin><cms-plugin alt="Picture / Image - Image (16257) " title="Picture / Image - Image (16257)" id="16257"></cms-plugin></p>\n\n<p><strong>Knife shaped rubber stick antenna</strong></p>\n\n<p><cms-plugin alt="Picture / Image - Image (16284) " title="Picture / Image - Image (16284)" id="16284"></cms-plugin><cms-plugin alt="Picture / Image - Image (16285) " title="Picture / Image - Image (16285)" id="16285"></cms-plugin><cms-plugin alt="Picture / Image - Image (16286) " title="Picture / Image - Image (16286)" id="16286"></cms-plugin></p>\n\n<p><strong>433 small folding antenna</strong></p>\n\n<p><cms-plugin alt="Picture / Image - Image (16287) " title="Picture / Image - Image (16287)" id="16287"></cms-plugin><cms-plugin alt="Picture / Image - Image (16288) " title="Picture / Image - Image (16288)" id="16288"></cms-plugin><cms-plugin alt="Picture / Image - Image (16289) " title="Picture / Image - Image (16289)" id="16289"></cms-plugin></p>\n\n<p><strong>Hexagonal adhesive rod antenna</strong></p>\n\n<p> </p>','\n',char(10)),11183);
