INSERT INTO djangocms_text_ckeditor_text VALUES(replace('<p>Cables are selected with good performance after screening and testing, and can be purchased with confidence.</p>\n\n<p>If you have any other needs, please contact customer service to provide you with professional technical knowledge answers.</p>\n\n<p> </p>\n\n<p><cms-plugin alt="Picture / Image - Image (16193) " title="Picture / Image - Image (16193)" id="16193"></cms-plugin>     <cms-plugin alt="Picture / Image - Image (16194) " title="Picture / Image - Image (16194)" id="16194"></cms-plugin></p>\n\n<p><cms-plugin alt="Picture / Image - Image (16195) " title="Picture / Image - Image (16195)" id="16195"></cms-plugin>    <cms-plugin alt="Picture / Image - Image (16196) " title="Picture / Image - Image (16196)" id="16196"></cms-plugin>    <cms-plugin alt="Picture / Image - Image (16197) " title="Picture / Image - Image (16197)" id="16197"></cms-plugin>    <cms-plugin alt="Picture / Image - Image (16198) " title="Picture / Image - Image (16198)" id="16198"></cms-plugin></p>','\n',char(10)),13038);
