INSERT INTO djangocms_text_ckeditor_text VALUES(replace('<p>The RF attenuators sold in our store all have good 50ohm characteristic impedance, and the attenuation values have been tested by grid division, and the power meets the requirements.</p>\n\n<p>You can go to Bilibili TinyRFeqip to watch my videos.</p>\n\n<p>For more questions, usage methods, and examples, please visit the website <br>\nFor RF related issues, please contact the TaoBao store owner directly. The store owner will do their best to consult and learn from each other.</p>\n\n<p>This link is for all attenuators used for Tiny RF equity series spectrometers, network dividers, and signal sources. They must be purchased together with the instrument for free shipping.</p>\n\n<p>The profit is meager, but the quality is guaranteed. Please feel free to use it. If you don''t understand, you can consult the shop owner.</p>\n\n<p><cms-plugin alt="Picture / Image - Image (16179) " title="Picture / Image - Image (16179)" id="16179"></cms-plugin>    <cms-plugin alt="Picture / Image - Image (16180) " title="Picture / Image - Image (16180)" id="16180"></cms-plugin></p>\n\n<p><cms-plugin alt="Picture / Image - Image (16181) " title="Picture / Image - Image (16181)" id="16181"></cms-plugin>    <cms-plugin alt="Picture / Image - Image (16182) " title="Picture / Image - Image (16182)" id="16182"></cms-plugin></p>\n\n<p><cms-plugin alt="Picture / Image - Image (16183) " title="Picture / Image - Image (16183)" id="16183"></cms-plugin>    <cms-plugin alt="Picture / Image - Image (16184) " title="Picture / Image - Image (16184)" id="16184"></cms-plugin></p>\n\n<p><cms-plugin alt="Picture / Image - Image (16185) " title="Picture / Image - Image (16185)" id="16185"></cms-plugin>    <cms-plugin alt="Picture / Image - Image (16186) " title="Picture / Image - Image (16186)" id="16186"></cms-plugin></p>\n\n<p><cms-plugin alt="Picture / Image - Image (16187) " title="Picture / Image - Image (16187)" id="16187"></cms-plugin>    <cms-plugin alt="Picture / Image - Image (16188) " title="Picture / Image - Image (16188)" id="16188"></cms-plugin></p>\n\n<p><cms-plugin alt="Picture / Image - Image (16189) " title="Picture / Image - Image (16189)" id="16189"></cms-plugin>    <cms-plugin alt="Picture / Image - Image (16190) " title="Picture / Image - Image (16190)" id="16190"></cms-plugin></p>','\n',char(10)),16178);
INSERT INTO djangocms_text_ckeditor_text VALUES('<p><a href="https://item.taobao.com/item.htm?id=835054701215&amp;pisk=g5RE49cLdXhEnjsdKC1z3ZHeBzCdH_ofZQs5rUYlRMjhAQtyrZ_ArWbhqlfGbE0dAYHp4d-kX9snvvQuanxOPyTkNaAP9C9QNMidaUxfamijGjTpJsCocm6B-KUG9a7uK7q5j1bPawq098SwJ_CocPNohj8pvilwXJblSV75PWbkqw2gjGQ7KgxlxOqGuZClZ3XHSlbCogbhrW0aSabVqJjutFfGzayhZ_xls1jOr_bHq_ck-IA8ba6nPD1GTblLObIW-GPuZBcRLiyf7NQW_hXhmO4ga7uR89SD-Gonzk-1IUBywzFPHevv2Zx3xm6prd-N8_l_KsYwEn79tjZFWpTM2GXLz7-VT3WDtOzuaF5wK17Mi4wAfCSBqBWilSW5sI6ctdMtAT1Fu3ApYzPkmFTX9Odr0ljJdZCGlehU_sYhrgS02NAoQQpUq8WhWNSj7VlaJS-JJL3vx8eRp2QNc2X3e8BhWNSj7Vy8e9KR7ighK&amp;skuId=5652850560505&amp;spm=a21xtw.29978516.0.0">Purchase link：RF adapter cable  IPEX SMA RF EMC N</a></p>',16207);
INSERT INTO djangocms_text_ckeditor_text VALUES(replace('<p>Cables are selected with good performance after screening and testing, and can be purchased with confidence.</p>\n\n<p>If you have any other needs, please contact customer service to provide you with professional technical knowledge answers.</p>\n\n<p> </p>\n\n<p><cms-plugin alt="Picture / Image - Image (16214) " title="Picture / Image - Image (16214)" id="16214"></cms-plugin>     <cms-plugin alt="Picture / Image - Image (16215) " title="Picture / Image - Image (16215)" id="16215"></cms-plugin></p>\n\n<p><cms-plugin alt="Picture / Image - Image (16216) " title="Picture / Image - Image (16216)" id="16216"></cms-plugin>    <cms-plugin alt="Picture / Image - Image (16217) " title="Picture / Image - Image (16217)" id="16217"></cms-plugin>    <cms-plugin alt="Picture / Image - Image (16218) " title="Picture / Image - Image (16218)" id="16218"></cms-plugin>    <cms-plugin alt="Picture / Image - Image (16219) " title="Picture / Image - Image (16219)" id="16219"></cms-plugin></p>','\n',char(10)),16213);
INSERT INTO djangocms_text_ckeditor_text VALUES('<p><strong> TinySA Ultra TinySA Ultra TinySA Ultra TinySA Ultra TinySA Ultra TinySA Ultra TinySA Ultra TinySA Ultra</strong></p>',16584);
INSERT INTO djangocms_text_ckeditor_text VALUES(replace('<p><strong>TinySA是一种小型频谱分析仪和信号发生器，具有一些不错的功能：</strong></p>\n\n<ul>\n	<li><strong>TinySA基本特点:</strong>\n\n	<ul>\n		<li>屏幕尺寸 2.8英寸</li>\n		<li>带两个输入端口的频谱分析仪，Low端口用于 10KHz-350MHz 的高质量 MF/HF/VHF 输入，High端口用于 240MHz-960MHz 的 UHF 输入。</li>\n		<li>信号发生器具有两个输出，正弦波输出为100KHz - 350MHz，方波输出为 240MHz-960MHz，信号发生器和频谱分析仪同一时刻只能选择其中的一个功能。</li>\n		<li>彩色显示屏显示最多 290个扫描点，提供长达整个低频或高频范围的无间隙覆盖。</li>\n	</ul>\n	</li>\n	<li><strong>TinySA</strong> <strong>Ultra基本特点:</strong>\n	<ul>\n		<li>屏幕尺寸 4英寸</li>\n		<li>频谱分析仪模式，初始状态为10KHz-800MHz，在启用独特的Ultra模式的情况下，可以监测高达12GHz的信号。</li>\n		<li>信号发生器模式，正弦波输出在100KHz-800MHz之间，射频测试信号的方波输出高达5.3GHz。</li>\n		<li>200Hz至850KHz的RBW设置提供更高的灵敏度范围。</li>\n		<li>内置 20dB 可选 LNA</li>\n		<li>彩色显示屏显示最大 450 个点，提供长达整个频率范围的无间隙覆盖。</li>\n		<li>MicroSD卡插槽，用于存储测量值，设置和屏幕截图。</li>\n	</ul>\n	</li>\n	<li>输入步进衰减器从0dB到31dB（不能与LNA结合使用）。</li>\n	<li>内置校准信号发生器，用于自动自检和（低）输入校准。</li>\n	<li>通过USB连接到PC，它成为PC控制的频谱分析仪或信号发生器</li>\n	<li>高达3000mah的可充电电池，可携带至少2小时。</li>\n	<li>最大输入电平 +6dBm。</li>\n	<li>信号发生器功能不能用作跟踪发生器，因为您不能同时使用频谱分析仪和信号发生器功能。</li>\n	<li>由于低成本和非常小的外形尺寸，存在某些相关的微小SA限制和微小SA超限制。</li>\n</ul>\n\n<figure><img alt="" src="https://tinysa.org/wiki/uploads/Main/tinySA_housing.jpg"></figure>\n\n<figure><img alt="" src="https://tinysa.org/wiki/uploads/Main/tinySA_ultra.jpg"></figure>\n\n<p><strong>视频教学：</strong></p>\n\n<p>可以在B站也就是哔哩哔哩_bilibili网站搜索TinyRFEquip账号找到介绍TinySA和TinySA Ultra以及其他TinyRFEquip仪器的主要功能介绍视频。例如：</p>\n\n<p><a href="https://www.bilibili.com/video/BV1yt421u7Y2/?vd_source=8d60a323bdde2d574cb0a85c07cb3212">TinySA Ultra对于无线话筒的频率特性检定测量_哔哩哔哩_bilibili</a></p>\n\n<p>https://www.bilibili.com/video/BV1yt421u7Y2/?vd_source=8d60a323bdde2d574cb0a85c07cb3212</p>\n\n<p><strong>法律内容</strong></p>\n\n<p>TinySA和TinySA Ultra的名称以及TinySA徽标是我们拥有的注册商标。未经书面许可，不允许其他人使用TinySA这个名字 或 TinySA Ultra 用于任何频谱分析仪产品。</p>','\n',char(10)),16590);
