INSERT INTO djangocms_text_ckeditor_text VALUES(replace('<p>Six types of antennas, capable of covering 430M to 6.4G</p>\n\n<p>Accept customized antennas for other frequency bands</p>\n\n<p><a href="https://item.taobao.com/item.htm?id=831909852616&amp;pisk=gJ8sqb97ZR2_Ru_YGGcFNgbIrVbfGXuyHS1vZIUaMNQOHS9pMleODOUd9_CfDroG7i_Xp98NQC7OhZOkFdWN0l-QGQvBhicG3tBX3IKZT4uysCbckEMrz47vRy19ClQADjBdgscF6zUib9_ckYkzYrIiPZv9XJ_TXkCdKs1YWipYJkCRpsUAMKBdv_CzBZpvHwddw1aAHGCYpX1Gi1FOklFLJs1P6opAkXsdM9BAkGpv9bA456l1KCGG0s0-G7DiIOUYke11vDROpTBsgsS6mC6IeNTd18XJ69aYkT6xOIAB_AakTNYDF_JZJP9WZevC9L3jdZvHDKCXp42VS3JMrM9Z2xRd5ssRkMNYkB_OCiC1y4eCtHdwDFv_GrCM7USfEMGYoi7pzgKJCSck9NCvngYqEPX9MQYk4agUXadBDLtf4kaPFrdgcWsul66rOXZ0msWuHCPi8J1AX6fE3XGQ4IjOt66rOXZ0mGChTClIOuRc.&amp;spm=a21xtw.29978516.0.0">Purchase link：multi band 433MHz/915MHz/2.4GHz/5.8GHz/RFID Antenna</a></p>','\n',char(10)),17648);
INSERT INTO djangocms_text_ckeditor_text VALUES(replace('<p>All antennas sold in our store have been personally selected and tested by the store owner to be suitable for the frequency band required by the customer, and relevant test lines have been provided. Antennas that meet S11 and VSWR performance requirements can be purchased with confidence. If you have any other needs, please contact customer service to provide professional technical knowledge answers.</p>\n\n<p> </p>\n\n<p><strong>Large round head rubber rod antenna</strong></p>\n\n<p><cms-plugin alt="Picture / Image - Image (17655) " title="Picture / Image - Image (17655)" id="17655"></cms-plugin><cms-plugin alt="Picture / Image - Image (17657) " title="Picture / Image - Image (17657)" id="17657"></cms-plugin><cms-plugin alt="Picture / Image - Image (17656) " title="Picture / Image - Image (17656)" id="17656"></cms-plugin></p>\n\n<p><strong>Short flat adhesive rod antenna</strong></p>\n\n<p><cms-plugin alt="Picture / Image - Image (17658) " title="Picture / Image - Image (17658)" id="17658"></cms-plugin><cms-plugin alt="Picture / Image - Image (17659) " title="Picture / Image - Image (17659)" id="17659"></cms-plugin><cms-plugin alt="Picture / Image - Image (17660) " title="Picture / Image - Image (17660)" id="17660"></cms-plugin></p>\n\n<p><strong>915 small folding antenna</strong></p>\n\n<p><cms-plugin alt="Picture / Image - Image (17661) " title="Picture / Image - Image (17661)" id="17661"></cms-plugin><cms-plugin alt="Picture / Image - Image (17662) " title="Picture / Image - Image (17662)" id="17662"></cms-plugin><cms-plugin alt="Picture / Image - Image (17663) " title="Picture / Image - Image (17663)" id="17663"></cms-plugin></p>\n\n<p><strong>Knife shaped rubber stick antenna</strong></p>\n\n<p><cms-plugin alt="Picture / Image - Image (17664) " title="Picture / Image - Image (17664)" id="17664"></cms-plugin><cms-plugin alt="Picture / Image - Image (17665) " title="Picture / Image - Image (17665)" id="17665"></cms-plugin><cms-plugin alt="Picture / Image - Image (17666) " title="Picture / Image - Image (17666)" id="17666"></cms-plugin></p>\n\n<p><strong>433 small folding antenna</strong></p>\n\n<p><cms-plugin alt="Picture / Image - Image (17667) " title="Picture / Image - Image (17667)" id="17667"></cms-plugin><cms-plugin alt="Picture / Image - Image (17668) " title="Picture / Image - Image (17668)" id="17668"></cms-plugin><cms-plugin alt="Picture / Image - Image (17669) " title="Picture / Image - Image (17669)" id="17669"></cms-plugin></p>\n\n<p><strong>Hexagonal adhesive rod antenna</strong></p>\n\n<p> </p>','\n',char(10)),17654);
INSERT INTO djangocms_text_ckeditor_text VALUES(replace('<p>TinyRFSG: </p>\n\n<p>1.Basic introduction of signal source and display of the whole family bucket: </p>\n\n<p><a href="https://www.youtube.com/watch?v=7wull02SPAY">Debut!! high precision and power, ultra portable programmable RF signal generator TinyRFSG</a></p>','\n',char(10)),17690);
INSERT INTO djangocms_text_ckeditor_text VALUES(replace('<p>Here are all the documents you need about the device, including user manuals, programming guides, etc. If you have any other questions or interests, please send me a private message and I will answer them for you.</p>\n\n<p><cms-plugin alt="File - TinySA and Ultra_UserManualAndProgrammingGuide_V1.6.pdf " title="File - TinySA and Ultra_UserManualAndProgrammingGuide_V1.6.pdf" id="18279"></cms-plugin></p>\n\n<p> </p>\n\n<p><cms-plugin alt="File - NanoVNA-F V2_UserManualAndProgrammingGuide.pdf " title="File - NanoVNA-F V2_UserManualAndProgrammingGuide.pdf" id="18280"></cms-plugin></p>\n\n<p> </p>\n\n<p><cms-plugin alt="File - NanoVNA-F V3_UserManualAndProgrammingGuide.pdf " title="File - NanoVNA-F V3_UserManualAndProgrammingGuide.pdf" id="18281"></cms-plugin></p>\n\n<p> </p>\n\n<p><cms-plugin alt="File - LiteVNA_User-Guide.pdf " title="File - LiteVNA_User-Guide.pdf" id="18282"></cms-plugin></p>','\n',char(10)),17696);
INSERT INTO djangocms_text_ckeditor_text VALUES(replace('<p>Portable TinySA Spectrum Analyzer, Upgraded V0.3.1 Handheld Tiny Frequency Analyzer 100kHz to 960MHz MF/HF/VHF UHF Input, 2.8 inch Touch Screen with ESD Protect Function</p>\n\n<p>Product details</p>\n\n<ul>\n	<li>Package Dimensions ‏ : ‎ 10.35 x 7.6 x 1.3 inches; 2.2 Pounds</li>\n	<li>Batteries ‏ : ‎ 1pcs of  500mah Lithium Ion batteries required. (included)</li>\n	<li><a href="https://item.taobao.com/item.htm?id=731987933177&amp;pisk=gGoS44G1I_fW1dqddzv4CPqXj3qIdK-Z99wKIvIPpuE899GxpaC8J7IYHReQJM8u4yZIMSozaYr8OkMi1bPz8aufdAcjOyvuTWFITv3y3h-ZEYq3vDOwbhrKciw-O8ULvrpLIRPp3zIOgUPLvCRwbZWYrQrKT43ypnQYISe8p7Uphie_IkeRv7pbMJwGJ_hK9KZYKRXRvkURksF0IgeRyMCvDJe3e_I-9xpbLJrL9XUJhxh86gw2FSDWEyyHXp9dXxNfvMnbHBVtFZSTEmyWf5M7GCCmcG476YFfvQ39lmPQicd2lxcnybymOhObxj0K9JGAMBzopqGbFbR1tWooUDwmFOSihyNSk0UfpMHYVSGsRbO5r73rGP2Yk9tg3fPxE03XKsH-_7Z8Hr-9CxUKu04i4II7XVDz42hH7ZqSp4Ef43sa1MHlRtaGA-NwhK_h-JPG9YWk0swLy-22TK9f7v48n-NwhK_h-ze03YJXhNkh.&amp;spm=a21xtw.29978516.0.0">Purchase link：TinySA Handheld Spectrum Analyzer 10K-960MHz RF EMC  Lora</a></li>\n</ul>\n\n<p>Price: 285 RMB (excluding tax)</p>','\n',char(10)),17801);
INSERT INTO djangocms_text_ckeditor_text VALUES(replace('<ul>\n	<li>Frequency Range :Tiny Spectrum Analyzer with two inputs, high quality MF/HF/VHF input for 0.1MHZ-350MHz, lesser quality UHF input for 240MHz-960MHz. Switchable resolution bandpass filters for both ranges between 3kHz and 640kHz. Color display showing 290 scan points covering up to the full low or high frequency rangefrequency range. The tinySA contains all the components of a conventional heterodyne swept spectrum analyzer</li>\n	<li>Built-in Calibration Signal Generator:When not used as Spectrum Analyzer it can be used as Signal Generator, MF/HF/VHF sinus output between 0.1MHZ-350MHz, UHF square wave output between 240MHz-960MHz. Built-in calibration signal generator that is used for automatic self test and low input calibration. But the SG function is not careful calibration, so the output level is not very accurate, just as a reference.</li>\n	<li>Tiny Spectrum analyzers &amp; ESD Function: Switchable resolution bandpass filters for both ranges between 3kHz and 640kHz.Color display showing 290 scan points covering up to the full low or high frequency range. Bulit-in rechargeable battery allowing a minimum of at least 2 hours portable use.With a new ESD protrcted function enable the product to have a higher antistatic level and a longer service life</li>\n	<li>PC Control: Connected to a PC via USB it becomes a PC controlled Spectrum Analyzer.The USB interface implements the Serial over USB (CDC) protocol and there is a large set of commands that can be invoked over the serial interface. These command can be used to perform measurements or update internal settings. The driver for Windows will install automatically after connecting to a Windows PC. The driver for Linux is built into the kernel</li>\n	<li>Package List: 1x Tiny Spectrum Analyzer; 2 x 20cm RF Cable;1 x USB Cable;1 x SMA Female to Female Connector;1x Touchscreen Pen;1 x SMA Telescopic Antenna.It''s very useful as an antenna analyzer for your ham station, easy to set without fancy calibration.The firmware of the tinySA can be updated by the user. New versions of the firmware needed please contact seller for download link</li>\n	<li><cms-plugin alt="Picture / Image - Image (17808) " title="Picture / Image - Image (17808)" id="17808"></cms-plugin></li>\n	<li><cms-plugin alt="Picture / Image - Image (17809) " title="Picture / Image - Image (17809)" id="17809"></cms-plugin></li>\n	<li><cms-plugin alt="Picture / Image - Image (17810) " title="Picture / Image - Image (17810)" id="17810"></cms-plugin></li>\n	<li> </li>\n</ul>','\n',char(10)),17807);
INSERT INTO djangocms_text_ckeditor_text VALUES(replace('<ul>\n	<li>Tinysa ULTRA+ ZS406 owns high performance frequency in 100khz to 900MHz, and when in ultra mode, the analyzer can reach 5.4GHz. With new 4'''' touchscreen display and installed with the latest hardware system V0.4.6. Built-in 32Gb micro TF card for data transfer and storage</li>\n	<li>[Frequency Range] Tinysa ultra measures from 100KHz-5.4GHz: Spectrum Analyzer for 0.1MHz-900MHz, with Ultra mode enabled, level calibrated up to 6GHz, can observe signals up to 12GHz. RBW from 200Hz-850kHz, you can fast and accurate execute measurement tests. Color display showing max 450 points providing gapless covering up to the full frequency range</li>\n	<li><a href="https://item.taobao.com/item.htm?id=849801646126&amp;pisk=gX4tqf4J49XM3Satt5SHm0DDW8C3BMVN9RPWoxDMcJeLGRMinfTsAvGoNdG_Gx0YH-exIm6ZSreLh-L0jP0icZMLCEmgkS8xGSwV_xfNx5PZuq6lETbu_5Pmp0JbWFGIOWl2cdsnfQ9nXxWlEablfBgABT2c67FGRbhSlfijCD1KZbvslmgXO6hjidtX5-1d9jcXCCMjl2tINv9XlhTbO2G-NnGscj1LOvlxhqgbh21Kgbcfvx-sEEEPYctfdgRKPqaK6cH79g8XkOGeExN6YELbJkUIFaDplEaK6ShpA5YRmYZrI0D0dwYtkWGYIv25Pe3I2uPmMRQ95VqQYPug-TpmX2ksVoid1NNKWAn85cQACVEbQrnaXI5zOVwU4Yo1Y9lLSzmxUDpCCWVKC0EYI98jIuFQp04HKU04LowjMJ9O43zuykmBEYhDf6Cp0nosT0l3hX6Trmvj9Yfnsn-qvMlKE6Cp0nosTXHltKx20DIF.&amp;skuId=5757350816604&amp;spm=a21xtw.29978516.0.0">Purchase link:TinySA ULTRA Spectrum Analyzer 10K-12GHz Bluetooth Ham RF</a></li>\n</ul>\n\n<p>Price: 752 RMB (excluding tax)</p>','\n',char(10)),17821);
INSERT INTO djangocms_text_ckeditor_text VALUES(replace('<ul>\n	<li id="bundle-v2-btf-component-bullet-point-1-2">[Upgraded TinySA Ultra ZS406] TinySA Ultra owns high performance frequency in 100khz to 900MHz, and when in ultra mode, the analyzer can reach 5.4GHz. With new 4'''' touchscreen display and installed with the latest hardware system V0.4.6. Built-in 32Gb micro TF card for data transfer and storage</li>\n	<li id="bundle-v2-btf-component-bullet-point-1-3">[Frequency Range] Tiny sa ultra measures from 100KHz-5.4GHz: Spectrum Analyzer for 0.1MHz-900MHz, with Ultra mode enabled, level calibrated up to 6GHz, can observe signals up to 12GHz. RBW can be set from 200Hz-850kHz, you can fast and accurate execute measurement tests. Color display showing max 450 points providing gapless covering up to the full frequency range</li>\n	<li id="bundle-v2-btf-component-bullet-point-1-4">[2 in 1 Device] When not used as Spectrum Analyzer it can be used as Signal Generator, MF/HF/VHF sinus output between 100kHZ-900MHz, UHF square wave output between 800mHz-4.4GHz, Mixing signal output is between 4.4GHz-5.4GHz. Built-in calibration signal generator that is used for automatic self test and level calibration</li>\n	<li id="bundle-v2-btf-component-bullet-point-1-5">[PC Operation] Connected to a PC via USB. The USB interface implements CDC protocol and there is a large set of commands that can be invoked over the serial interface. These command can be used to perform MEAS or update internal settings. Tinysa-APP transfers data directly to the computer. The driver for Windows will install automatically after connecting to a Windows10 or Win11 PC. The driver for Linux is built into the kernel</li>\n	<li id="bundle-v2-btf-component-bullet-point-1-6">[200Hz-850kHz RBW] RBW frequency from 200hz to 850khz which can be set to match the measurement requirements, meet SBB two-tone test requirements and fast scanning. The RBW is as low as 200Hz, which can effectively distinguish adjacent signals and meet the requirements of SSB dual-satellite inter-modulation test. Input Step attenuator from 0dB to 31dB (can not be used not in combination with LNA)</li>\n	<li id="bundle-v2-btf-component-bullet-point-1-7">[What You Get] 1x Tinysa ULTRA (4inch touchscreen, 5000mah rechargeable battery); 2x 30cm ALSR100 SMA cables; 1 x USB Type-C data cable; 1x SMA-SMA barrel connector; 1x TLanyard and touch plectrum; 1x Antenna with SMA connector; 1x 32GB MicroSD card(plugged in the host), 1x Stylus Pen</li>\n</ul>\n\n<figure> </figure>\n\n<figure>\n<p><img alt="" src="https://tinysa.org/wiki/uploads/Main/tinySA_ultra.jpg"></p>\n\n<p><cms-plugin alt="Picture / Image - Image (17830) " title="Picture / Image - Image (17830)" id="17830"></cms-plugin></p>\n\n<p>Using TinySA to test satellite RF module for transmission. </p>\n\n<p><cms-plugin alt="Picture / Image - Image (17828) " title="Picture / Image - Image (17828)" id="17828"></cms-plugin></p>\n\n<p><cms-plugin alt="Picture / Image - Image (17829) " title="Picture / Image - Image (17829)" id="17829"></cms-plugin></p>\n</figure>\n\n<p><cms-plugin alt="Picture / Image - Image (17831) " title="Picture / Image - Image (17831)" id="17831"></cms-plugin></p>','\n',char(10)),17827);
INSERT INTO djangocms_text_ckeditor_text VALUES(replace('<ul>\n	<li>\n	<p id="title">Tinysa Ultra+ ZS407 spectrum analyzer: With ultra-wide frequency range of 100kHz-7.3GHz, enabling you to capture and analyze a broader spectrum of signals precisely. With 4” IPS-TFT LCD (480×320) display can show a maximum of 450 points per scan, clearly presenting signal details and measurement results. Supports PC control, enabling easy data transfer and analysis</p>\n	</li>\n	<li>Ultra-Wide Frequency Range: The TinySA Ultra+ ZS407 Spectrum Analyzer covers a frequency range of 0.1 - 900MHz, with Ultra mode enabled up to 7.3 GHz, level calibrated up to 7.3GHz. Can observe signals up to 12GHz, which represents a significant improvement over previous models. It can accurately capture and analyze a broader range of signals, making it suitable for a variety of complex RF testing scenarios</li>\n	<li>Signal Generation Capability: ZS407 have the SG function, but the SG function is not calibrated and the max output power is -18.5dbm, sine wave output between 0.1 MHz and 900 MHz, square wave output up to 6.3 GHz, or RF test signal output up to 7.3 GHz. It has a rich variety of signal generation types and a wide frequency range</li>\n	<li><a href="https://item.taobao.com/item.htm?id=849801646126&amp;pisk=gX4tqf4J49XM3Satt5SHm0DDW8C3BMVN9RPWoxDMcJeLGRMinfTsAvGoNdG_Gx0YH-exIm6ZSreLh-L0jP0icZMLCEmgkS8xGSwV_xfNx5PZuq6lETbu_5Pmp0JbWFGIOWl2cdsnfQ9nXxWlEablfBgABT2c67FGRbhSlfijCD1KZbvslmgXO6hjidtX5-1d9jcXCCMjl2tINv9XlhTbO2G-NnGscj1LOvlxhqgbh21Kgbcfvx-sEEEPYctfdgRKPqaK6cH79g8XkOGeExN6YELbJkUIFaDplEaK6ShpA5YRmYZrI0D0dwYtkWGYIv25Pe3I2uPmMRQ95VqQYPug-TpmX2ksVoid1NNKWAn85cQACVEbQrnaXI5zOVwU4Yo1Y9lLSzmxUDpCCWVKC0EYI98jIuFQp04HKU04LowjMJ9O43zuykmBEYhDf6Cp0nosT0l3hX6Trmvj9Yfnsn-qvMlKE6Cp0nosTXHltKx20DIF.&amp;skuId=5757350816604&amp;spm=a21xtw.29978516.0.0">Purchase link：TinySA ULTRA Spectrum Analyzer 10K-12GHz Bluetooth Ham RF</a></li>\n</ul>\n\n<p>Price: 995 RMB (excluding tax)</p>','\n',char(10)),17842);
INSERT INTO djangocms_text_ckeditor_text VALUES(replace('<ul>\n	<li id="bundle-v2-btf-component-bullet-point-1-1">ZS407 spectrum analyzer: With ultra-wide frequency range of 100kHz-7.3GHz, enabling you to capture and analyze a broader spectrum of signals precisely. With 4” IPS-TFT LCD (480×320) display can show a maximum of 450 points per scan, clearly presenting signal details and measurement results. Supports PC control, enabling easy data transfer and analysis</li>\n	<li id="bundle-v2-btf-component-bullet-point-1-4">Long-Lasting Battery: Equipped with a Li-polymer 3.7V 5000mAh battery, the battery life is significantly increased compared to previous models. It can meet the needs of continuous testing for a long time or outdoor operations, reducing the inconvenience of frequent charging and improving work efficiency. Built-in 32GB micro SD card, solving the on-site data storage issue, convenient for data sharing and storage</li>\n	<li id="bundle-v2-btf-component-bullet-point-1-5">High-Gain Low-Noise Amplifier (LNA): The internal LNA gain can reach 20dB up to 7.3GHz, effectively enhancing the reception ability of weak signals. At the same time, at 100MHz, the DANL is as low as -169dBm/Hz when the LNA is on, reducing noise interference and improving the accuracy of signal measurement</li>\n	<li id="bundle-v2-btf-component-bullet-point-1-6">Excellent Phase Noise Performance: The phase noise is -100dBc/Hz at a 10kHz offset and -103dBc/Hz at a 100kHz offset. The low phase noise indicates high signal purity, enabling more accurate analysis of signal frequency stability and spectral purity. It is crucial for high-precision RF measurement and communication system performance evaluation</li>\n	<li id="bundle-v2-btf-component-bullet-point-1-7">Paking List: 1x Tinysa ULTRA+ ZS407 Spectrum Analyzer (built-in 5000mah rechargeable battery); 1x 32GB Micro SD card (plugged in the host); 2x 30cm ALSR100 SMA cables; 1 x USB Type-C data cable; 1x SMA-SMA barrel connector; 1x TLanyard and touch plectrum; 1x Antenna with SMA connector; 1x stylus pen</li>\n</ul>\n\n<figure> </figure>\n\n<figure>\n<p><img alt="" src="https://tinysa.org/wiki/uploads/Main/tinySA_ultra.jpg"></p>\n\n<p>Using TinySA to test satellite RF module for transmission. </p>\n\n<p><cms-plugin alt="Picture / Image - Image (17849) " title="Picture / Image - Image (17849)" id="17849"></cms-plugin></p>\n\n<p><cms-plugin alt="Picture / Image - Image (17850) " title="Picture / Image - Image (17850)" id="17850"></cms-plugin></p>\n</figure>\n\n<p> </p>','\n',char(10)),17848);
INSERT INTO djangocms_text_ckeditor_text VALUES(replace('<p>LibreVNA 2025 is a 100kHz-6GHz Vector Network Analyzer USB Based Full 2-Port with External Reference Input/Output,6-Layer PCB Design Measure Full S-Parameters. Special design with 6mm fins installed on the top side and 4 positioning holes are installed on the bottom side, so customers can install larger heat sinks or feet (M3*6 nuts) for easy use. The 2025 version also replaces the original brass SMA with a four-hole flange stainless steel SMA with more torque, both SMA fittings that can support up to 18G.</p>\n\n<p>You can buy from <cms-plugin alt="Link / Button - Link (17886) " title="Link / Button - Link (17886)" id="17886"></cms-plugin></p>\n\n<p>You can learn by video from<cms-plugin alt="Link / Button - Link (17887) " title="Link / Button - Link (17887)" id="17887"></cms-plugin></p>\n\n<p>Price: 3450 RMB (excluding tax)<cms-plugin alt="Link / Button - Link (17885) " title="Link / Button - Link (17885)" id="17885"></cms-plugin></p>','\n',char(10)),17884);
INSERT INTO djangocms_text_ckeditor_text VALUES(replace('<ul>\n	<li>LibreVNA 2025 is a 100kHz-6GHz Vector Network Analyzer. Special design with 6mm fins installed on the top side and 4 positioning holes are installed on the bottom side, so customers can install larger heat sinks or feet (M3*6 nuts) for easy use. The 2025 version also replaces the original brass SMA with a four-hole flange stainless steel SMA with more torque, both SMA fittings that can support up to 18G.</li>\n	<li id="bundle-v2-btf-component-bullet-point-2-1">[Upgraded Professional LibreVNA] LibreVNA is a open-source hardware, USB based full 2-port vector network analyzer (VNA) designed by Jankae, provides a 100kHz to 6GHz ultra-wide frequency range. Updated 6-layer PCB design that optimizes S12 port isolation and high-frequency port matching. Supports firmware update and can load a new microcontroller firmware and FPGA configuration into the LibreVNA</li>\n	<li id="bundle-v2-btf-component-bullet-point-2-2">[Comparable to Lab-grade Nano VNA] The ultra-low noise power supply design and the use of 16bit ADC, together with the precision CNC''s aluminum shielded housing, achieve up to 100dB of effective dynamics. Using 3 ADCs to sample data simultaneously and using FPGAs for signal processing, Libre VNA handheld antenna Analyzer is capable of scanning over 10,000 points of full dual-port measurements in less than 1 second</li>\n	<li id="bundle-v2-btf-component-bullet-point-2-3">[Frequency range] Supports a wide range of frequency measurements from 100kHz to 6GHz, upgraded Frequency Accuracy is &lt;2ppm. The S12 can achieve over 90dB of port isolation below 3GHz, allowing measurements above 6GHz use harmonics. During up to 9GHz actual tests, both S11 and S22 have more than 10dB port directivity, and S12, S21 have more than 40dB dynamics</li>\n	<li id="bundle-v2-btf-component-bullet-point-2-4">[Full S-Parameters Measurements] In the LibreVNA operating mode, the VNA can measure the complete S11, S21, S12 and S21 parameters. A source signal is generated and alternately applied to the RF ports. This incoming signal at both RF ports is measured, resulting in the four S-parameters S11 and S21(when signal routes to Port 1), as well as S12 and S22(when signal routes to Port 2)</li>\n	<li id="bundle-v2-btf-component-bullet-point-2-5">[3 In 1 Device] Although the VNA hardware is not designed to be used as spectrum analyzer and signal generator, the general hardware architecture of a spectrum analyzer and signal generator are similar enough to that of a VNA to implement basic spectrum measurements and output a CW signal, which might suffice if no other equipment is available. The main differences to a real spectrum analyzer and signal generator please refer to the product manual</li>\n	<li id="bundle-v2-btf-component-bullet-point-2-6">[PC Software Control] The LibreVNA needs to be used with the host computer software and a separate screen, as it does not have a built-in monitor. LibreVNA provides software for the Windows and Ubuntu platforms. You just need to download and unzip it to run. Supported Operating System: Windows, Linux, MacOS. (Only 64-bit software is available for now)</li>\n	<li id="bundle-v2-btf-component-bullet-point-2-7">[Packing List] 1x LibreVNA host, 1x USB type-C data cable, 1x USB power cable, 2x 20cm SMA male to male SS405 RF cable, 1x SMA male calibration kit - OPEN, 1x SMA male calibration kit - SHORT, 1x SMA male calibration kit - LOAD, 2x SMA female to female connector, 2x SMA male to male connector, 1x English manual. The LibreVNA is highly functional and capable of meeting the demands of RF engineers, researchers, or hobbyists for a wide range of RF measurements and microwave network parameter measurement.</li>\n	<li><cms-plugin alt="Picture / Image - Image (17894) " title="Picture / Image - Image (17894)" id="17894"></cms-plugin></li>\n	<li><cms-plugin alt="Picture / Image - Image (17895) " title="Picture / Image - Image (17895)" id="17895"></cms-plugin></li>\n	<li><cms-plugin alt="Picture / Image - Image (17896) " title="Picture / Image - Image (17896)" id="17896"></cms-plugin></li>\n	<li> </li>\n	<li> </li>\n</ul>','\n',char(10)),17893);
INSERT INTO djangocms_text_ckeditor_text VALUES(replace('<ul>\n	<li>LibreVNA is a open-source hardware, USB based full 2-port vector network analyzer (VNA) designed by Jankae, provides a 100kHz to 6GHz ultra-wide frequency range. Updated 6-layer PCB design that optimizes S12 port isolation and high-frequency port matching. Supports firmware update and can load a new microcontroller firmware and FPGA configuration into the LibreVNA</li>\n	<li>[Comparable to Lab-grade Nano VNA] The ultra-low noise power supply design and the use of 16bit ADC, together with the precision CNC''s aluminum shielded housing, achieve up to 100dB of effective dynamics. Using 3 ADCs to sample data simultaneously and using FPGAs for signal processing.</li>\n	<li>[Full S-Parameters Measurements] In the LibreVNA operating mode, the VNA can measure the complete S11, S21, S12 and S21 parameters. A source signal is generated and alternately applied to the RF ports. This incoming signal at both RF ports is measured, resulting in the four S-parameters S11 and S21(when signal routes to Port 1), as well as S12 and S22(when signal routes to Port 2)</li>\n	<li>\n	<p>You can buy from <a href="https://item.taobao.com/item.htm?ft=t&amp;id=850498267983&amp;spm=a21dvs.23580594.0.0.1d292c1bCF41l9">Taobao LibreLink</a></p>\n\n	<p>You can learn by video from<a href="https://www.youtube.com/@RFTinyEquip-Terry">Youtube Link</a></p>\n	</li>\n</ul>\n\n<p>Price: 3290 RMB (excluding tax)</p>','\n',char(10)),17907);
INSERT INTO djangocms_text_ckeditor_text VALUES(replace('<ul>\n	<li id="bundle-v2-btf-component-bullet-point-1-1">[Frequency range] Supports a wide range of frequency measurements from 100kHz to 6GHz, upgraded Frequency Accuracy is &lt;2ppm. The S12 can achieve over 90dB of port isolation below 3GHz, allowing measurements above 6GHz use harmonics. During up to 9GHz actual tests, both S11 and S22 have more than 10dB port directivity, and S12, S21 have more than 40dB dynamics</li>\n	<li id="bundle-v2-btf-component-bullet-point-1-4">[Full S-Parameters Measurements] In the LibreVNA operating mode, the VNA can measure the complete S11, S21, S12 and S21 parameters. A source signal is generated and alternately applied to the RF ports. This incoming signal at both RF ports is measured, resulting in the four S-parameters S11 and S21(when signal routes to Port 1), as well as S12 and S22(when signal routes to Port 2)</li>\n	<li id="bundle-v2-btf-component-bullet-point-1-5">[3 In 1 Device] Although the VNA hardware is not designed to be used as spectrum analyzer and signal generator, the general hardware architecture of a spectrum analyzer and signal generator are similar enough to that of a VNA to implement basic spectrum measurements and output a CW signal, which might suffice if no other equipment is available. The main differences to a real spectrum analyzer and signal generator please refer to the product manual</li>\n	<li id="bundle-v2-btf-component-bullet-point-1-6">[PC Software Control] The LibreVNA needs to be used with the host computer software and a separate screen, as it does not have a built-in monitor. LibreVNA provides software for the Windows and Ubuntu platforms. You just need to download and unzip it to run. Supported Operating System: Windows, Linux, MacOS. (Only 64-bit software is available for now)</li>\n	<li id="bundle-v2-btf-component-bullet-point-1-7">[Packing List] 1x LibreVNA host, 1x USB type-C data cable, 1x USB power cable, 2x 30cm SMA male to male SS405 RF cable, 1x SMA male calibration kit - OPEN, 1x SMA male calibration kit - SHORT, 1x SMA male calibration kit - LOAD, 2x SMA female to female connector, 2x SMA male to male connector. The LibreVNA is highly functional and capable of meeting the demands of RF engineers, researchers, or hobbyists for a wide range of RF measurements and microwave network parameter measurements</li>\n</ul>\n\n<p> </p>\n\n<p><strong>Because LibreVNA is relatively complex to operate, you can get professional remote meeting support and explanation after purchasing the product!</strong></p>\n\n<p><strong>The latest hardware has been upgraded to support V1.6.2 Firmware and GUI.</strong></p>\n\n<p> </p>\n\n<p>We and <strong>Jankae</strong> jointly developed <strong>LibreVNA</strong>.Based on the latest <strong>LibreVNA</strong> hardware design, we have spent more time and effort optimizing the impedance control and stacking control between <strong>6</strong>-layer boards to achieve better high-frequency isolation. First-class product quality, but also need first-class professional service, after all, the equipment is not used is the biggest waste need to understand the use of <strong>LibreVNA</strong>, please move to station BiLiBiLi, you will learn:</p>\n\n<p> </p>\n\n<div style=""><span style=""><span style="unicode-bidi: embed;"><span style=""><span style="">1. After unboxing, the adjustment and adaptation process of LibreVNA''s host computer software </span></span></span></span><span style=""><span style="unicode-bidi: embed;"><span style=""><span style="">and firmware. (very important)</span></span></span></span></div>\n\n<div style=""><span style=""><span style="unicode-bidi: embed;"><span style=""><span style="">2. How to use LibreVNA GUI 1.5.0.</span></span></span></span></div>\n\n<div style=""><span style=""><span style="unicode-bidi: embed;"><span style=""><span style="">3. Calibration method of LibreVNA: calibration method without wire and with wire.</span></span></span></span></div>\n\n<div style=""><span style=""><span style="unicode-bidi: embed;"><span style=""><span style="">4. How LibreVNA measures antennas and attenuators and adjusts antenna matching in com-</span></span></span></span><span style=""><span style="unicode-bidi: embed;"><span style=""><span style="">bination with Keysight ADS.</span></span></span></span></div>\n\n<div style=""><span style=""><span style="unicode-bidi: embed;"><span style=""><span style="">5. LibreVNA program automation test process and method.</span></span></span></span></div>\n\n<div style=""> </div>\n\n<p><strong>All professional video training materials are available in the TinyRFEquip account of Bilibili, hoping to be able to connect three times with one click. Related firmware, GUI, operation instructions, circuit diagrams, software control programs, all in Baidu cloud disk and mobile cloud disk.</strong></p>\n\n<p> </p>\n\n<p>Google Cloud Drive</p>\n\n<p>https://drive.google.com/drive/folders/1YZBoOaVeXCeArZZNnu49Q4pUKuTufpCc?usp=sharing</p>\n\n<p>About warranty: Precision equipment is not man-made damage, signed and collected, and the physical warranty is one year.</p>\n\n<p>Customer site test diagram:<cms-plugin alt="Picture / Image - Image (17914) " title="Picture / Image - Image (17914)" id="17914"></cms-plugin></p>\n\n<p><cms-plugin alt="Picture / Image - Image (17915) " title="Picture / Image - Image (17915)" id="17915"></cms-plugin></p>\n\n<p><cms-plugin alt="Picture / Image - Image (17916) " title="Picture / Image - Image (17916)" id="17916"></cms-plugin></p>\n\n<p><cms-plugin alt="Picture / Image - Image (17917) " title="Picture / Image - Image (17917)" id="17917"></cms-plugin></p>\n\n<p><cms-plugin alt="Picture / Image - Image (17918) " title="Picture / Image - Image (17918)" id="17918"></cms-plugin></p>\n\n<p><cms-plugin alt="Picture / Image - Image (17919) " title="Picture / Image - Image (17919)" id="17919"></cms-plugin></p>','\n',char(10)),17913);
INSERT INTO djangocms_text_ckeditor_text VALUES(replace('<p>TinyRFSG is a signal generator independently developed by our store, which supports a transmission frequency range of 20MHz~6GHz and can transmit a minimum signal of -60dBm; The maximum transmission amplitude reaches+15dBm (frequency range 20MHz~3GHz). And the power accuracy of this signal source is good, basically stable within 2dB.</p>\n\n<p>This signal source is compact in size and can be carried around. Control the launch settings with the upper computer software, and also support pre configuration of all functions, which can run independently without the upper computer. And it is far superior to similar products on the market in various parameters, and can be used as a calibration source.</p>\n\n<p><a href="https://item.taobao.com/item.htm?id=851786764090&amp;pisk=gEuIqPMfi9XI8i4RNkAaGo46oe47PC8qe_N-ibQFwyULe_MtwMBL2JQT6SF72a-38uaSBRuULXzLFzGmhvyU4Mo1NjDsFuA3U8eSUbne_E8qtX4uy492uEz-5NNKdMELyQETTWda9ZQHYRauyKJVbaEHlzDKvoZVvGFTI7NRJuHRWGFYB7FL2YeTXSFVpzH-ePhTMW_8ekFRBCN3GWBdy7BOXSVR98H8yCZTZRe8ykH-6b3dR5RQIXO347YvNpKJLJ_RyVNQXhlLBr4Ja5EIuXw6HNg1okwx9R_JpmKs78wikd-ssYmKL5DWldaoI0H8NAB9Ukc-fANILK6uU2cEP5cCgZc_VJitJl1RyfUQCxiSdps3pDk_m5EONEVZ3RhnJcOlBXH4dyFTbEdj6unZ-o0eBwaxmXzE2YxVjyG-vPszNZyfyXj51ob71-R61gjua-X-T6YNC7ELs5Jy1CsqZkFg1-R61gjuv5VZTCO10bf..&amp;spm=a21xtw.29978516.0.0">Purchase link：TinyRFSG High precision RF signal source 20M-6.3GHz peogrammable 1Hz stepper</a></p>\n\n<p>Price: 2500 RMB (excluding tax)</p>','\n',char(10)),17930);
INSERT INTO djangocms_text_ckeditor_text VALUES(replace('<p>The TinyRFSG, which is completely independently developed by our store, is the world''s first. Before designing this product, the owner had already purchased various portable signal sources and small desktop signal sources on Taobao. However, they found that these signal sources had inaccurate first power (i.e. without real calibration), second input power amplitude that did not meet the standards stated in the instructions, poor third frequency step accuracy, often ranging from 1KHz to 10KHz, and too many harmonics. The second and third harmonics were basically not suppressed by filters, so square waves were used for counting.</p>\n\n<p>As an engineer, I also need an excellent portable, pocket signal source. My requirement for my own signal source is accurate power: it can easily calibrate other spectrometers; Good harmonic suppression: pure signal; Strong output capability: Try to achieve a maximum output of 15dBm. Of course, as the frequency increases, the output power will decrease, but I will also tell the customer where my limit is; Portable: compact, strong anti-interference ability, suitable for pocket use.</p>\n\n<p>At the same time, as it is our own research and development, we accept customized hardware and upper computer requirements from customers. Specific issues can be discussed in detail. At present, it only supports power supply on the computer side, and the computer software is controlled through the VISA interface.</p>\n\n<p><cms-plugin alt="Picture / Image - Image (17937) " title="Picture / Image - Image (17937)" id="17937"></cms-plugin></p>\n\n<p><cms-plugin alt="Picture / Image - Image (17938) " title="Picture / Image - Image (17938)" id="17938"></cms-plugin></p>','\n',char(10)),17936);
INSERT INTO djangocms_text_ckeditor_text VALUES(replace('<p>This NanoVNA-F V3 vna analyzer is a new production machine , with 4.3 inch 800 x 480 large touchscreen display, 1MHz to 6GHz widely measuring range, the scan speed of NanoVNA-F V3 is up to 200 points/s and the maximum scanning points is up to 801.In addition, the nanovna analyzer supports TDR function which is useful for cable lengths measurement.</p>\n\n<p>Compared to the Nanovna-F V2 (50kHz-3GHz), the upgraded Nanovna-F V3 has 1MHz-6GHz ultra-wide measuring frequency range, The S21 dynamic range of NanoVNA-F V3 is 65 dB, while the S11 dynamic range is 50 dB. The scan points is up to 101-801 and the calibration result storage is 12, covering up to the full low or high frequency range. Faster and more accurate measurement performance, you can easily cope with measurement testes in various fields.</p>\n\n<p>This nano vna analyzer measuring tool is made of metal material, which is durable and can effectively shield electromagnetic interference. With SMA connector design which can be used to connect DUTs directly.In addition,it is support PC Software control and compatible with NanoVNA-Saver for convenient measurement data transfer.Built-in 4500m-ah rechargeable battery,with type-C charging cable and LED charging indicator,it can be fully charged within 3 hours,no need to charge frequently.</p>\n\n<p><a href="https://item.taobao.com/item.htm?id=808249048405&amp;pisk=gsf-2cftQoqlq6fJoaymKdxnwGUcJ-bzkg7stHxodiIARgtkxUGWhnTM50T5RHAdvMIpqpZyZ6IAAMhhE_AkdWtAVXvl9wlpRwsUzH4zna7yTBZgjlVGza7HDdoCwYMjGZ8KADwDFViDeHrgj5VgFqOL2lj3ydHKlFL6OU9BVKavSFmWOp9IlrLB-0MINMaYkeYIV4tBOIMX5niBAX9BlSTe5DGBOUaAln8eOHsBFrQjZZwvYYti9Oy2FvZj7W15MsLJeh_YQXGLfemMYa6i9XK87Lt_snhIOsLRJEHfrfeHfO-kIHjbibddleIkmGNsMI9OQwYd27hWZt6VaQf0XDvJg391dKU7NZdJ2dCWeWEWw9sP9LW-8P7XNiWwbLw40EClspKwHmZ5oZKWB9Iu0XtlBZsvIsmmsBSVdMTdc0Iz81fOnKiMXeD7krHELLT2QEjBluCMKDTvjrYoLvJY3EKgkrHELLT2kh4mxvkeH-5..&amp;spm=a21xtw.29978516.0.0&amp;skuId=5659210298993">Purchase link：NanoVNA V3 1M-6.3GHz network analyzer Antenna filter VSWR impedance RFID measure</a></p>\n\n<p>Price: 1300 RMB (excluding tax)</p>','\n',char(10)),17985);
INSERT INTO djangocms_text_ckeditor_text VALUES(replace('<p>NanoVNA-F V3 is a Portable Vector Network Analyzer (VNA) with frequency range of 1MHz~6GHz. It can be used for S11 and S21 measurements. The S21 dynamic range of NanoVNA-F V3 is 65 dB, while the S11 dynamic range is 50 dB.</p>\n\n<p>NanoVNA-F V3 antenna analyzer is suitable for antenna testing of MF/HF/VHF/UHF/SHF bands. Supports a variety of display formats: Log Mag, Linear Mag, Phase, Smith R+jX, Smith R+L/C, VSWR, Polar, Group delay, Resistance, Reactance, etc. It can also be used to measure filters, amplifiers, attenuators, cables, power dividers, couplers, duplexers and other RF components. For the amateur radio operator or radio enthusiast, this latest vna antenna analyzer will be a very handy analyzer to have.</p>\n\n<p>After optimizing the RF design in our store, the NanoVNA-F V3 uses an independent local oscillator generation chip instead of the harmonic components commonly used in most imitations as a cheap option for local oscillator signals. Additionally, the customized all metal casing and high-quality SMA connector can support customers for longer use and better external shielding performance.</p>\n\n<p>Especially the factory has perfectly calibrated the S21 performance of 3G-6G, far exceeding LiteVNA. It can conveniently monitor power dividers, combiners, filters, attenuators, antennas, cables, amplifiers, mixers, duplexers, couplers, isolators, circulators, adapters, waveguides, differential devices, etc.<br>\nCommon testing functions include: TDR cable connection, standing wave ratio, return loss, insertion loss, flatness, out of band suppression, attenuation, gain, isolation, characteristic impedance, input-output impedance, phase, delay, and 1dB compression point.</p>\n\n<p><b> Features:</b><br>\nFrequency range: 1MHz-6GHz<br>\nS21 dynamic range: 65dB and S11 dynamic range: 50dB<br>\n4.3" high-brightness IPS display with resistive touch panel<br>\nMetal case can effectively shield electromagnetic interference<br>\nSMA connector is stable and durable to use<br>\nFull touch screen and 3 physical buttons enable convenient and smooth operation<br>\nDimensions: 125 x 75 x 20mm/4.9 x 3 x 0.8"<br>\nBuilt-in 4500mAh lithium-ion batteries with endurance time up to 5 hours<br>\nTDR function can be used to measure cable length<br>\nUp to 4 reference traces<br>\nUp to 4 markers, and the marker table can be dragged to anywhere on the screen<br>\n12 save/recall slots<br>\nCharging via USB Type-C, and the charging voltage is 5V DC<br>\nDesigned with a 5V/1A USB power output port<br>\nFirmware upgrade via virtual U disk with USB Type-C cable<br>\nComes with SMA calibration kit and 2 x 20cm/7.9" SMA-JJ RG405 coaxial cable<br>\nSupports console commands and PC software</p>\n\n<p> </p>\n\n<p><cms-plugin alt="Picture / Image - Image (17994) " title="Picture / Image - Image (17994)" id="17994"></cms-plugin></p>\n\n<p><cms-plugin alt="Image - 17993 " title="Image - 17993" id="17993"></cms-plugin><cms-plugin alt="Picture / Image - Image (17995) " title="Picture / Image - Image (17995)" id="17995"></cms-plugin></p>\n\n<p><cms-plugin alt="Image - 17992 " title="Image - 17992" id="17992"></cms-plugin></p>\n\n<p> </p>','\n',char(10)),17991);
INSERT INTO djangocms_text_ckeditor_text VALUES(replace('<p>LiteVNA-64 improves on the popular NanoVNA and SAA2. Now you can get a portable vector network analyzer (VNA) as small as the NanoVNA and capable of meeting the ultra-wide measurement range of 50 kHz to 6.3 GHz.<br>\n<br>\nTo minimize power consumption and size, the LiteVNA-64 uses only one frequency mixer, with multiple internal RF switches for S11 and S21 measurements, and IFFT calculations for TDR and DTF measurements.<br>\n<br>\nDesigned with the community''s input in mind, the LiteVNA-64 now brings faster scanning speeds and more scan points in addition to a wider measurement range. Combined with an easy-to-use interface consistent with the NanoVNA, it can now be easily used as a field test tool.<br>\n<br>\nLiteVNA-64 includes a MicroSD slot, so you can save field test data or screens to a MicroSD card at any time. With a measurement range of up to 6.3GHz, the LiteVNA-64 is capable of meeting common amateur radio and IoT applications, as well as emerging 5GHz testing, enabling the application of the latest 5.8GHz wifi and 5.8GHz image transmission.</p>\n\n<p><a href="https://item.taobao.com/item.htm?id=755371705235&amp;pisk=gmQK2a_x0R23k-_ps6riqnvoJtFMJlfU695jrLvnVOBON99HEBgBfdODGvOCNLYReTBJK3we-aBOFT3lxwYHVz9Od4xhy_uJN_6zTLVUj65ezUw0n-4cT65kBnk5JBTsC1RmRXZMAjMMvLy0nr40AfT8p-Xu9dKs1IdXPBtWdhN9iIDBP39B55dWZviSRTNT6QASdX9WPFi6GdMIAB9ICFOXNDOWdBNO1dRWPL6WA5CsZKE9UD9myirwA0wsy2sf2NdpvK1T04g-cIHDC6tty4pLgH9bod3SPNddwCn1tqEkhiJHmLX_S2LR1QBHItajWFtA0_ARpy3B-GsN8ebgHYxp7ptfVhFQR1LppnQBvzeBJg6FyHSKaS56ROS23HZaQCQho3p2XAwCs1pBDgB3Q49hD169mNDioUWNVTORCvIyTZbAjhMDHQmQ65nr4HOw0CXW1JQDqYO9n5An40-TbCp065nr4HOw6KViE0oyXl5..&amp;skuId=5207120012805&amp;spm=a21xtw.29978516.0.0">Purchase link：LiteVNA vector network analyzer 50k-6.3G Antenna Cable Impedance matching measure filter</a></p>\n\n<p>Price: 899 RMB (excluding tax)</p>','\n',char(10)),18006);
INSERT INTO djangocms_text_ckeditor_text VALUES(replace('<p>We have updated LiteVNA-64 to version 0.3.1, redesigned the power supply and IF circuit, greatly reduced noise floor and completely solved interference when it is connected to an external power supply. Below 1MHz-3GHz frequencies, effective dynamics of better than 90dB can be obtained with 20AVG. Above 3 GHz, the limited isolation is reduced. The effective dynamic reduction is reduced to 50dB at 6.3GHz. Compared to similar products, LiteVNA-64 has a wider frequency measurement range and an effective dynamic range. Furthermore, it is more light and reliable!</p>\n\n<p>Because the design of LiteVNA evolved from NanoVNA, it not only has a wider measurement range, but also has faster scanning speed and more scanning points. It has an easy-to-use interface consistent with NanoVNA, and all control software compatible with NanoVNA, such as TinyRFeqipApp, Nano_Spp, and NanoVNA saver, can be perfectly matched with LiteVNA. Now, LiteVNA can be easily used as a testing tool for on-site and remote control.</p>\n\n<p>Affected by the current tight chip supply, we still hope that LiteVNA series is an affordable device for hobbyists and startups. The 0.3.1 version of the LiteVNA-64 is currently in short supply.</p>\n\n<p><b>Package Included:</b><br>\n- 1 x LiteVNA-64 Main Unit (with 3.95-inch touch screen and 2000mAh battery)<br>\n- 2 x 30cm/11.8" SMA Male to Male SS405 RF Cables<br>\n- 1 x SMA Female-to-Female Connector<br>\n- 1 x SMA Simple Calibration Kit SHORT<br>\n- 1 x SMA Simple Calibration Kit OPEN<br>\n- 1 x SMA Simple Calibration Kit LOAD<br>\n- 1 x USB Type-C Data Cable<br>\n- 1 x Pick</p>\n\n<p><cms-plugin alt="Picture / Image - Image (18013) " title="Picture / Image - Image (18013)" id="18013"></cms-plugin></p>\n\n<p><cms-plugin alt="Picture / Image - Image (18014) " title="Picture / Image - Image (18014)" id="18014"></cms-plugin></p>','\n',char(10)),18012);
INSERT INTO djangocms_text_ckeditor_text VALUES(replace('<p>H-Field E-Field PROBE EMC EMI Near Field Probe Conducted Radiation Rectification Simple Magnetic Field Probe</p>\n\n<p>Operating frequency: 9K-3G;</p>\n\n<p>Size: 73mm X 24mm (excluding connectors)</p>\n\n<p>Weight: 3.4 g</p>\n\n<p>Connector: SMA Female Head</p>\n\n<p><a href="https://item.taobao.com/item.htm?id=777091447381&amp;pisk=g7Uoq6ACXuo7ZMBxDrg5jHCuGPjYw4gI3JLKp2HF0xkXyJ3-JEJqtXty8UozmXyLh61SyWk3K-Hby_MdNp23t7mUpvFJNowT_UURV2LnP2gFBOQOWbNSR2l-45TeNqlns37KUYkqPXCyFBXlW7NSRQvF6o79tEj1Tp-ELJuq0XlK83lezsmqTf0ezD8y0Kkj32lr8U7qgXGHYLyezKJqObcy8v8r3IlK3vuEUJPViXHqLbV6gYeUFrWXPVfhIj5pKjooQ7kDSSama3MP5A8eErlui1VonjhYobmoQDlaQXazHWz8PmsJV2NYjJqUdGKjrWrrzfF5rE0aaoUnMyCpxYPYoDUomL-rs4Dobzo2TFuqYo4myzWBfSFmUc0YDi6-v42ufAiPctw3iYeUrmJlHvETMzo0QtL0dDq_9X2lrUyN4q-2bRbwRj5LuHtI4jGmBG_jMsZYyfOlisxaf0ljaNCciHtI4jGmBsfDbsirGb7O.&amp;spm=a21xtw.29978516.0.0">Purchase link：H-FIELD E-FIELD PROBE EMC EMI Near field probe conducts radiation magnetic field electric field probe</a></p>\n\n<p>Price: Five per set, 60 RMB (excluding tax)</p>','\n',char(10)),18025);
INSERT INTO djangocms_text_ckeditor_text VALUES(replace('<p>This product set includes 4 H-Field probes, which are magnetic field probes. The main function of the magnetic field probes is to detect changes in voltage and radiation.</p>\n\n<p>One E-field, also known as an electric field probe, mainly detects changes in current and radiation.</p>\n\n<p>This product is widely used for EMC and EMI testing, and of course, it can also measure wireless signals near the emission source. The video shows monitoring the key signal of a Honda CRV.</p>\n\n<p>When using, do not touch the PCB board with your hands！！！</p>\n\n<p>Magnetic field probe 1-4</p>\n\n<p><cms-plugin alt="Picture / Image - Image (18032) " title="Picture / Image - Image (18032)" id="18032"></cms-plugin></p>\n\n<p><cms-plugin alt="Picture / Image - Image (18033) " title="Picture / Image - Image (18033)" id="18033"></cms-plugin></p>\n\n<p><cms-plugin alt="Picture / Image - Image (18034) " title="Picture / Image - Image (18034)" id="18034"></cms-plugin></p>\n\n<p><cms-plugin alt="Picture / Image - Image (18035) " title="Picture / Image - Image (18035)" id="18035"></cms-plugin></p>\n\n<p>Electric field probe</p>\n\n<p><cms-plugin alt="Picture / Image - Image (18036) " title="Picture / Image - Image (18036)" id="18036"></cms-plugin></p>','\n',char(10)),18031);
INSERT INTO djangocms_text_ckeditor_text VALUES(replace('<ul>\n	<li>Covering commonly used RF connectors, with a complete range of types.</li>\n	<li>After rigorous testing, the performance is guaranteed.</li>\n	<li>Material selection, good durability</li>\n</ul>\n\n<p><a href="https://item.taobao.com/item.htm?id=813704560920&amp;pisk=giVS2_Z6S3xSwmGpRYbq5Acfs_cIPZ5avegLSydyJbh-veZYJLK-p0dxkV3IpBWoavGQDmPr4zl-AXagfuorLLyXRPqbAvboYDnQYyePu15arzcn9WsN_1lLGIg8VBdJew3xJ2bqyCdlUmGn9GSw3BHl1Xq8eKMw9K3xm2gpwvEpMK3tD2dK2knxHV3w2XELvjUxW4OKvY3pDZgoRQK-9DdvH20SJDEK9ZOxm2hKykhKZwOSuai0PaDE-1QBLBdi2BdLG4MA3znxcD_E-YG0Pmst8S3WjcU-cBdKfDQb-raPVC4qZWqs7u5vNlagiogYX6sjto2Lv2ZAsHluQuVihuWOYrhSRAhKhedLlbnSp4GO6ng0HzyLZuTB94Vz_viihwdnLjFZBREW-N4xw2EnIWSMZ0ULS52Z1sJ-6rwLfJsyVCo69zvBlAAIlc7flpvn8cxLzUf2c2H-oqSFlZ9a-Y3mlc7flpvneq04zZ_XQyf..&amp;skuId=5653129272399&amp;spm=a21xtw.29978516.0.0">Purchase link：KX-01 RF ToolKit suit_SMA_N-Type_BNC_M Adapter_Admission documents</a></p>\n\n<p> </p>','\n',char(10)),18047);
INSERT INTO djangocms_text_ckeditor_text VALUES(replace('<p>There are a wide variety of RF connectors, making them extremely difficult to carry. RF enthusiasts and engineers often lose them due to poor storage. As a senior RF engineer, the shop owner shares the same feeling, so he designed this RF ToolKit. The ToolKit is exquisite, compact, and very easy to carry. On the basis of ensuring the 0-6G frequency coverage of all adapters, the carefully selected connector materials ensure the durability of the connectors. At the same time, advanced industrial plastics are used to make a sealed and waterproof storage box, which is very durable. It can be used as a gift for other RF engineers, please feel free to use it.</p>\n\n<p>RF adapter ToolKit product list (standard version)<br>\nThe size of KX-01ToolKit toolbox is 223 × 158 × 42mm<br>\nN female head straight through x 1<br>\nN-head straight through x 1<br>\nN male head to female head x 1<br>\nSMA male head straight through x 1<br>\nSMA female head straight through x 1<br>\nSMA male head to female head x 1<br>\nSMA male head to N female head x 1<br>\nSMA male head to N male head x 1<br>\nSMA female head to N female head x 1<br>\nSMA female head to N male head x 1<br>\nBNC male head to SMA female head x 1<br>\nBNC female head to SMA male head x 1<br>\nCalibration parts for N-terminal vector network analyzer (open × 1, short × 1, load × 1)<br>\nSMA Head Vector Network Analyzer Calibration Parts (open × 1, short × 1, load × 1)<br>\nSMA isolated by 1</p>\n\n<p> </p>\n\n<p>RF adapter ToolKit product list (no network calibration part version)<br>\nThe size of KX-01 ToolKit toolbox is 223 × 158 × 42mm<br>\nN female head straight through x 1<br>\nN-head straight through x 1<br>\nN male head to female head x 1<br>\nSMA male head straight through x 1<br>\nSMA female head straight through x 1<br>\nSMA male head to female head x 1<br>\nSMA male head to N female head x 1<br>\nSMA male head to N male head x 1<br>\nSMA female head to N female head x 1<br>\nSMA female head to N male head x 1<br>\nBNC male head to SMA female head x 1<br>\nBNC female head to SMA male head x 1<br>\nSMA isolated by 1</p>\n\n<p> </p>\n\n<p>RF Adapter ToolKit Product List (Upgraded Version)<br>\nThe size of KX-01 ToolKit toolbox is 22315842 mm</p>\n\n<p>N female head straight through 1<br>\nN-head straight through 1<br>\nN male head to female head 1<br>\nSMA male head straight through 1<br>\nSMA female head straight through 1<br>\nSMA male head to female head 1<br>\nSMA male head to N female head 1<br>\nSMA male head to N male head 1<br>\nSMA female head to N female head 1<br>\nSMA female head to N male head 1<br>\nBNC male head to SMA female head 1<br>\nBNC female head to SMA male head 1<br>\nSMA Straight 1<br>\nSMA Head Vector Network Analyzer Calibration Parts: (Supports up to 6G)   open1, short1, load1<br>\nCalibration parts for N-head vector network analyzer: (Upgraded version can support up to 8.5G, suitable for R&amp;S and related products from KeySight)  open1、short1、load1</p>','\n',char(10)),18053);
INSERT INTO djangocms_text_ckeditor_text VALUES(replace('<h5>Global customers can learn and purchase the instruments you need online on Taobao. Taobao is the largest online trading platform in China.<br>\nPlease identify our authentic authorized store TinyRFLab </h5>\n\n<h5>You can buy from <span style=""><span style="unicode-bidi: embed;"><span style=""><span style=""><span style="font-variant: normal;"><span style="letter-spacing: 0pt;"><span style=""><span style="font-weight: normal;"><span style="font-style: normal;"><span style="vertical-align: baseline;"><a href="https://shop57235471.taobao.com/">TinyRFlab</a></span></span></span></span></span></span><span style="font-variant: normal;"><span style="letter-spacing: 0pt;"><span style=""><span style="font-weight: normal;"><span style="font-style: normal;"><span style="vertical-align: baseline;"><a href="https://shop57235471.taobao.com/"> </a></span></span></span></span></span></span><span style="font-variant: normal;"><span style="letter-spacing: 0pt;"><span style=""><span style="font-weight: normal;"><span style="font-style: normal;"><span style="vertical-align: baseline;"><a href="https://shop57235471.taobao.com/">(taobao.com)</a></span></span></span></span></span></span></span></span></span></span></h5>\n\n<h5><span style=""><span style="unicode-bidi: embed;"><span style=""><span style=""><span style="font-variant: normal;"><span style="letter-spacing: 0pt;"><span style=""><span style="font-weight: normal;"><span style="font-style: normal;"><span style="vertical-align: baseline;">If you have any questions about equipment or technology, please consult email: <a href="mailto:14025259@qq.com">14025259@qq.com</a></span></span></span></span></span></span></span></span></span></span></h5>\n\n<h5 class="O0" style=""><span style=""><span style="unicode-bidi: embed;"><span style=""><span style=""><span style="">We have tutorial videos about instruments on YouTube. If you have any other questions, you can also send them directly via private message</span></span></span></span></span></h5>\n\n<h5 class="O0" style=""><span style=""><span style="unicode-bidi: embed;"><span style=""><span style=""><span style="">Youtube: </span></span></span></span></span><cms-plugin alt="Link / Button - Link (18071) " title="Link / Button - Link (18071)" id="18071"></cms-plugin></h5>\n\n<h5 class="O0" style=""> </h5>\n\n<div class="O0" style="">\n<h5 style="text-align: justify;">Welcome to the website of Tiny RF Equipment, which covers and introduces many miniature and efficient RF microwave testing equipment, components, and related RF modules. These products are mainly used to meet the basic needs of wireless product testing, amateur radio testing enthusiasts, and students'' learning needs. This is a free and open website, hoping to communicate with everyone more professionally and quickly about RF professional issues. The products here strive to achieve the maximum economic input-output ratio for customers.</h5>\n\n<h5 style="text-align: justify;">At the same time, our studio engineers are proficient in RF instruments related to Keysight, Rod, and Anli, providing online and on-site training and consultation. For more information, please contact us directly on Taobao or email.The most important thing in purchasing equipment is the performance and technical support of the equipment itself. as an old engineer of RF, I hope to provide customers with professional consulting services.</h5>\n</div>\n\n<div class="O0" style=""> </div>\n\n<div class="O0" style=""> </div>','\n',char(10)),18070);
